package main

// Pandoc AST types - internal representation

type Doc struct {
	Meta   map[string]MetaVal
	Blocks []Block
}

type MetaVal struct {
	Type    string // "MetaInlines", "MetaString", "MetaList", "MetaMap", "MetaBool", "MetaBlocks"
	Inlines []Inline
	Str     string
	Bool    bool
	List    []MetaVal
	Map     map[string]MetaVal
	Blocks  []Block
}

type Block struct {
	Type     string
	// Header
	Level    int
	Attr     Attr
	Inlines  []Inline
	// Para, Plain, BlockQuote
	Blocks   []Block
	// CodeBlock, RawBlock
	Code     string
	Format   string
	// BulletList, OrderedList
	Items    [][]Block
	// OrderedList
	ListAttr ListAttr
	// HorizontalRule - no fields
	// Table
	Table    *TableData
	// Div
	// DefinitionList
	DefItems []DefItem
	// LineBlock
	Lines    [][]Inline
}

type Attr struct {
	ID      string
	Classes []string
	KVPairs [][2]string
}

type ListAttr struct {
	Start     int
	Style     string // Decimal, LowerAlpha, UpperAlpha, LowerRoman, UpperRoman, Example, DefaultStyle
	Delimiter string // Period, OneParen, TwoParen, DefaultDelim
}

type DefItem struct {
	Term []Inline
	Defs [][]Block
}

type TableData struct {
	Caption  Caption
	ColSpecs []ColSpec
	Head     TableHead
	Bodies   []TableBody
	Foot     TableFoot
}

type Caption struct {
	Short  []Inline
	Blocks []Block
}

type ColSpec struct {
	Align string
	Width float64 // 0 means default
}

type TableHead struct {
	Attr Attr
	Rows []TableRow
}

type TableBody struct {
	Attr     Attr
	RowHead  int
	HeadRows []TableRow
	Rows     []TableRow
}

type TableFoot struct {
	Attr Attr
	Rows []TableRow
}

type TableRow struct {
	Attr  Attr
	Cells []TableCell
}

type TableCell struct {
	Attr    Attr
	Align   string
	RowSpan int
	ColSpan int
	Blocks  []Block
}

type Inline struct {
	Type      string
	// Str, Code, RawInline, Math
	Text      string
	// Inlines - for Emph, Strong, Strikeout, Superscript, Subscript, SmallCaps, Span, Note content
	Inlines   []Inline
	// Attr for Code, Span, Link, Image
	Attr      Attr
	// Link, Image
	Target    Target
	// Math type
	MathType  string // InlineMath or DisplayMath
	// RawInline format
	Format    string
	// Note
	Blocks    []Block
	// Cite
	Citations []Citation
	// Quoted
	QuoteType string // SingleQuote or DoubleQuote
	// SoftBreak, LineBreak, Space - no fields
}

type Target struct {
	URL   string
	Title string
}

type Citation struct {
	ID      string
	Prefix  []Inline
	Suffix  []Inline
	Mode    string // NormalCitation, SuppressAuthor, AuthorInText
	NoteNum int
	Hash    int
}

func emptyAttr() Attr {
	return Attr{ID: "", Classes: []string{}, KVPairs: [][2]string{}}
}

func (a Attr) hasClass(c string) bool {
	for _, cl := range a.Classes {
		if cl == c {
			return true
		}
	}
	return false
}
