func (p *MdParser) parse(input string) *Doc {
	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	// Normalize line endings
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")

	// Parse YAML front matter if present
	remaining := p.parseYAML(input, doc)

	// First pass: collect reference definitions
	remaining = p.collectRefs(remaining)

	// Parse blocks
	doc.Blocks = p.parseBlocks(remaining)

	return doc
}

func (p *MdParser) parseYAML(input string, doc *Doc) string {
	if !strings.HasPrefix(input, "---\n") && !strings.HasPrefix(input, "---\r\n") {
		return input
	}

	// Find end of YAML block
	rest := input[4:]
	endIdx := strings.Index(rest, "\n---\n")
	endIdx2 := strings.Index(rest, "\n...\n")

	var yamlContent string
	var remaining string

	if endIdx >= 0 && (endIdx2 < 0 || endIdx <= endIdx2) {
		yamlContent = rest[:endIdx]
		remaining = rest[endIdx+5:]
	} else if endIdx2 >= 0 {
		yamlContent = rest[:endIdx2]
		remaining = rest[endIdx2+5:]
	} else {
		// Check end of string
		endIdxEOF := strings.Index(rest, "\n---")
		endIdxEOF2 := strings.Index(rest, "\n...")
		if endIdxEOF >= 0 || endIdxEOF2 >= 0 {
			if endIdxEOF >= 0 {
				yamlContent = rest[:endIdxEOF]
				remaining = rest[endIdxEOF+4:]
			} else {
				yamlContent = rest[:endIdxEOF2]
				remaining = rest[endIdxEOF2+4:]
			}
		} else {
			return input
		}
	}

	// Parse YAML key-value pairs
	parseSimpleYAML(yamlContent, doc.Meta, p)

	return remaining
}

func parseSimpleYAML(yaml string, meta map[string]MetaVal, p *MdParser) {
	lines := strings.Split(yaml, "\n")
	i := 0
	for i < len(lines) {
		line := lines[i]
		if line == "" || strings.HasPrefix(line, "#") {
			i++
			continue
		}
		// Check for key: value
		if colonIdx := strings.Index(line, ":"); colonIdx > 0 {
			key := strings.TrimSpace(line[:colonIdx])
			val := strings.TrimSpace(line[colonIdx+1:])

			if val == "" || val == "|" || val == ">" {
				// Multi-line value - check for list or block
				var multiLines []string
				i++
				for i < len(lines) && (lines[i] == "" || strings.HasPrefix(lines[i], " ") || strings.HasPrefix(lines[i], "\t")) {
					multiLines = append(multiLines, lines[i])
					i++
				}
				// Process multi-line
				content := strings.Join(multiLines, "\n")
				content = strings.TrimSpace(content)
				if content != "" {
					// Check if it's a list
					if strings.HasPrefix(strings.TrimSpace(multiLines[0]), "- ") {
						var listVals []MetaVal
						for _, ml := range multiLines {
							ml = strings.TrimSpace(ml)
							if strings.HasPrefix(ml, "- ") {
								item := strings.TrimPrefix(ml, "- ")
								item = strings.TrimSpace(item)
								listVals = append(listVals, MetaVal{
									Type:    "MetaInlines",
									Inlines: p.parseInlines(item),
								})
							}
						}
						meta[key] = MetaVal{Type: "MetaList", List: listVals}
					} else {
						meta[key] = MetaVal{
							Type:    "MetaInlines",
							Inlines: p.parseInlines(content),
						}
					}
				}
				continue
			}

			// Check for list value (starts with -)
			if strings.HasPrefix(val, "[") && strings.HasSuffix(val, "]") {
				// Inline list
				inner := val[1 : len(val)-1]
				parts := splitCSV(inner)
				var listVals []MetaVal
				for _, part := range parts {
					part = strings.TrimSpace(part)
					part = strings.Trim(part, `"'`)
					listVals = append(listVals, MetaVal{
						Type:    "MetaInlines",
						Inlines: p.parseInlines(part),
					})
				}
				meta[key] = MetaVal{Type: "MetaList", List: listVals}
			} else {
				// Remove surrounding quotes if present
				if (strings.HasPrefix(val, `"`) && strings.HasSuffix(val, `"`)) ||
					(strings.HasPrefix(val, `'`) && strings.HasSuffix(val, `'`)) {
					val = val[1 : len(val)-1]
				}
				meta[key] = MetaVal{
					Type:    "MetaInlines",
					Inlines: p.parseInlines(val),
				}
			}
		}
		i++
	}
}

func splitCSV(s string) []string {
	var parts []string
	var cur strings.Builder
	inQuote := false
	quoteChar := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQuote {
			if c == quoteChar {
				inQuote = false
			} else {
				cur.WriteByte(c)
			}
		} else if c == '"' || c == '\'' {
			inQuote = true
			quoteChar = c
		} else if c == ',' {
			parts = append(parts, cur.String())
			cur.Reset()
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		parts = append(parts, cur.String())
	}
	return parts
}

func (p *MdParser) collectRefs(input string) string {
	// Find and remove reference definitions like:
	// [ref]: URL "title"
	// [ref]: URL
	refRegex := regexp.MustCompile(`(?m)^\[([^\]]+)\]:\s+(\S+)(?:\s+"([^"]*)"|\s+'([^']*)'|\s+\(([^)]*)\))?\s*$`)

	result := refRegex.ReplaceAllStringFunc(input, func(m string) string {
		matches := refRegex.FindStringSubmatch(m)
		if len(matches) >= 3 {
			key := strings.ToLower(matches[1])
			url := matches[2]
			title := ""
			if len(matches) > 3 && matches[3] != "" {
				title = matches[3]
			} else if len(matches) > 4 && matches[4] != "" {
				title = matches[4]
			} else if len(matches) > 5 && matches[5] != "" {
				title = matches[5]
			}
			p.refs[key] = RefDef{URL: url, Title: title}
		}
		return ""
	})

	return result
}

// parseBlocks parses a string into block elements
func (p *MdParser) parseBlocks(input string) []Block {
	var blocks []Block

	// Split into "paragraphs" - sequences separated by blank lines
	lines := strings.Split(input, "\n")

	var result []Block
	result = p.parseBlockLines(lines)
	blocks = append(blocks, result...)

	return blocks
}

type lineState struct {
	lines []string
	pos   int
}

func (ls *lineState) peek() string {
	if ls.pos >= len(ls.lines) {
		return ""
	}
	return ls.lines[ls.pos]
}

func (ls *lineState) next() string {
	if ls.pos >= len(ls.lines) {
		return ""
	}
	line := ls.lines[ls.pos]
	ls.pos++
	return line
}

func (ls *lineState) done() bool {
	return ls.pos >= len(ls.lines)
}

func isBlankLine(s string) bool {
	return strings.TrimSpace(s) == ""
}

func (p *MdParser) parseBlockLines(lines []string) []Block {
	ls := &lineState{lines: lines}
	var blocks []Block

	for !ls.done() {
		line := ls.peek()

		if isBlankLine(line) {
			ls.next()
			continue
		}

		// Fenced div (:::)
		if isFencedDiv(line) {
			block := p.parseFencedDiv(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// ATX header (# to ######)
		if block := tryATXHeader(line); block != nil {
			ls.next()
			// Parse header attributes
			p.parseHeaderAttr(block)
			block.Inlines = p.parseInlines(block.Code)
			block.Code = ""
			blocks = append(blocks, *block)
			continue
		}

		// Fenced code block
		if isFencedCode(line) {
			block := p.parseFencedCode(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Indented code block (4 spaces or 1 tab)
		if isIndentedCode(line) {
			block := p.parseIndentedCode(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Horizontal rule
		if isHorizontalRule(line) {
			ls.next()
			blocks = append(blocks, Block{Type: "HorizontalRule"})
			continue
		}

		// Block quote
		if strings.HasPrefix(line, "> ") || line == ">" {
			block := p.parseBlockQuote(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Bullet list
		if isBulletListItem(line) {
			block := p.parseBulletList(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Ordered list
		if isOrderedListItem(line) {
			block := p.parseOrderedList(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Definition list
		if isDefinitionList(ls) {
			block := p.parseDefinitionList(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Line block (| prefix)
		if strings.HasPrefix(line, "| ") || line == "|" {
			block := p.parseLineBlock(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// HTML block
		if isHTMLBlock(line) {
			block := p.parseHTMLBlock(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Raw LaTeX block
		if strings.HasPrefix(line, "\\begin{") {
			block := p.parseLaTeXBlock(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Table (pipe table or other)
		if isPipeTable(ls) {
			block := p.parsePipeTable(ls)
			if block != nil {
				blocks = append(blocks, *block)
			}
			continue
		}

		// Collect paragraph lines (including setext header check)
		paraLines := p.collectParaLines(ls)

		// Check for setext header
		if len(paraLines) >= 2 {
			lastLine := paraLines[len(paraLines)-1]
			if isSetextUnderline1(lastLine) {
				headerText := strings.Join(paraLines[:len(paraLines)-1], " ")
				block := &Block{Type: "Header", Level: 1, Attr: emptyAttr()}
				p.parseHeaderAttr(block)
				block.Inlines = p.parseInlines(headerText)
				block.Code = ""
				blocks = append(blocks, *block)
				continue
			}
			if isSetextUnderline2(lastLine) {
				headerText := strings.Join(paraLines[:len(paraLines)-1], " ")
				block := &Block{Type: "Header", Level: 2, Attr: emptyAttr()}
				p.parseHeaderAttr(block)
				block.Inlines = p.parseInlines(headerText)
				block.Code = ""
				blocks = append(blocks, *block)
				continue
			}
		}

		// It's a paragraph
		text := strings.Join(paraLines, "\n")
		inlines := p.parseInlines(text)
		if len(inlines) > 0 {
			blocks = append(blocks, Block{Type: "Para", Inlines: inlines})
		}
	}

	return blocks
}

func (p *MdParser) collectParaLines(ls *lineState) []string {
	var paraLines []string
	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			break
		}
		// Stop at block-level elements
		if tryATXHeader(line) != nil ||
			isFencedCode(line) ||
			isHorizontalRule(line) ||
			(strings.HasPrefix(line, "> ") || line == ">") ||
			isBulletListItem(line) ||
			isOrderedListItem(line) ||
			isHTMLBlock(line) ||
			isPipeTableLine(line) ||
			isFencedDiv(line) {
			break
		}
		paraLines = append(paraLines, ls.next())
	}
	return paraLines
}

func isFencedDiv(line string) bool {
	trimmed := strings.TrimSpace(line)
	return regexp.MustCompile(`^:{3,}\s*(\{[^}]*\}|\w+)?\s*$`).MatchString(trimmed) ||
		regexp.MustCompile(`^:{3,}\s*$`).MatchString(trimmed)
}

func (p *MdParser) parseFencedDiv(ls *lineState) *Block {
	firstLine := ls.next()
	trimmed := strings.TrimSpace(firstLine)

	// Parse attributes
	attr := emptyAttr()
	colonCount := 0
	for _, c := range trimmed {
		if c == ':' {
			colonCount++
		} else {
			break
		}
	}
	rest := strings.TrimSpace(trimmed[colonCount:])
	if rest != "" {
		attr = parseAttrStr(rest)
	}

	closing := strings.Repeat(":", colonCount)
	var divLines []string
	for !ls.done() {
		line := ls.peek()
		trimLine := strings.TrimSpace(line)
		if strings.HasPrefix(trimLine, closing) && strings.TrimSpace(trimLine[colonCount:]) == "" {
			ls.next()
			break
		}
		divLines = append(divLines, ls.next())
	}

	innerBlocks := p.parseBlockLines(divLines)
	return &Block{Type: "Div", Attr: attr, Blocks: innerBlocks}
}

func tryATXHeader(line string) *Block {
	re := regexp.MustCompile(`^(#{1,6})\s+(.+?)(?:\s+#+\s*)?$`)
	re2 := regexp.MustCompile(`^(#{1,6})\s*$`)

	if m := re.FindStringSubmatch(line); m != nil {
		level := len(m[1])
		text := strings.TrimRight(m[2], " #")
		text = strings.TrimRight(text, " ")
		return &Block{Type: "Header", Level: level, Code: text, Attr: emptyAttr()}
	}
	if m := re2.FindStringSubmatch(line); m != nil {
		level := len(m[1])
		return &Block{Type: "Header", Level: level, Code: "", Attr: emptyAttr()}
	}
	return nil
}

func (p *MdParser) parseHeaderAttr(block *Block) {
	text := block.Code
	// Check for {#id .class key=val}
	attrRe := regexp.MustCompile(`\{([^}]*)\}\s*$`)
	if m := attrRe.FindStringSubmatch(text); m != nil {
		block.Attr = parseAttrStr(m[1])
		block.Code = strings.TrimSpace(text[:len(text)-len(m[0])])
	} else {
		// Auto generate ID from text
		block.Attr = Attr{
			ID:      makeIdentifier(text),
			Classes: []string{},
			KVPairs: [][2]string{},
		}
	}
}

func parseAttrStr(s string) Attr {
	attr := emptyAttr()
	s = strings.TrimSpace(s)
	// Remove surrounding { } if present
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		s = s[1 : len(s)-1]
	}
	s = strings.TrimSpace(s)

	tokens := tokenizeAttr(s)
	for _, tok := range tokens {
		if strings.HasPrefix(tok, "#") {
			attr.ID = tok[1:]
		} else if strings.HasPrefix(tok, ".") {
			attr.Classes = append(attr.Classes, tok[1:])
		} else if strings.Contains(tok, "=") {
			parts := strings.SplitN(tok, "=", 2)
			val := parts[1]
			if strings.HasPrefix(val, `"`) && strings.HasSuffix(val, `"`) {
				val = val[1 : len(val)-1]
			}
			attr.KVPairs = append(attr.KVPairs, [2]string{parts[0], val})
		}
	}
	if attr.ID == "" {
		// Not set
	}
	return attr
}

func tokenizeAttr(s string) []string {
	var tokens []string
	var cur strings.Builder
	inQuote := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' {
			inQuote = !inQuote
			cur.WriteByte(c)
		} else if c == ' ' || c == '\t' {
			if !inQuote {
				if cur.Len() > 0 {
					tokens = append(tokens, cur.String())
					cur.Reset()
				}
			} else {
				cur.WriteByte(c)
			}
		} else {
			cur.WriteByte(c)
		}
	}
	if cur.Len() > 0 {
		tokens = append(tokens, cur.String())
	}
	return tokens
}

func makeIdentifier(text string) string {
	// Remove formatting and convert to identifier
	// Strip HTML tags
	re := regexp.MustCompile(`<[^>]+>`)
	text = re.ReplaceAllString(text, "")
	// Remove punctuation except hyphens and underscores
	var sb strings.Builder
	prevWasSpace := false
	for _, r := range strings.ToLower(text) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(r)
			prevWasSpace = false
		} else if r == '-' || r == '_' || r == '.' {
			sb.WriteRune(r)
			prevWasSpace = false
		} else if unicode.IsSpace(r) || r == '/' {
			if !prevWasSpace && sb.Len() > 0 {
				sb.WriteByte('-')
				prevWasSpace = true
			}
		}
		// Skip other chars
	}
	result := strings.Trim(sb.String(), "-")
	if result == "" {
		result = "section"
	}
	return result
}

func isFencedCode(line string) bool {
	trimmed := strings.TrimLeft(line, " \t")
	return regexp.MustCompile("^(`{3,}|~{3,})").MatchString(trimmed)
}

func (p *MdParser) parseFencedCode(ls *lineState) *Block {
	firstLine := ls.next()
	trimmed := strings.TrimLeft(firstLine, " \t")

	// Find fence char and length
	fenceChar := trimmed[0]
	fenceLen := 0
	for fenceLen < len(trimmed) && trimmed[fenceLen] == fenceChar {
		fenceLen++
	}
	fence := string([]byte{fenceChar})

	// Parse info string (language)
	infoStr := strings.TrimSpace(trimmed[fenceLen:])

	attr := emptyAttr()
	lang := ""
	if strings.HasPrefix(infoStr, "{") {
		attr = parseAttrStr(infoStr)
	} else if infoStr != "" {
		// Could be "python" or "python .numberLines"
		parts := strings.Fields(infoStr)
		if len(parts) > 0 {
			lang = parts[0]
			attr.Classes = []string{lang}
			for _, part := range parts[1:] {
				if strings.HasPrefix(part, ".") {
					attr.Classes = append(attr.Classes, part[1:])
				} else if strings.HasPrefix(part, "#") {
					attr.ID = part[1:]
				} else if strings.Contains(part, "=") {
					kv := strings.SplitN(part, "=", 2)
					attr.KVPairs = append(attr.KVPairs, [2]string{kv[0], kv[1]})
				}
			}
		}
	}
	_ = lang

	// Collect code lines until matching fence
	var codeLines []string
	closingFence := regexp.MustCompile(`^` + strings.Repeat(`\`+fence, fenceLen) + `+\s*$`)

	for !ls.done() {
		line := ls.peek()
		if closingFence.MatchString(strings.TrimLeft(line, " \t")) {
			ls.next()
			break
		}
		codeLines = append(codeLines, ls.next())
	}

	code := strings.Join(codeLines, "\n")
	return &Block{Type: "CodeBlock", Attr: attr, Code: code}
}

func isIndentedCode(line string) bool {
	return strings.HasPrefix(line, "    ") || strings.HasPrefix(line, "\t")
}

func (p *MdParser) parseIndentedCode(ls *lineState) *Block {
	var codeLines []string
	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			// peek ahead to see if more code follows
			saved := ls.pos
			ls.next()
			if ls.done() || !isIndentedCode(ls.peek()) {
				ls.pos = saved
				break
			}
			codeLines = append(codeLines, "")
			continue
		}
		if !isIndentedCode(line) {
			break
		}
		// Remove leading 4 spaces or 1 tab
		if strings.HasPrefix(line, "\t") {
			codeLines = append(codeLines, line[1:])
		} else {
			codeLines = append(codeLines, line[4:])
		}
		ls.next()
	}
	// Remove trailing blank lines
	for len(codeLines) > 0 && codeLines[len(codeLines)-1] == "" {
		codeLines = codeLines[:len(codeLines)-1]
	}
	code := strings.Join(codeLines, "\n")
	return &Block{Type: "CodeBlock", Attr: emptyAttr(), Code: code}
}

func isHorizontalRule(line string) bool {
	trimmed := strings.TrimSpace(line)
	if len(trimmed) < 3 {
		return false
	}
	// --- or *** or ___ (with optional spaces)
	re := regexp.MustCompile(`^(\-\s*){3,}$|^(\*\s*){3,}$|^(_\s*){3,}$`)
	return re.MatchString(trimmed)
}

func (p *MdParser) parseBlockQuote(ls *lineState) *Block {
	var quoteLines []string
	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			// Check if blockquote continues after blank line
			saved := ls.pos
			ls.next()
			if ls.done() || (!strings.HasPrefix(ls.peek(), "> ") && ls.peek() != ">") {
				ls.pos = saved
				break
			}
			quoteLines = append(quoteLines, "")
			continue
		}
		if strings.HasPrefix(line, "> ") {
			quoteLines = append(quoteLines, line[2:])
			ls.next()
		} else if line == ">" {
			quoteLines = append(quoteLines, "")
			ls.next()
		} else if len(quoteLines) > 0 && !isBlankLine(line) && !isBulletListItem(line) && !isOrderedListItem(line) && tryATXHeader(line) == nil {
			// Lazy continuation
			quoteLines = append(quoteLines, line)
			ls.next()
		} else {
			break
		}
	}

	innerBlocks := p.parseBlockLines(quoteLines)
	return &Block{Type: "BlockQuote", Blocks: innerBlocks}
}

func isBulletListItem(line string) bool {
	re := regexp.MustCompile(`^(\s{0,3})([*\-+])\s`)
	return re.MatchString(line)
}

func isOrderedListItem(line string) bool {
	re := regexp.MustCompile(`^(\s{0,3})(\d+|[a-zA-Z])[.)]\s`)
	return re.MatchString(line)
}

func isDefinitionList(ls *lineState) bool {
	if ls.pos+1 >= len(ls.lines) {
		return false
	}
	nextLine := ls.lines[ls.pos+1]
	return strings.HasPrefix(strings.TrimSpace(nextLine), ": ")
}

func (p *MdParser) parseBulletList(ls *lineState) *Block {
	var items [][]Block

	// Detect list marker
	firstLine := ls.peek()
	re := regexp.MustCompile(`^(\s*)([*\-+])\s+(.*)$`)
	m := re.FindStringSubmatch(firstLine)
	if m == nil {
		return nil
	}
	marker := m[2]

	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			ls.next()
			continue
		}

		re2 := regexp.MustCompile(`^(\s*)([*\-+])\s+(.*)$`)
		m2 := re2.FindStringSubmatch(line)
		if m2 == nil || m2[2] != marker {
			break
		}

		// Collect item lines
		indent := len(m2[1]) + 2 // marker + space
		content := m2[3]
		ls.next()

		var itemLines []string
		itemLines = append(itemLines, content)

		// Collect continuation lines
		for !ls.done() {
			nextLine := ls.peek()
			if isBlankLine(nextLine) {
				// Check for loose list
				saved := ls.pos
				ls.next()
				if ls.done() {
					break
				}
				nextNonBlank := ls.peek()
				if isIndented(nextNonBlank, indent) {
					itemLines = append(itemLines, "")
					continue
				}
				ls.pos = saved
				break
			}
			if isIndented(nextLine, indent) {
				itemLines = append(itemLines, nextLine[min(indent, len(nextLine)):])
				ls.next()
			} else {
				break
			}
		}

		innerBlocks := p.parseBlockLines(itemLines)
		items = append(items, innerBlocks)
	}

	if len(items) == 0 {
		return nil
	}

	// Determine if tight or loose
	tight := isListTight(items)
	if tight {
		for i := range items {
			items[i] = makeListTight(items[i])
		}
	}

	return &Block{Type: "BulletList", Items: items}
}

func isIndented(line string, indent int) bool {
	count := 0
	for _, c := range line {
		if c == ' ' {
			count++
		} else if c == '\t' {
			count += 4
		} else {
			break
		}
		if count >= indent {
			return true
		}
	}
	return false
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func isListTight(items [][]Block) bool {
	for _, item := range items {
		for _, block := range item {
			if block.Type == "Para" {
				// If it has para, and there are multiple items, it's loose
			}
		}
	}
	// Simple heuristic: if any item has multiple blocks or a Para at top level, it's loose
	for _, item := range items {
		if len(item) > 1 {
			return false
		}
		if len(item) == 1 && item[0].Type == "Para" {
			// Check if there are blank lines (we can't easily detect this here)
			// Actually, we need to track blank lines during parsing
			// For now, return tight for single-block items
		}
	}
	return true
}

func makeListTight(blocks []Block) []Block {
	var result []Block
	for _, b := range blocks {
		if b.Type == "Para" {
			result = append(result, Block{Type: "Plain", Inlines: b.Inlines})
		} else {
			result = append(result, b)
		}
	}
	return result
}

var orderedListRe = regexp.MustCompile(`^(\s*)(\d+|[a-zA-Z])([.)]) {1,4}(.*)$`)
var orderedListReRoman = regexp.MustCompile(`^(\s*)(i{1,4}|v|vi{1,3}|ix|x{1,3}|xl|l|li{1,4}|lv|lvi{1,3}|lix|I{1,4}|V|VI{1,3}|IX|X{1,3}|XL|L|LI{1,4}|LV|LVI{1,3}|LIX)([.)]) `)

func (p *MdParser) parseOrderedList(ls *lineState) *Block {
	var items [][]Block

	firstLine := ls.peek()
	m := orderedListRe.FindStringSubmatch(firstLine)
	if m == nil {
		return nil
	}

	delim := m[3]
	markerStr := m[2]

	// Determine style
	style := "Decimal"
	startNum := 1

	if len(markerStr) == 1 {
		c := markerStr[0]
		if c >= '0' && c <= '9' {
			style = "Decimal"
			startNum = int(c - '0')
		} else if c >= 'a' && c <= 'z' {
			// Could be alpha or roman
			if isRomanNumeral(markerStr) {
				style = "LowerRoman"
				startNum = romanToInt(markerStr)
			} else {
				style = "LowerAlpha"
				startNum = int(c-'a') + 1
			}
		} else if c >= 'A' && c <= 'Z' {
			if isRomanNumeral(strings.ToLower(markerStr)) {
				style = "UpperRoman"
				startNum = romanToInt(strings.ToLower(markerStr))
			} else {
				style = "UpperAlpha"
				startNum = int(c-'A') + 1
			}
		}
	} else {
		// Multi-digit decimal
		n := 0
		for _, c := range markerStr {
			n = n*10 + int(c-'0')
		}
		startNum = n
	}

	delimStr := "Period"
	if delim == ")" {
		delimStr = "OneParen"
	}

	listAttr := ListAttr{
		Start:     startNum,
		Style:     style,
		Delimiter: delimStr,
	}

	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			ls.next()
			continue
		}

		m2 := orderedListRe.FindStringSubmatch(line)
		if m2 == nil || m2[3] != delim {
			break
		}

		// Check style consistency
		marker2 := m2[2]
		if style == "Decimal" && !isDecimal(marker2) {
			break
		}

		indent := len(m2[1]) + len(m2[2]) + 1 + 1 // indentation + marker + delim + space
		content := m2[4]
		ls.next()

		var itemLines []string
		itemLines = append(itemLines, content)

		for !ls.done() {
			nextLine := ls.peek()
			if isBlankLine(nextLine) {
				saved := ls.pos
				ls.next()
				if ls.done() {
					break
				}
				if isIndented(ls.peek(), indent) {
					itemLines = append(itemLines, "")
					continue
				}
				ls.pos = saved
				break
			}
			if isIndented(nextLine, indent) {
				itemLines = append(itemLines, nextLine[min(indent, len(nextLine)):])
				ls.next()
			} else {
				break
			}
		}

		innerBlocks := p.parseBlockLines(itemLines)
		items = append(items, innerBlocks)
	}

	if len(items) == 0 {
		return nil
	}

	tight := isListTight(items)
	if tight {
		for i := range items {
			items[i] = makeListTight(items[i])
		}
	}

	return &Block{Type: "OrderedList", Items: items, ListAttr: listAttr}
}

func isDecimal(s string) bool {
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(s) > 0
}

var romanNumerals = map[string]int{
	"i": 1, "v": 5, "x": 10, "l": 50, "c": 100, "d": 500, "m": 1000,
}

func isRomanNumeral(s string) bool {
	s = strings.ToLower(s)
	for _, c := range s {
		if _, ok := romanNumerals[string(c)]; !ok {
			return false
		}
	}
	return len(s) > 0
}

func romanToInt(s string) int {
	s = strings.ToLower(s)
	val := 0
	prev := 0
	for i := len(s) - 1; i >= 0; i-- {
		curr := romanNumerals[string(s[i])]
		if curr < prev {
			val -= curr
		} else {
			val += curr
		}
		prev = curr
	}
	if val == 0 {
		return 1
	}
	return val
}

func (p *MdParser) parseDefinitionList(ls *lineState) *Block {
	var items []DefItem

	for !ls.done() {
		termLine := ls.peek()
		if isBlankLine(termLine) {
			ls.next()
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(termLine), ": ") {
			// Orphaned definition, skip
			ls.next()
			continue
		}

		// Check if next line is a definition
		if ls.pos+1 >= len(ls.lines) {
			break
		}
		nextLine := ls.lines[ls.pos+1]
		if !strings.HasPrefix(strings.TrimSpace(nextLine), ": ") {
			break
		}

		termText := ls.next()
		term := p.parseInlines(strings.TrimSpace(termText))

		var defs [][]Block
		for !ls.done() {
			line := ls.peek()
			if isBlankLine(line) {
				saved := ls.pos
				ls.next()
				if ls.done() || !strings.HasPrefix(strings.TrimSpace(ls.peek()), ": ") {
					ls.pos = saved
					break
				}
				continue
			}
			trimLine := strings.TrimSpace(line)
			if !strings.HasPrefix(trimLine, ": ") {
				break
			}

			defContent := trimLine[2:]
			ls.next()

			var defLines []string
			defLines = append(defLines, defContent)

			for !ls.done() {
				nextL := ls.peek()
				if isBlankLine(nextL) {
					break
				}
				if strings.HasPrefix(nextL, "  ") || strings.HasPrefix(nextL, "\t") {
					defLines = append(defLines, strings.TrimPrefix(strings.TrimPrefix(nextL, "  "), "\t"))
					ls.next()
				} else {
					break
				}
			}

			defBlocks := p.parseBlockLines(defLines)
			defs = append(defs, defBlocks)
		}

		items = append(items, DefItem{Term: term, Defs: defs})
	}

	if len(items) == 0 {
		return nil
	}
	return &Block{Type: "DefinitionList", DefItems: items}
}

func (p *MdParser) parseLineBlock(ls *lineState) *Block {
	var lines [][]Inline
	for !ls.done() {
		line := ls.peek()
		if strings.HasPrefix(line, "| ") {
			lines = append(lines, p.parseInlines(line[2:]))
			ls.next()
		} else if line == "|" {
			lines = append(lines, []Inline{})
			ls.next()
		} else {
			break
		}
	}
	return &Block{Type: "LineBlock", Lines: lines}
}

func isHTMLBlock(line string) bool {
	trimmed := strings.TrimSpace(line)
	// Block-level HTML tags
	blockTags := []string{"div", "p", "section", "article", "header", "footer", "nav",
		"aside", "main", "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "li",
		"dl", "dt", "dd", "table", "thead", "tbody", "tr", "th", "td", "blockquote",
		"pre", "hr", "br", "figure", "figcaption", "details", "summary",
		"form", "fieldset", "script", "style", "link", "meta", "head", "html",
		"!DOCTYPE", "!--",
	}
	if !strings.HasPrefix(trimmed, "<") {
		return false
	}
	lower := strings.ToLower(trimmed[1:])
	for _, tag := range blockTags {
		if strings.HasPrefix(lower, strings.ToLower(tag)) {
			rest := lower[len(tag):]
			if len(rest) == 0 || rest[0] == ' ' || rest[0] == '>' || rest[0] == '/' || rest[0] == '\t' || rest[0] == '\n' {
				return true
			}
		}
	}
	// HTML comment
	if strings.HasPrefix(trimmed, "<!--") {
		return true
	}
	// Self-closing
	if strings.HasSuffix(trimmed, "/>") {
		return true
	}
	return false
}

func (p *MdParser) parseHTMLBlock(ls *lineState) *Block {
	var htmlLines []string
	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			// HTML blocks end at blank line for most types
			htmlLines = append(htmlLines, ls.next())
			if ls.done() || isBlankLine(ls.peek()) {
				// Remove trailing blank
				for len(htmlLines) > 0 && isBlankLine(htmlLines[len(htmlLines)-1]) {
					htmlLines = htmlLines[:len(htmlLines)-1]
				}
				break
			}
		} else {
			htmlLines = append(htmlLines, ls.next())
		}
	}
	html := strings.Join(htmlLines, "\n")
	return &Block{Type: "RawBlock", Format: "html", Code: html}
}

func (p *MdParser) parseLaTeXBlock(ls *lineState) *Block {
	var latexLines []string
	for !ls.done() {
		line := ls.peek()
		latexLines = append(latexLines, ls.next())
		if strings.HasPrefix(strings.TrimSpace(line), "\\end{") {
			break
		}
		if isBlankLine(line) && len(latexLines) > 1 {
			break
		}
	}
	latex := strings.Join(latexLines, "\n")
	return &Block{Type: "RawBlock", Format: "latex", Code: latex}
}

func isPipeTableLine(line string) bool {
	return strings.Contains(line, "|")
}

func isPipeTable(ls *lineState) bool {
	if ls.pos >= len(ls.lines) {
		return false
	}
	line := ls.lines[ls.pos]
	if !strings.Contains(line, "|") {
		return false
	}
	// Check if next line is a separator line
	if ls.pos+1 < len(ls.lines) {
		nextLine := ls.lines[ls.pos+1]
		if isPipeTableSep(nextLine) {
			return true
		}
	}
	return false
}

func isPipeTableSep(line string) bool {
	trimmed := strings.TrimSpace(line)
	re := regexp.MustCompile(`^\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?\s*$`)
	return re.MatchString(trimmed) && strings.Contains(trimmed, "-")
}

func (p *MdParser) parsePipeTable(ls *lineState) *Block {
	// Read header line
	headerLine := ls.next()
	// Read separator line
	sepLine := ls.next()

	headers := parsePipeTableRow(headerLine)
	aligns := parsePipeTableAligns(sepLine)

	// Pad aligns to match headers
	for len(aligns) < len(headers) {
		aligns = append(aligns, "AlignDefault")
	}

	// Read body rows
	var bodyRows [][]string
	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) || !strings.Contains(line, "|") {
			break
		}
		bodyRows = append(bodyRows, parsePipeTableRow(ls.next()))
	}

	// Build table
	numCols := len(headers)

	// ColSpecs
	colSpecs := make([]ColSpec, numCols)
	for i := 0; i < numCols; i++ {
		al := "AlignDefault"
		if i < len(aligns) {
			al = aligns[i]
		}
		colSpecs[i] = ColSpec{Align: al, Width: 0}
	}

	// Header row
	var headCells []TableCell
	for i := 0; i < numCols; i++ {
		text := ""
		if i < len(headers) {
			text = headers[i]
		}
		al := colSpecs[i].Align
		headCells = append(headCells, TableCell{
			Attr:    emptyAttr(),
			Align:   al,
			RowSpan: 1,
			ColSpan: 1,
			Blocks:  []Block{{Type: "Plain", Inlines: p.parseInlines(text)}},
		})
	}

	headRow := TableRow{Attr: emptyAttr(), Cells: headCells}

	// Body rows
	var bodyTableRows []TableRow
	for _, row := range bodyRows {
		var cells []TableCell
		for i := 0; i < numCols; i++ {
			text := ""
			if i < len(row) {
				text = row[i]
			}
			al := colSpecs[i].Align
			cells = append(cells, TableCell{
				Attr:    emptyAttr(),
				Align:   al,
				RowSpan: 1,
				ColSpan: 1,
				Blocks:  []Block{{Type: "Plain", Inlines: p.parseInlines(text)}},
			})
		}
		bodyTableRows = append(bodyTableRows, TableRow{Attr: emptyAttr(), Cells: cells})
	}

	tableData := &TableData{
		Caption:  Caption{},
		ColSpecs: colSpecs,
		Head:     TableHead{Attr: emptyAttr(), Rows: []TableRow{headRow}},
		Bodies:   []TableBody{{Attr: emptyAttr(), RowHead: 0, HeadRows: []TableRow{}, Rows: bodyTableRows}},
		Foot:     TableFoot{Attr: emptyAttr(), Rows: []TableRow{}},
	}

	return &Block{Type: "Table", Attr: emptyAttr(), Table: tableData}
}

func parsePipeTableRow(line string) []string {
	trimmed := strings.TrimSpace(line)
	// Remove leading and trailing |
	if strings.HasPrefix(trimmed, "|") {
		trimmed = trimmed[1:]
	}
	if strings.HasSuffix(trimmed, "|") {
		trimmed = trimmed[:len(trimmed)-1]
	}

	parts := strings.Split(trimmed, "|")
	result := make([]string, len(parts))
	for i, p := range parts {
		result[i] = strings.TrimSpace(p)
	}
	return result
}

func parsePipeTableAligns(line string) []string {
	cells := parsePipeTableRow(line)
	var aligns []string
	for _, cell := range cells {
		cell = strings.TrimSpace(cell)
		left := strings.HasPrefix(cell, ":")
		right := strings.HasSuffix(cell, ":")
		if left && right {
			aligns = append(aligns, "AlignCenter")
		} else if right {
			aligns = append(aligns, "AlignRight")
		} else if left {
			aligns = append(aligns, "AlignLeft")
		} else {
			aligns = append(aligns, "AlignDefault")
		}
	}
	return aligns
}

func isSetextUnderline1(line string) bool {
	trimmed := strings.TrimSpace(line)
	if len(trimmed) == 0 {
		return false
	}
	re := regexp.MustCompile(`^=+$`)
	return re.MatchString(trimmed)
}

func isSetextUnderline2(line string) bool {
	trimmed := strings.TrimSpace(line)
	if len(trimmed) == 0 {
		return false
	}
	re := regexp.MustCompile(`^-+$`)
	return re.MatchString(trimmed)
}
