package main

import (
	"regexp"
	"strings"
	"unicode/utf8"
)

// parseInlines parses inline markdown text into a slice of Inline elements
func (p *MdParser) parseInlines(text string) []Inline {
	if text == "" {
		return []Inline{}
	}
	parser := &inlineParser{
		text:   text,
		pos:    0,
		refs:   p.refs,
		noteID: 0,
	}
	return parser.parse()
}

type inlineParser struct {
	text    string
	pos     int
	refs    map[string]RefDef
	noteID  int
	notes   [][]Block
}

func (p *inlineParser) parse() []Inline {
	var result []Inline

	for p.pos < len(p.text) {
		inline := p.parseOne()
		if inline == nil {
			// Advance one rune
			r, size := utf8.DecodeRuneInString(p.text[p.pos:])
			result = appendStr(result, string(r))
			p.pos += size
			continue
		}
		result = mergeInlines(result, *inline)
	}

	return result
}

func appendStr(inlines []Inline, s string) []Inline {
	if s == "" {
		return inlines
	}
	if len(inlines) > 0 && inlines[len(inlines)-1].Type == "Str" {
		inlines[len(inlines)-1].Text += s
		return inlines
	}
	return append(inlines, Inline{Type: "Str", Text: s})
}

func mergeInlines(result []Inline, inline Inline) []Inline {
	if inline.Type == "Str" && len(result) > 0 && result[len(result)-1].Type == "Str" {
		result[len(result)-1].Text += inline.Text
		return result
	}
	return append(result, inline)
}

func (p *inlineParser) parseOne() *Inline {
	if p.pos >= len(p.text) {
		return nil
	}

	c := p.text[p.pos]

	switch c {
	case '\\':
		return p.parseBackslash()
	case '`':
		return p.parseCode()
	case '*', '_':
		return p.parseEmphStrong()
	case '[':
		return p.parseLinkOrImage()
	case '!':
		return p.parseImage()
	case '<':
		return p.parseAutolink()
	case '&':
		return p.parseHTMLEntity()
	case '\n':
		return p.parseLineBreak()
	case '-':
		return p.parseDash()
	case '"':
		return p.parseDoubleQuote()
	case '\'':
		return p.parseSingleQuote()
	case '~':
		return p.parseStrikeOrSub()
	case '^':
		return p.parseSuperscript()
	case '$':
		return p.parseMath()
	}

	return nil
}

func (p *inlineParser) peek(n int) byte {
	if p.pos+n >= len(p.text) {
		return 0
	}
	return p.text[p.pos+n]
}

func (p *inlineParser) parseBackslash() *Inline {
	if p.pos+1 >= len(p.text) {
		return nil
	}
	next := p.text[p.pos+1]

	// Hard line break: \\ at end of line
	if next == '\n' {
		p.pos += 2
		return &Inline{Type: "LineBreak"}
	}

	// Escaped punctuation
	escapable := `\` + "`*_{}[]()#+-.!|`
	if strings.ContainsRune(escapable, rune(next)) {
		p.pos += 2
		return &Inline{Type: "Str", Text: string(next)}
	}

	// Raw TeX: \command or similar - just return the backslash
	return nil
}

func (p *inlineParser) parseCode() *Inline {
	start := p.pos
	// Count backticks
	count := 0
	for p.pos < len(p.text) && p.text[p.pos] == '`' {
		count++
		p.pos++
	}

	// Find matching closing backticks
	closing := strings.Repeat("`", count)
	endIdx := strings.Index(p.text[p.pos:], closing)
	if endIdx < 0 {
		// Not a code span, backtrack
		p.pos = start
		return nil
	}

	codeText := p.text[p.pos : p.pos+endIdx]
	p.pos += endIdx + count

	// Normalize: strip single spaces if both ends have space
	if len(codeText) > 2 && codeText[0] == ' ' && codeText[len(codeText)-1] == ' ' {
		codeText = codeText[1 : len(codeText)-1]
	}
	// Collapse whitespace
	codeText = regexp.MustCompile(`\s+`).ReplaceAllString(codeText, " ")

	return &Inline{Type: "Code", Attr: emptyAttr(), Text: codeText}
}

func (p *inlineParser) parseEmphStrong() *Inline {
	start := p.pos
	c := p.text[p.pos]

	// Count delimiter runs
	count := 0
	for p.pos < len(p.text) && p.text[p.pos] == c {
		count++
		p.pos++
	}

	if count == 0 {
		p.pos = start
		return nil
	}

	// Determine what we're looking for
	// 1 = emph, 2 = strong, 3 = strong+emph

	var result *Inline

	if count >= 3 {
		// Try strong+emph
		delim := string([]byte{c, c, c})
		content, ok := p.parseUntilDelim(delim)
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			result = &Inline{Type: "Strong", Inlines: []Inline{
				{Type: "Emph", Inlines: parsed},
			}}
			return result
		}
		p.pos = start + count
	}

	if count >= 2 {
		p.pos = start
		// Try **strong**
		delim := string([]byte{c, c})
		p.pos += 2
		content, ok := p.parseUntilDelim(delim)
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{Type: "Strong", Inlines: parsed}
		}
		p.pos = start + count
	}

	if count >= 1 {
		p.pos = start + 1
		// Try *emph*
		delim := string([]byte{c})
		content, ok := p.parseUntilDelim(delim)
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{Type: "Emph", Inlines: parsed}
		}
	}

	p.pos = start
	return nil
}

func (p *inlineParser) parseUntilDelim(delim string) (string, bool) {
	startPos := p.pos
	// Don't allow delimiter at start
	if p.pos < len(p.text) && string(p.text[p.pos:min(p.pos+len(delim), len(p.text))]) == delim {
		return "", false
	}

	for p.pos < len(p.text) {
		if p.text[p.pos] == '\\' && p.pos+1 < len(p.text) {
			p.pos += 2
			continue
		}
		if len(p.text)-p.pos >= len(delim) && p.text[p.pos:p.pos+len(delim)] == delim {
			content := p.text[startPos:p.pos]
			p.pos += len(delim)
			// Don't close if followed by the same char
			if len(delim) == 1 && p.pos < len(p.text) && p.text[p.pos] == delim[0] {
				// This might be **word* case - backtrack not possible here
			}
			return content, true
		}
		_, size := utf8.DecodeRuneInString(p.text[p.pos:])
		p.pos += size
	}

	p.pos = startPos
	return "", false
}

func (p *inlineParser) parseLinkOrImage() *Inline {
	start := p.pos
	p.pos++ // skip [

	// Check for footnote [^label]
	if p.pos < len(p.text) && p.text[p.pos] == '^' {
		return p.parseFootnoteRef(start)
	}

	// Find matching ]
	content, ok := p.parseBracketContent()
	if !ok {
		p.pos = start
		return nil
	}

	// Check what follows
	if p.pos >= len(p.text) {
		p.pos = start
		return nil
	}

	if p.text[p.pos] == '(' {
		// Inline link
		p.pos++
		url, title, ok := p.parseLinkTarget()
		if !ok {
			p.pos = start
			return nil
		}
		inner := &inlineParser{text: content, pos: 0, refs: p.refs}
		parsed := inner.parse()
		return &Inline{
			Type:    "Link",
			Attr:    emptyAttr(),
			Inlines: parsed,
			Target:  Target{URL: url, Title: title},
		}
	} else if p.text[p.pos] == '[' {
		// Reference link [text][ref]
		p.pos++
		refContent, ok := p.parseBracketContent()
		if !ok {
			p.pos = start
			return nil
		}
		refKey := strings.ToLower(refContent)
		if refKey == "" {
			refKey = strings.ToLower(content)
		}
		if ref, found := p.refs[refKey]; found {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{
				Type:    "Link",
				Attr:    emptyAttr(),
				Inlines: parsed,
				Target:  Target{URL: ref.URL, Title: ref.Title},
			}
		}
		p.pos = start
		return nil
	} else {
		// Shortcut reference link [text] or [text][]
		if p.pos < len(p.text) && p.text[p.pos] == '[' && p.pos+1 < len(p.text) && p.text[p.pos+1] == ']' {
			p.pos += 2
		}
		refKey := strings.ToLower(content)
		if ref, found := p.refs[refKey]; found {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{
				Type:    "Link",
				Attr:    emptyAttr(),
				Inlines: parsed,
				Target:  Target{URL: ref.URL, Title: ref.Title},
			}
		}
		// Check for bracketed spans {.class} etc
		if p.pos < len(p.text) && p.text[p.pos] == '{' {
			attrStart := p.pos
			p.pos++
			attrContent, ok := p.parseUntilChar('}')
			if ok {
				p.pos++ // skip }
				attr := parseAttrStr("{" + attrContent + "}")
				inner := &inlineParser{text: content, pos: 0, refs: p.refs}
				parsed := inner.parse()
				return &Inline{Type: "Span", Attr: attr, Inlines: parsed}
			}
			p.pos = attrStart
		}
		p.pos = start
		return nil
	}
}

func (p *inlineParser) parseFootnoteRef(start int) *Inline {
	p.pos++ // skip ^
	labelContent, ok := p.parseBracketContent()
	if !ok {
		p.pos = start
		return nil
	}
	// Inline note
	inner := &inlineParser{text: labelContent, pos: 0, refs: p.refs}
	parsed := inner.parse()
	// Create a note - in pandoc, [^label] references a footnote
	// For inline notes [^content], we create a Note directly
	_ = parsed
	return &Inline{Type: "Note", Blocks: []Block{{Type: "Para", Inlines: parsed}}}
}

func (p *inlineParser) parseBracketContent() (string, bool) {
	startPos := p.pos
	depth := 0
	for p.pos < len(p.text) {
		c := p.text[p.pos]
		if c == '[' {
			depth++
			p.pos++
		} else if c == ']' {
			if depth == 0 {
				content := p.text[startPos:p.pos]
				p.pos++ // skip ]
				return content, true
			}
			depth--
			p.pos++
		} else if c == '\\' && p.pos+1 < len(p.text) {
			p.pos += 2
		} else {
			p.pos++
		}
	}
	p.pos = startPos - 1
	return "", false
}

func (p *inlineParser) parseLinkTarget() (string, string, bool) {
	// Skip whitespace
	for p.pos < len(p.text) && (p.text[p.pos] == ' ' || p.text[p.pos] == '\n' || p.text[p.pos] == '\t') {
		p.pos++
	}

	if p.pos >= len(p.text) {
		return "", "", false
	}

	var url string
	if p.text[p.pos] == '<' {
		// Angle bracket URL
		p.pos++
		urlStart := p.pos
		for p.pos < len(p.text) && p.text[p.pos] != '>' {
			p.pos++
		}
		url = p.text[urlStart:p.pos]
		if p.pos < len(p.text) {
			p.pos++ // skip >
		}
	} else {
		// URL until space or )
		urlStart := p.pos
		depth := 0
		for p.pos < len(p.text) {
			c := p.text[p.pos]
			if c == '(' {
				depth++
				p.pos++
			} else if c == ')' {
				if depth == 0 {
					break
				}
				depth--
				p.pos++
			} else if c == ' ' || c == '\t' || c == '\n' {
				break
			} else if c == '\\' && p.pos+1 < len(p.text) {
				p.pos += 2
			} else {
				p.pos++
			}
		}
		url = p.text[urlStart:p.pos]
	}

	// Skip whitespace
	for p.pos < len(p.text) && (p.text[p.pos] == ' ' || p.text[p.pos] == '\n' || p.text[p.pos] == '\t') {
		p.pos++
	}

	title := ""
	if p.pos < len(p.text) && (p.text[p.pos] == '"' || p.text[p.pos] == '\'' || p.text[p.pos] == '(') {
		closer := p.text[p.pos]
		if closer == '(' {
			closer = ')'
		}
		p.pos++
		titleStart := p.pos
		for p.pos < len(p.text) && p.text[p.pos] != closer {
			if p.text[p.pos] == '\\' && p.pos+1 < len(p.text) {
				p.pos += 2
			} else {
				p.pos++
			}
		}
		title = p.text[titleStart:p.pos]
		if p.pos < len(p.text) {
			p.pos++ // skip closer
		}
	}

	// Skip whitespace
	for p.pos < len(p.text) && (p.text[p.pos] == ' ' || p.text[p.pos] == '\n' || p.text[p.pos] == '\t') {
		p.pos++
	}

	if p.pos >= len(p.text) || p.text[p.pos] != ')' {
		return "", "", false
	}
	p.pos++ // skip )

	return url, title, true
}

func (p *inlineParser) parseImage() *Inline {
	start := p.pos
	if p.pos+1 >= len(p.text) || p.text[p.pos+1] != '[' {
		return nil
	}
	p.pos += 2 // skip ![

	altContent, ok := p.parseBracketContent()
	if !ok {
		p.pos = start
		return nil
	}

	if p.pos >= len(p.text) {
		p.pos = start
		return nil
	}

	if p.text[p.pos] == '(' {
		p.pos++
		url, title, ok := p.parseLinkTarget()
		if !ok {
			p.pos = start
			return nil
		}
		inner := &inlineParser{text: altContent, pos: 0, refs: p.refs}
		parsed := inner.parse()
		return &Inline{
			Type:    "Image",
			Attr:    emptyAttr(),
			Inlines: parsed,
			Target:  Target{URL: url, Title: title},
		}
	} else if p.text[p.pos] == '[' {
		// Reference image
		p.pos++
		refContent, ok := p.parseBracketContent()
		if !ok {
			p.pos = start
			return nil
		}
		refKey := strings.ToLower(refContent)
		if refKey == "" {
			refKey = strings.ToLower(altContent)
		}
		if ref, found := p.refs[refKey]; found {
			inner := &inlineParser{text: altContent, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{
				Type:    "Image",
				Attr:    emptyAttr(),
				Inlines: parsed,
				Target:  Target{URL: ref.URL, Title: ref.Title},
			}
		}
		p.pos = start
		return nil
	}

	p.pos = start
	return nil
}

func (p *inlineParser) parseAutolink() *Inline {
	start := p.pos
	if p.pos+1 >= len(p.text) {
		return nil
	}

	p.pos++ // skip <

	// Check for URL or email
	urlStart := p.pos
	for p.pos < len(p.text) && p.text[p.pos] != '>' && p.text[p.pos] != '<' && p.text[p.pos] != ' ' {
		p.pos++
	}

	if p.pos >= len(p.text) || p.text[p.pos] != '>' {
		p.pos = start
		return nil
	}

	content := p.text[urlStart:p.pos]
	p.pos++ // skip >

	// Check if it's a valid URL or email
	if strings.Contains(content, "://") || strings.Contains(content, "@") {
		isEmail := strings.Contains(content, "@") && !strings.Contains(content, "://")
		url := content
		if isEmail {
			url = "mailto:" + content
		}
		return &Inline{
			Type:    "Link",
			Attr:    emptyAttr(),
			Inlines: []Inline{{Type: "Str", Text: content}},
			Target:  Target{URL: url},
		}
	}

	// Could be HTML tag - return as raw HTML
	fullTag := "<" + content + ">"
	p.pos = start
	_ = fullTag
	return nil
}

func (p *inlineParser) parseHTMLEntity() *Inline {
	start := p.pos
	if p.pos+1 >= len(p.text) || p.text[p.pos+1] != '#' {
		// Named entity like &amp;
		p.pos++
		entityStart := p.pos
		for p.pos < len(p.text) && (isLetter(p.text[p.pos]) || isDigit(p.text[p.pos])) {
			p.pos++
		}
		if p.pos < len(p.text) && p.text[p.pos] == ';' {
			entity := p.text[entityStart:p.pos]
			p.pos++
			decoded := decodeHTMLEntity(entity)
			if decoded != "" {
				return &Inline{Type: "Str", Text: decoded}
			}
		}
		p.pos = start
		return nil
	}
	return nil
}

func isLetter(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func decodeHTMLEntity(name string) string {
	entities := map[string]string{
		"amp": "&", "lt": "<", "gt": ">", "quot": `"`, "apos": "'",
		"nbsp": "\u00a0", "mdash": "\u2014", "ndash": "\u2013",
		"ldquo": "\u201c", "rdquo": "\u201d", "lsquo": "\u2018", "rsquo": "\u2019",
		"hellip": "\u2026", "copy": "\u00a9", "reg": "\u00ae",
		"trade": "\u2122", "euro": "\u20ac", "pound": "\u00a3",
	}
	return entities[name]
}

func (p *inlineParser) parseLineBreak() *Inline {
	p.pos++ // skip \n
	if p.pos >= len(p.text) {
		return &Inline{Type: "SoftBreak"}
	}
	// Skip leading spaces on next line
	return &Inline{Type: "SoftBreak"}
}

func (p *inlineParser) parseDash() *Inline {
	start := p.pos
	count := 0
	for p.pos < len(p.text) && p.text[p.pos] == '-' {
		count++
		p.pos++
	}

	if count >= 3 {
		// Em dash(es)
		numEmDash := count / 3
		remaining := count % 3
		var result strings.Builder
		for i := 0; i < numEmDash; i++ {
			result.WriteString("\u2014")
		}
		if remaining == 2 {
			result.WriteString("\u2013")
		} else if remaining == 1 {
			result.WriteString("-")
		}
		return &Inline{Type: "Str", Text: result.String()}
	} else if count == 2 {
		// En dash
		return &Inline{Type: "Str", Text: "\u2013"}
	}

	p.pos = start
	return nil
}

func (p *inlineParser) parseDoubleQuote() *Inline {
	start := p.pos
	p.pos++ // skip "

	// Find closing "
	content, ok := p.parseUntilChar('"')
	if !ok {
		p.pos = start
		return nil
	}
	p.pos++ // skip closing "

	inner := &inlineParser{text: content, pos: 0, refs: p.refs}
	parsed := inner.parse()
	return &Inline{Type: "Quoted", QuoteType: "DoubleQuote", Inlines: parsed}
}

func (p *inlineParser) parseSingleQuote() *Inline {
	start := p.pos
	p.pos++ // skip '

	// Only parse as quote if preceded by word boundary
	// Apostrophe in "it's" should not be a quote

	// Find closing '
	content, ok := p.parseUntilChar('\'')
	if !ok {
		p.pos = start
		return nil
	}
	// Check that content doesn't contain just a word (it's apostrophe case)
	if len(content) == 0 || !strings.Contains(content, " ") {
		// Might be apostrophe, leave it
		p.pos = start
		return nil
	}
	p.pos++ // skip closing '

	inner := &inlineParser{text: content, pos: 0, refs: p.refs}
	parsed := inner.parse()
	return &Inline{Type: "Quoted", QuoteType: "SingleQuote", Inlines: parsed}
}

func (p *inlineParser) parseUntilChar(c byte) (string, bool) {
	start := p.pos
	for p.pos < len(p.text) {
		if p.text[p.pos] == c {
			content := p.text[start:p.pos]
			return content, true
		}
		if p.text[p.pos] == '\\' && p.pos+1 < len(p.text) {
			p.pos += 2
		} else {
			p.pos++
		}
	}
	p.pos = start
	return "", false
}

func (p *inlineParser) parseStrikeOrSub() *Inline {
	start := p.pos
	count := 0
	for p.pos < len(p.text) && p.text[p.pos] == '~' {
		count++
		p.pos++
	}

	if count == 2 {
		// ~~strikethrough~~
		content, ok := p.parseUntilDelim("~~")
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{Type: "Strikeout", Inlines: parsed}
		}
	} else if count == 1 {
		// ~subscript~
		content, ok := p.parseUntilDelim("~")
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs}
			parsed := inner.parse()
			return &Inline{Type: "Subscript", Inlines: parsed}
		}
	}

	p.pos = start
	return nil
}

func (p *inlineParser) parseSuperscript() *Inline {
	start := p.pos
	p.pos++ // skip ^

	content, ok := p.parseUntilDelim("^")
	if ok {
		inner := &inlineParser{text: content, pos: 0, refs: p.refs}
		parsed := inner.parse()
		return &Inline{Type: "Superscript", Inlines: parsed}
	}

	p.pos = start
	return nil
}

func (p *inlineParser) parseMath() *Inline {
	start := p.pos
	p.pos++ // skip first $

	if p.pos < len(p.text) && p.text[p.pos] == '$' {
		// Display math $$...$$
		p.pos++
		mathStart := p.pos
		endIdx := strings.Index(p.text[p.pos:], "$$")
		if endIdx < 0 {
			p.pos = start
			return nil
		}
		mathText := p.text[mathStart : p.pos+endIdx]
		p.pos += endIdx + 2
		return &Inline{Type: "Math", MathType: "DisplayMath", Text: mathText}
	}

	// Inline math $...$
	mathStart := p.pos
	endIdx := strings.Index(p.text[p.pos:], "$")
	if endIdx < 0 {
		p.pos = start
		return nil
	}
	mathText := p.text[mathStart : p.pos+endIdx]
	p.pos += endIdx + 1
	return &Inline{Type: "Math", MathType: "InlineMath", Text: mathText}
}

// Parse soft line breaks in paragraph text (treating \n as SoftBreak or space)
func parseParaText(text string, refs map[string]RefDef) []Inline {
	// Handle hard line breaks (two spaces + newline, or backslash + newline)
	// and soft breaks
	lines := strings.Split(text, "\n")
	var result []Inline

	for i, line := range lines {
		if i > 0 {
			// Check if previous line ended with hard break
			prev := result
			if len(prev) > 0 {
				last := prev[len(prev)-1]
				if last.Type == "LineBreak" {
					// Already have a hard break
				} else {
					// Soft break (inline space)
					result = append(result, Inline{Type: "SoftBreak"})
				}
			}
		}

		// Check for hard break at end of line
		hardBreak := false
		if strings.HasSuffix(line, "  ") || strings.HasSuffix(line, "\\") {
			if strings.HasSuffix(line, "\\") {
				line = line[:len(line)-1]
			} else {
				line = strings.TrimRight(line, " ")
			}
			hardBreak = true
		}

		p := &inlineParser{text: line, pos: 0, refs: refs}
		parsed := p.parse()
		result = append(result, parsed...)

		if hardBreak && i < len(lines)-1 {
			result = append(result, Inline{Type: "LineBreak"})
		}
	}

	return result
}
