		"round": true, "isinstance": true, "issubclass": true, "hasattr": true,
		"getattr": true, "setattr": true, "delattr": true, "dir": true,
		"vars": true, "repr": true, "id": true, "hash": true, "any": true,
		"all": true, "next": true, "iter": true, "callable": true,
	}
	return builtins[w]
}

func isHaskellKeyword(w string) bool {
	keywords := map[string]bool{
		"case": true, "class": true, "data": true, "default": true, "deriving": true,
		"do": true, "else": true, "forall": true, "if": true, "import": true,
		"in": true, "infix": true, "infixl": true, "infixr": true, "instance": true,
		"let": true, "module": true, "newtype": true, "of": true, "qualified": true,
		"then": true, "type": true, "where": true, "as": true, "hiding": true,
	}
	return keywords[w]
}

func isJSKeyword(w string) bool {
	keywords := map[string]bool{
		"break": true, "case": true, "catch": true, "class": true, "const": true,
		"continue": true, "debugger": true, "default": true, "delete": true,
		"do": true, "else": true, "export": true, "extends": true, "finally": true,
		"for": true, "function": true, "if": true, "import": true, "in": true,
		"instanceof": true, "let": true, "new": true, "return": true, "static": true,
		"super": true, "switch": true, "this": true, "throw": true, "try": true,
		"typeof": true, "var": true, "void": true, "while": true, "with": true,
		"yield": true, "async": true, "await": true, "of": true,
