# Now let me write the HTML writer
cat > pandoc-impl/html_writer.go << 'GOEOF'
package main

import (
	"fmt"
	"strings"
	"strconv"
	"regexp"
)

type HTMLWriter struct {
	opts       *Options
	footnotes  [][]Block
	footnoteID int
	codeBlockID int
	identifiers map[string]int // for deduplication
}

func newHTMLWriter(opts *Options) *HTMLWriter {
	return &HTMLWriter{
		opts:        opts,
		identifiers: make(map[string]int),
	}
}

func (w *HTMLWriter) write(doc *Doc) string {
	var sb strings.Builder

	for _, block := range doc.Blocks {
		w.writeBlock(&sb, block, 0)
	}

	// Write footnotes
	if len(w.footnotes) > 0 {
		sb.WriteString("<section id=\"footnotes\" class=\"footnotes footnotes-end-of-document\"\nrole=\"doc-endnotes\">\n<hr />\n<ol>\n")
		for i, note := range w.footnotes {
			id := i + 1
			sb.WriteString(fmt.Sprintf("<li id=\"fn%d\">", id))
			// Write note content, adding backlink to last Para
			for j, block := range note {
				if j == len(note)-1 && block.Type == "Para" {
					// Add backlink
					var pbsb strings.Builder
					for k, il := range block.Inlines {
						_ = k
						w.writeInline(&pbsb, il)
					}
					content := pbsb.String()
					backlink := fmt.Sprintf("<a href=\"#fnref%d\"\nclass=\"footnote-back\" role=\"doc-backlink\">&#x21a9;&#xfe0e;</a>", id)
					sb.WriteString("<p>")
					sb.WriteString(content)
					sb.WriteString(backlink)
					sb.WriteString("</p>")
				} else {
					w.writeBlock(&sb, block, 0)
				}
			}
			sb.WriteString(fmt.Sprintf("</li>\n"))
		}
		sb.WriteString("</ol>\n</section>\n")
	}

	return sb.String()
}

func (w *HTMLWriter) uniqueID(id string) string {
	if id == "" {
		return ""
	}
	if count, ok := w.identifiers[id]; ok {
		w.identifiers[id]++
		return fmt.Sprintf("%s-%d", id, count+1)
	}
	w.identifiers[id] = 1
	return id
}

func (w *HTMLWriter) writeBlock(sb *strings.Builder, block Block, indent int) {
	switch block.Type {
	case "Para":
		sb.WriteString("<p>")
		for _, il := range block.Inlines {
			w.writeInline(sb, il)
		}
		sb.WriteString("</p>\n")

	case "Plain":
		for _, il := range block.Inlines {
			w.writeInline(sb, il)
		}
		sb.WriteString("\n")

	case "Header":
		tag := fmt.Sprintf("h%d", block.Level)
		id := block.Attr.ID
		if id == "" {
			// generate from content
			text := inlinesToText(block.Inlines)
			id = makeIdentifier(text)
		}
		id = w.uniqueID(id)

		classes := block.Attr.Classes

		attrs := ""
		if id != "" {
			attrs += fmt.Sprintf(" id=\"%s\"", htmlEscape(id))
		}
		if len(classes) > 0 {
			attrs += fmt.Sprintf(" class=\"%s\"", htmlEscape(strings.Join(classes, " ")))
		}
		for _, kv := range block.Attr.KVPairs {
			attrs += fmt.Sprintf(" %s=\"%s\"", kv[0], htmlEscape(kv[1]))
		}

		sb.WriteString("<" + tag + attrs + ">")
		for _, il := range block.Inlines {
			w.writeInline(sb, il)
		}
		sb.WriteString("</" + tag + ">\n")

	case "BlockQuote":
		sb.WriteString("<blockquote>\n")
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, indent+1)
		}
		sb.WriteString("</blockquote>\n")

	case "CodeBlock":
		lang := ""
		if len(block.Attr.Classes) > 0 {
			lang = block.Attr.Classes[0]
		}

		// Check if highlighting is enabled
		if w.opts.Highlight != "none" && lang != "" && isSupportedLang(lang) {
			w.writeHighlightedCode(sb, block)
		} else {
			if lang != "" {
				sb.WriteString(fmt.Sprintf("<pre class=\"%s\"><code>", htmlEscape(lang)))
			} else {
				sb.WriteString("<pre><code>")
			}
			sb.WriteString(htmlEscape(block.Code))
			sb.WriteString("</code></pre>\n")
		}

	case "RawBlock":
		if block.Format == "html" || block.Format == "html5" || block.Format == "html4" {
			sb.WriteString(block.Code)
			if !strings.HasSuffix(block.Code, "\n") {
				sb.WriteString("\n")
			}
		}

	case "HorizontalRule":
		sb.WriteString("<hr />\n")

	case "BulletList":
		w.writeBulletList(sb, block)

	case "OrderedList":
		w.writeOrderedList(sb, block)

	case "DefinitionList":
		w.writeDefinitionList(sb, block)

	case "Table":
		w.writeTable(sb, block)

	case "Figure":
		w.writeFigure(sb, block)

	case "Div":
		w.writeDiv(sb, block, indent)

	case "LineBlock":
		sb.WriteString("<div class=\"line-block\">\n")
		for _, line := range block.Lines {
			sb.WriteString("<span class=\"line\">")
			for _, il := range line {
				w.writeInline(sb, il)
			}
			sb.WriteString("</span><br />\n")
		}
		sb.WriteString("</div>\n")
	}
}

func (w *HTMLWriter) writeBulletList(sb *strings.Builder, block Block) {
	// Check if task list
	isTask := false
	for _, item := range block.Items {
		if len(item) > 0 {
			bl := item[0]
			if (bl.Type == "Plain" || bl.Type == "Para") && len(bl.Inlines) > 0 {
				first := bl.Inlines[0]
				if first.Type == "Str" && (first.Text == "[ ]" || first.Text == "[x]" || first.Text == "[X]") {
					isTask = true
					break
				}
			}
		}
	}

	if isTask {
		sb.WriteString("<ul class=\"task-list\">\n")
	} else {
		sb.WriteString("<ul>\n")
	}

	for _, item := range block.Items {
		if isTask {
			// Extract checkbox
			checked := false
			if len(item) > 0 {
				bl := &item[0]
				if (bl.Type == "Plain" || bl.Type == "Para") && len(bl.Inlines) > 0 {
					first := bl.Inlines[0]
					if first.Type == "Str" {
						if first.Text == "[x]" || first.Text == "[X]" {
							checked = true
							bl.Inlines = bl.Inlines[1:]
							if len(bl.Inlines) > 0 && bl.Inlines[0].Type == "Space" {
								bl.Inlines = bl.Inlines[1:]
							}
						} else if first.Text == "[ ]" {
							bl.Inlines = bl.Inlines[1:]
							if len(bl.Inlines) > 0 && bl.Inlines[0].Type == "Space" {
								bl.Inlines = bl.Inlines[1:]
							}
						}
					}
				}
			}
			sb.WriteString("<li>")
			if checked {
				sb.WriteString("<label><input type=\"checkbox\" checked=\"\" />")
			} else {
				sb.WriteString("<label><input type=\"checkbox\" />")
			}
			for _, b := range item {
				if b.Type == "Plain" {
					for _, il := range b.Inlines {
						w.writeInline(sb, il)
					}
				} else if b.Type == "Para" {
					for _, il := range b.Inlines {
						w.writeInline(sb, il)
					}
				} else {
					w.writeBlock(sb, b, 0)
				}
			}
			sb.WriteString("</label>")
		} else {
			sb.WriteString("<li>")
			for i, b := range item {
				if b.Type == "Plain" {
					for _, il := range b.Inlines {
						w.writeInline(sb, il)
					}
					if i < len(item)-1 {
						sb.WriteString("\n")
					}
				} else {
					w.writeBlock(sb, b, 1)
				}
			}
		}
		sb.WriteString("</li>\n")
	}
	sb.WriteString("</ul>\n")
}

func (w *HTMLWriter) writeOrderedList(sb *strings.Builder, block Block) {
	attr := ""
	la := block.ListAttr
	if la.Start != 1 {
		attr += fmt.Sprintf(" start=\"%d\"", la.Start)
	}
	switch la.Style {
	case "LowerAlpha":
		attr += " type=\"a\""
	case "UpperAlpha":
		attr += " type=\"A\""
	case "LowerRoman":
		attr += " type=\"i\""
	case "UpperRoman":
		attr += " type=\"I\""
	}

	sb.WriteString("<ol" + attr + ">\n")
	for _, item := range block.Items {
		sb.WriteString("<li>")
		for _, b := range item {
			if b.Type == "Plain" {
				for _, il := range b.Inlines {
					w.writeInline(sb, il)
				}
			} else {
				w.writeBlock(sb, b, 1)
			}
		}
		sb.WriteString("</li>\n")
	}
	sb.WriteString("</ol>\n")
}

func (w *HTMLWriter) writeDefinitionList(sb *strings.Builder, block Block) {
	sb.WriteString("<dl>\n")
	for _, item := range block.DefItems {
		sb.WriteString("<dt>")
		for _, il := range item.Term {
			w.writeInline(sb, il)
		}
		sb.WriteString("</dt>\n")
		for _, def := range item.Defs {
			sb.WriteString("<dd>\n")
			for _, b := range def {
				w.writeBlock(sb, b, 1)
			}
			sb.WriteString("</dd>\n")
		}
	}
	sb.WriteString("</dl>\n")
}

func (w *HTMLWriter) writeTable(sb *strings.Builder, block Block) {
	td := block.Table
	if td == nil {
		return
	}

	sb.WriteString("<table>\n")

	// Caption
	if len(td.Caption.Blocks) > 0 {
		sb.WriteString("<caption>")
		for _, b := range td.Caption.Blocks {
			if b.Type == "Plain" || b.Type == "Para" {
				for _, il := range b.Inlines {
					w.writeInline(sb, il)
				}
			}
		}
		sb.WriteString("</caption>\n")
	}

	// Head
	if len(td.Head.Rows) > 0 {
		sb.WriteString("<thead>\n")
		for _, row := range td.Head.Rows {
			sb.WriteString("<tr>\n")
			for _, cell := range row.Cells {
				alignAttr := ""
				if cell.Align != "AlignDefault" && cell.Align != "" {
					switch cell.Align {
					case "AlignLeft":
						alignAttr = " style=\"text-align: left;\""
					case "AlignRight":
						alignAttr = " style=\"text-align: right;\""
					case "AlignCenter":
						alignAttr = " style=\"text-align: center;\""
					}
				}
				sb.WriteString("<th" + alignAttr + ">")
				for _, b := range cell.Blocks {
					if b.Type == "Plain" || b.Type == "Para" {
						for _, il := range b.Inlines {
							w.writeInline(sb, il)
						}
					} else {
						w.writeBlock(sb, b, 0)
					}
				}
				sb.WriteString("</th>\n")
			}
			sb.WriteString("</tr>\n")
		}
		sb.WriteString("</thead>\n")
	}

	// Body
	if len(td.Bodies) > 0 {
		sb.WriteString("<tbody>\n")
		for _, body := range td.Bodies {
			for _, row := range body.Rows {
				sb.WriteString("<tr>\n")
				for _, cell := range row.Cells {
					alignAttr := ""
					if cell.Align != "AlignDefault" && cell.Align != "" {
						switch cell.Align {
						case "AlignLeft":
							alignAttr = " style=\"text-align: left;\""
						case "AlignRight":
							alignAttr = " style=\"text-align: right;\""
						case "AlignCenter":
							alignAttr = " style=\"text-align: center;\""
						}
					}
					sb.WriteString("<td" + alignAttr + ">")
					for _, b := range cell.Blocks {
						if b.Type == "Plain" || b.Type == "Para" {
							for _, il := range b.Inlines {
								w.writeInline(sb, il)
							}
						} else {
							w.writeBlock(sb, b, 0)
						}
					}
					sb.WriteString("</td>\n")
				}
				sb.WriteString("</tr>\n")
			}
		}
		sb.WriteString("</tbody>\n")
	}

	sb.WriteString("</table>\n")
}

func (w *HTMLWriter) writeFigure(sb *strings.Builder, block Block) {
	sb.WriteString("<figure>\n")
	for _, b := range block.Blocks {
		if b.Type == "Plain" || b.Type == "Para" {
			for _, il := range b.Inlines {
				w.writeInline(sb, il)
			}
			sb.WriteString("\n")
		} else {
			w.writeBlock(sb, b, 0)
		}
	}
	// Caption
	if block.Table != nil && len(block.Table.Caption.Blocks) > 0 {
		sb.WriteString("<figcaption aria-hidden=\"true\">")
		for _, b := range block.Table.Caption.Blocks {
			if b.Type == "Plain" || b.Type == "Para" {
				for _, il := range b.Inlines {
					w.writeInline(sb, il)
				}
			}
		}
		sb.WriteString("</figcaption>\n")
	}
	sb.WriteString("</figure>\n")
}

func (w *HTMLWriter) writeDiv(sb *strings.Builder, block Block, indent int) {
	attr := buildHTMLAttr(block.Attr)
	sb.WriteString("<div" + attr + ">\n")
	for _, b := range block.Blocks {
		w.writeBlock(sb, b, indent+1)
	}
	sb.WriteString("</div>\n")
}

func buildHTMLAttr(attr Attr) string {
	var parts []string
	if attr.ID != "" {
		parts = append(parts, fmt.Sprintf("id=\"%s\"", htmlEscape(attr.ID)))
	}
	if len(attr.Classes) > 0 {
		parts = append(parts, fmt.Sprintf("class=\"%s\"", htmlEscape(strings.Join(attr.Classes, " "))))
	}
	for _, kv := range attr.KVPairs {
		parts = append(parts, fmt.Sprintf("%s=\"%s\"", kv[0], htmlEscape(kv[1])))
	}
	if len(parts) == 0 {
		return ""
	}
	return " " + strings.Join(parts, " ")
}

func (w *HTMLWriter) writeInline(sb *strings.Builder, il Inline) {
	switch il.Type {
	case "Str":
		sb.WriteString(htmlEscape(il.Text))
	case "Space":
		sb.WriteString(" ")
	case "SoftBreak":
		sb.WriteString(" ")
	case "LineBreak":
		sb.WriteString("<br />\n")
	case "Emph":
		sb.WriteString("<em>")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</em>")
	case "Strong":
		sb.WriteString("<strong>")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</strong>")
	case "Strikeout":
		sb.WriteString("<del>")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</del>")
	case "Superscript":
		sb.WriteString("<sup>")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</sup>")
	case "Subscript":
		sb.WriteString("<sub>")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</sub>")
	case "SmallCaps":
		sb.WriteString("<span style=\"font-variant: small-caps;\">")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</span>")
	case "Quoted":
		if il.QuoteType == "DoubleQuote" {
			sb.WriteString("\u201c")
			for _, child := range il.Inlines {
				w.writeInline(sb, child)
			}
			sb.WriteString("\u201d")
		} else {
			sb.WriteString("\u2018")
			for _, child := range il.Inlines {
				w.writeInline(sb, child)
			}
			sb.WriteString("\u2019")
		}
	case "Code":
		attr := buildHTMLAttr(il.Attr)
		sb.WriteString("<code" + attr + ">")
		sb.WriteString(htmlEscape(il.Text))
		sb.WriteString("</code>")
	case "Math":
		if il.MathType == "DisplayMath" {
			sb.WriteString("<span class=\"math display\">")
			sb.WriteString(renderMathHTML(il.Text, true))
			sb.WriteString("</span>")
		} else {
			sb.WriteString("<span class=\"math inline\">")
			sb.WriteString(renderMathHTML(il.Text, false))
			sb.WriteString("</span>")
		}
	case "Link":
		attr := buildHTMLAttr(il.Attr)
		href := htmlEscape(il.Target.URL)
		title := ""
		if il.Target.Title != "" {
			title = fmt.Sprintf(" title=\"%s\"", htmlEscape(il.Target.Title))
		}
		sb.WriteString("<a href=\"" + href + "\"" + title + attr + ">")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</a>")
	case "Image":
		attr := buildHTMLAttr(il.Attr)
		src := htmlEscape(il.Target.URL)
		alt := htmlEscape(inlinesToText(il.Inlines))
		title := ""
		if il.Target.Title != "" {
			title = fmt.Sprintf(" title=\"%s\"", htmlEscape(il.Target.Title))
		}
		sb.WriteString("<img src=\"" + src + "\"" + title + " alt=\"" + alt + "\"" + attr + " />")
	case "RawInline":
		if il.Format == "html" || il.Format == "html5" {
			sb.WriteString(il.Text)
		}
	case "Span":
		attr := buildHTMLAttr(il.Attr)
		sb.WriteString("<span" + attr + ">")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("</span>")
	case "Note":
		w.footnoteID++
		id := w.footnoteID
		sb.WriteString(fmt.Sprintf("<a href=\"#fn%d\" class=\"footnote-ref\" id=\"fnref%d\"\nrole=\"doc-noteref\"><sup>%d</sup></a>", id, id, id))
		w.footnotes = append(w.footnotes, il.Blocks)
	case "Cite":
		// Simplified citation rendering
		sb.WriteString("[")
		for i, cit := range il.Citations {
			if i > 0 {
				sb.WriteString("; ")
			}
			sb.WriteString("@" + cit.ID)
		}
		sb.WriteString("]")
	}
}

func renderMathHTML(math string, display bool) string {
	// Convert LaTeX math to HTML
	// This is a simplified version - just render with unicode where possible
	result := latexMathToHTML(math)
	return result
}

func latexMathToHTML(math string) string {
	// Very basic LaTeX to HTML math conversion
	result := math
	// Superscripts: x^2 -> x<sup>2</sup>
	re := regexp.MustCompile(`\^(\{([^}]*)\}|([a-zA-Z0-9]))}?`)
	result = re.ReplaceAllStringFunc(result, func(m string) string {
		m2 := re.FindStringSubmatch(m)
		content := m2[2]
		if content == "" {
			content = m2[3]
		}
		return "<sup>" + content + "</sup>"
	})
	// Subscripts
	reSub := regexp.MustCompile(`_\{([^}]*)\}|_([a-zA-Z0-9])`)
	result = reSub.ReplaceAllStringFunc(result, func(m string) string {
		m2 := reSub.FindStringSubmatch(m)
		content := m2[1]
		if content == "" {
			content = m2[2]
		}
		return "<sub>" + content + "</sub>"
	})
	// Greek letters
	greekLetters := map[string]string{
		"alpha": "α", "beta": "β", "gamma": "γ", "delta": "δ",
		"epsilon": "ε", "theta": "θ", "lambda": "λ", "mu": "μ",
		"pi": "π", "sigma": "σ", "tau": "τ", "phi": "φ", "omega": "ω",
		"Alpha": "Α", "Beta": "Β", "Gamma": "Γ", "Delta": "Δ",
	}
	for name, sym := range greekLetters {
		result = strings.ReplaceAll(result, "\\"+name, sym)
	}
	// Basic operators
	result = strings.ReplaceAll(result, "\\cdot", "·")
	result = strings.ReplaceAll(result, "\\times", "×")
	result = strings.ReplaceAll(result, "\\div", "÷")
	result = strings.ReplaceAll(result, "\\pm", "±")
	result = strings.ReplaceAll(result, "\\infty", "∞")
	result = strings.ReplaceAll(result, "\\sum", "∑")
	result = strings.ReplaceAll(result, "\\int", "∫")
	result = strings.ReplaceAll(result, "\\sqrt", "√")

	// Italicize variables (basic heuristic)
	reVar := regexp.MustCompile(`([a-zA-Z])`)
	result = reVar.ReplaceAllStringFunc(result, func(m string) string {
		return "<em>" + m + "</em>"
	})

	return result
}

func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

func inlinesToText(inlines []Inline) string {
	var sb strings.Builder
	for _, il := range inlines {
		switch il.Type {
		case "Str":
			sb.WriteString(il.Text)
		case "Space":
			sb.WriteString(" ")
		case "SoftBreak":
			sb.WriteString(" ")
		case "LineBreak":
			sb.WriteString(" ")
		case "Emph", "Strong", "Strikeout", "Superscript", "Subscript", "SmallCaps", "Span":
			sb.WriteString(inlinesToText(il.Inlines))
		case "Quoted":
			sb.WriteString(inlinesToText(il.Inlines))
		case "Code":
			sb.WriteString(il.Text)
		case "Math":
			sb.WriteString(il.Text)
		case "Link":
			sb.WriteString(inlinesToText(il.Inlines))
		case "Image":
			sb.WriteString(inlinesToText(il.Inlines))
		}
	}
	return sb.String()
}

// Syntax highlighting support
func isSupportedLang(lang string) bool {
	supported := map[string]bool{
		"python": true, "haskell": true, "javascript": true, "java": true,
		"c": true, "cpp": true, "go": true, "rust": true, "ruby": true,
		"bash": true, "sh": true, "shell": true, "html": true, "css": true,
		"xml": true, "json": true, "yaml": true, "sql": true, "markdown": true,
		"typescript": true, "php": true, "perl": true, "r": true, "scala": true,
		"kotlin": true, "swift": true, "lua": true, "latex": true,
		"ocaml": true, "fsharp": true, "elm": true, "clojure": true,
		"dockerfile": true, "makefile": true, "diff": true, "cs": true,
	}
	return supported[strings.ToLower(lang)]
}

func (w *HTMLWriter) writeHighlightedCode(sb *strings.Builder, block Block) {
	lang := ""
	if len(block.Attr.Classes) > 0 {
		lang = block.Attr.Classes[0]
	}

	w.codeBlockID++
	cbID := "cb" + strconv.Itoa(w.codeBlockID)

	sb.WriteString(fmt.Sprintf("<div class=\"sourceCode\" id=\"%s\"><pre\nclass=\"sourceCode %s\"><code class=\"sourceCode %s\">",
		cbID, htmlEscape(lang), htmlEscape(lang)))

	lines := strings.Split(block.Code, "\n")
	for i, line := range lines {
		lineID := fmt.Sprintf("%s-%d", cbID, i+1)
		sb.WriteString(fmt.Sprintf("<span id=\"%s\"><a href=\"#%s\" aria-hidden=\"true\" tabindex=\"-1\"></a>",
			lineID, lineID))
		highlighted := highlightLine(line, lang)
		sb.WriteString(highlighted)
		sb.WriteString("</span>")
		if i < len(lines)-1 {
			sb.WriteString("\n")
		}
	}

	sb.WriteString("</code></pre></div>\n")
}

func highlightLine(line string, lang string) string {
	// Very simplified syntax highlighting
	// This would need a proper syntax highlighter for full compatibility
	result := htmlEscape(line)

	switch strings.ToLower(lang) {
	case "python":
		result = highlightPython(line)
	case "haskell":
		result = highlightHaskell(line)
	case "javascript", "typescript":
		result = highlightJS(line)
	default:
		result = htmlEscape(line)
	}

	return result
}

func highlightPython(line string) string {
	// Basic Python highlighting
	var result strings.Builder
	i := 0

	for i < len(line) {
		// String literals
		if line[i] == '"' || line[i] == '\'' {
			q := line[i]
			result.WriteString("<span class=\"st\">")
			result.WriteByte(q)
			i++
			for i < len(line) {
				if line[i] == '\\' && i+1 < len(line) {
					result.WriteString(htmlEscapeChar(line[i]))
					result.WriteString(htmlEscapeChar(line[i+1]))
					i += 2
				} else if line[i] == q {
					result.WriteByte(q)
					i++
					break
				} else {
					result.WriteString(htmlEscapeChar(line[i]))
					i++
				}
			}
			result.WriteString("</span>")
			continue
		}

		// Comments
		if line[i] == '#' {
			result.WriteString("<span class=\"co\">")
			for i < len(line) {
				result.WriteString(htmlEscapeChar(line[i]))
				i++
			}
			result.WriteString("</span>")
			continue
		}

		// Keywords and builtins
		if isIdentStart(line[i]) {
			start := i
			for i < len(line) && isIdentChar(line[i]) {
				i++
			}
			word := line[start:i]
			if isPythonKeyword(word) {
				result.WriteString("<span class=\"kw\">" + htmlEscape(word) + "</span>")
			} else if isPythonBuiltin(word) {
				result.WriteString("<span class=\"bu\">" + htmlEscape(word) + "</span>")
			} else {
				result.WriteString(htmlEscape(word))
			}
			continue
		}

		result.WriteString(htmlEscapeChar(line[i]))
		i++
	}

	return result.String()
}

func highlightHaskell(line string) string {
	var result strings.Builder
	i := 0

	for i < len(line) {
		// String literals
		if line[i] == '"' {
			result.WriteString("<span class=\"st\">\"")
			i++
			for i < len(line) && line[i] != '"' {
				if line[i] == '\\' && i+1 < len(line) {
					result.WriteString(htmlEscapeChar(line[i]))
					result.WriteString(htmlEscapeChar(line[i+1]))
					i += 2
				} else {
					result.WriteString(htmlEscapeChar(line[i]))
					i++
				}
			}
			if i < len(line) {
				result.WriteString("\"")
				i++
			}
			result.WriteString("</span>")
			continue
		}

		// Comments
		if i+1 < len(line) && line[i] == '-' && line[i+1] == '-' {
			result.WriteString("<span class=\"co\">")
			for i < len(line) {
				result.WriteString(htmlEscapeChar(line[i]))
				i++
			}
			result.WriteString("</span>")
			continue
		}

		// Type signatures (::)
		if i+1 < len(line) && line[i] == ':' && line[i+1] == ':' {
			result.WriteString("<span class=\"ot\">::</span>")
			i += 2
			continue
		}

		// Arrows
		if i+1 < len(line) && line[i] == '-' && line[i+1] == '>' {
			result.WriteString("<span class=\"ot\">-&gt;</span>")
			i += 2
			continue
		}

		// Operators
		if isHaskellOp(line[i]) {
			result.WriteString("<span class=\"op\">" + htmlEscapeChar(line[i]) + "</span>")
			i++
			continue
		}

		// Keywords and types
		if isIdentStart(line[i]) {
			start := i
			for i < len(line) && isIdentChar(line[i]) {
				i++
			}
			word := line[start:i]
			if isHaskellKeyword(word) {
				result.WriteString("<span class=\"kw\">" + htmlEscape(word) + "</span>")
			} else if len(word) > 0 && word[0] >= 'A' && word[0] <= 'Z' {
				result.WriteString("<span class=\"dt\">" + htmlEscape(word) + "</span>")
			} else {
				result.WriteString(htmlEscape(word))
			}
			continue
		}

		// Numbers
		if line[i] >= '0' && line[i] <= '9' {
			start := i
			for i < len(line) && (line[i] >= '0' && line[i] <= '9' || line[i] == '.') {
				i++
			}
			result.WriteString("<span class=\"dv\">" + htmlEscape(line[start:i]) + "</span>")
			continue
		}

		result.WriteString(htmlEscapeChar(line[i]))
		i++
	}

	return result.String()
}

func highlightJS(line string) string {
	var result strings.Builder
	i := 0

	for i < len(line) {
		// String literals
		if line[i] == '"' || line[i] == '\'' || line[i] == '`' {
			q := line[i]
			result.WriteString("<span class=\"st\">")
			result.WriteByte(q)
			i++
			for i < len(line) && line[i] != q {
				if line[i] == '\\' && i+1 < len(line) {
					result.WriteString(htmlEscapeChar(line[i]))
					result.WriteString(htmlEscapeChar(line[i+1]))
					i += 2
				} else {
					result.WriteString(htmlEscapeChar(line[i]))
					i++
				}
			}
			if i < len(line) {
				result.WriteByte(q)
				i++
			}
			result.WriteString("</span>")
			continue
		}

		// Comments
		if i+1 < len(line) && line[i] == '/' && line[i+1] == '/' {
			result.WriteString("<span class=\"co\">")
			for i < len(line) {
				result.WriteString(htmlEscapeChar(line[i]))
				i++
			}
			result.WriteString("</span>")
			continue
		}

		// Keywords
		if isIdentStart(line[i]) {
			start := i
			for i < len(line) && isIdentChar(line[i]) {
				i++
			}
			word := line[start:i]
			if isJSKeyword(word) {
				result.WriteString("<span class=\"kw\">" + htmlEscape(word) + "</span>")
			} else {
				result.WriteString(htmlEscape(word))
			}
			continue
		}

		result.WriteString(htmlEscapeChar(line[i]))
		i++
	}

	return result.String()
}

func htmlEscapeChar(c byte) string {
	switch c {
	case '&':
		return "&amp;"
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '"':
		return "&quot;"
	default:
		return string(c)
	}
}

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}

func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '\''
}

func isHaskellOp(c byte) bool {
	return c == '=' || c == '+' || c == '*' || c == '/' || c == '|' || c == '\\' || c == '.'
}

func isPythonKeyword(w string) bool {
	keywords := map[string]bool{
		"False": true, "None": true, "True": true, "and": true, "as": true,
		"assert": true, "async": true, "await": true, "break": true,
		"class": true, "continue": true, "def": true, "del": true,
		"elif": true, "else": true, "except": true, "finally": true,
		"for": true, "from": true, "global": true, "if": true, "import": true,
		"in": true, "is": true, "lambda": true, "nonlocal": true, "not": true,
		"or": true, "pass": true, "raise": true, "return": true, "try": true,
		"while": true, "with": true, "yield": true,
	}
	return keywords[w]
}

func isPythonBuiltin(w string) bool {
	builtins := map[string]bool{
