		"all": true, "next": true, "iter": true, "callable": true,
	}
	return builtins[w]
}

func isHaskellKeyword(w string) bool {
	keywords := map[string]bool{
		"case": true, "class": true, "data": true, "default": true, "deriving": true,
		"do": true, "else": true, "forall": true, "if": true, "import": true,
		"in": true, "infix": true, "infixl": true, "infixr": true, "instance": true,
		"let": true, "module": true, "newtype": true, "of": true, "qualified": true,
		"then": true, "type": true, "where": true, "as": true, "hiding": true,
