package main

import (
	"fmt"
	"strings"
)

// Plain text writer
type PlainWriter struct {
	opts    *Options
	columns int
}

func newPlainWriter(opts *Options) *PlainWriter {
	cols := opts.Columns
	if cols <= 0 {
		cols = 72
	}
	return &PlainWriter{opts: opts, columns: cols}
}

func (w *PlainWriter) write(doc *Doc) string {
	var sb strings.Builder
	for i, block := range doc.Blocks {
		if i > 0 {
			sb.WriteString("\n")
		}
		w.writeBlock(&sb, block)
	}
	return sb.String()
}

func (w *PlainWriter) writeBlock(sb *strings.Builder, block Block) {
	switch block.Type {
	case "Para", "Plain":
		text := inlinesToText(block.Inlines)
		if w.opts.Wrap == "none" {
			sb.WriteString(text)
		} else {
			sb.WriteString(wrapText(text, w.columns))
		}
		sb.WriteString("\n")
	case "Header":
		text := inlinesToText(block.Inlines)
		sb.WriteString(text)
		sb.WriteString("\n")
	case "BlockQuote":
		for _, b := range block.Blocks {
			w.writeBlock(sb, b)
		}
	case "CodeBlock":
		lines := strings.Split(block.Code, "\n")
		for _, line := range lines {
			sb.WriteString(line)
			sb.WriteString("\n")
		}
	case "HorizontalRule":
		sb.WriteString("------------------------------------------------------------------------\n")
	case "BulletList":
		for _, item := range block.Items {
			prefix := "- "
			for i, b := range item {
				if i == 0 {
					text := ""
					if b.Type == "Plain" || b.Type == "Para" {
						text = inlinesToText(b.Inlines)
					}
					lines := strings.Split(wrapText(text, w.columns-len(prefix)), "\n")
					for j, line := range lines {
						if j == 0 {
							sb.WriteString(prefix + line + "\n")
						} else if line != "" {
							sb.WriteString(strings.Repeat(" ", len(prefix)) + line + "\n")
						}
					}
				} else {
					w.writeBlock(sb, b)
				}
			}
		}
	case "OrderedList":
		for idx, item := range block.Items {
			num := block.ListAttr.Start + idx
			prefix := fmt.Sprintf("%d.  ", num)
			for i, b := range item {
				if i == 0 {
					text := ""
					if b.Type == "Plain" || b.Type == "Para" {
						text = inlinesToText(b.Inlines)
					}
					sb.WriteString(prefix + text + "\n")
				} else {
					w.writeBlock(sb, b)
				}
			}
		}
	case "DefinitionList":
		for _, item := range block.DefItems {
			sb.WriteString(inlinesToText(item.Term) + "\n")
			for _, def := range item.Defs {
				for _, b := range def {
					w.writeBlock(sb, b)
				}
			}
		}
	case "Table":
		// Simplified table output
		sb.WriteString("\n")
	case "RawBlock":
		// Skip raw blocks in plain output
	case "Div":
		for _, b := range block.Blocks {
			w.writeBlock(sb, b)
		}
	case "LineBlock":
		for _, line := range block.Lines {
			sb.WriteString(inlinesToText(line) + "\n")
		}
	}
}

func wrapText(text string, cols int) string {
	if cols <= 0 {
		return text
	}
	words := strings.Fields(text)
	if len(words) == 0 {
		return ""
	}

	var lines []string
	var currentLine strings.Builder
	currentLen := 0

	for _, word := range words {
		wordLen := len(word)
		if currentLen == 0 {
			currentLine.WriteString(word)
			currentLen = wordLen
		} else if currentLen+1+wordLen <= cols {
			currentLine.WriteString(" ")
			currentLine.WriteString(word)
			currentLen += 1 + wordLen
		} else {
			lines = append(lines, currentLine.String())
			currentLine.Reset()
			currentLine.WriteString(word)
			currentLen = wordLen
		}
	}
	if currentLine.Len() > 0 {
		lines = append(lines, currentLine.String())
	}

	return strings.Join(lines, "\n")
}

// Markdown writer
type MarkdownWriter struct {
	opts *Options
}

func newMarkdownWriter(opts *Options) *MarkdownWriter {
	return &MarkdownWriter{opts: opts}
}

func (w *MarkdownWriter) write(doc *Doc) string {
	var sb strings.Builder

	// Write metadata if present
	if len(doc.Meta) > 0 {
		sb.WriteString("---\n")
		for key, val := range doc.Meta {
			sb.WriteString(key + ": ")
			sb.WriteString(metaValToMarkdown(val))
			sb.WriteString("\n")
		}
		sb.WriteString("---\n\n")
	}

	for i, block := range doc.Blocks {
		if i > 0 {
			sb.WriteString("\n")
		}
		w.writeBlock(&sb, block, 0)
	}
	return sb.String()
}

func metaValToMarkdown(mv MetaVal) string {
	switch mv.Type {
	case "MetaInlines":
		return inlinesToMarkdown(mv.Inlines)
	case "MetaString":
		return mv.Str
	case "MetaList":
		var parts []string
		for _, item := range mv.List {
			parts = append(parts, metaValToMarkdown(item))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	return ""
}

func (w *MarkdownWriter) writeBlock(sb *strings.Builder, block Block, indent int) {
	prefix := strings.Repeat("  ", indent)

	switch block.Type {
	case "Para":
		text := inlinesToMarkdown(block.Inlines)
		sb.WriteString(prefix)
		if w.opts.Wrap == "none" {
			sb.WriteString(text)
		} else {
			sb.WriteString(wrapMarkdown(text, w.opts.Columns, indent*2))
		}
		sb.WriteString("\n")
	case "Plain":
		text := inlinesToMarkdown(block.Inlines)
		sb.WriteString(prefix + text + "\n")
	case "Header":
		w.writeHeader(sb, block)
	case "BlockQuote":
		for _, b := range block.Blocks {
			var bsb strings.Builder
			w.writeBlock(&bsb, b, 0)
			lines := strings.Split(strings.TrimRight(bsb.String(), "\n"), "\n")
			for _, line := range lines {
				if line == "" {
					sb.WriteString(">\n")
				} else {
					sb.WriteString("> " + line + "\n")
				}
			}
		}
	case "CodeBlock":
		lang := ""
		if len(block.Attr.Classes) > 0 {
			lang = block.Attr.Classes[0]
		}
		id := block.Attr.ID
		extraAttrs := ""
		if id != "" {
			extraAttrs += " #" + id
		}
		for _, cls := range block.Attr.Classes[1:] {
			extraAttrs += " ." + cls
		}
		for _, kv := range block.Attr.KVPairs {
			extraAttrs += " " + kv[0] + "=" + kv[1]
		}
		if lang != "" || extraAttrs != "" {
			sb.WriteString("```" + lang + extraAttrs + "\n")
		} else {
			sb.WriteString("```\n")
		}
		sb.WriteString(block.Code + "\n")
		sb.WriteString("```\n")
	case "RawBlock":
		sb.WriteString(block.Code + "\n")
	case "HorizontalRule":
		sb.WriteString(strings.Repeat("-", 72) + "\n")
	case "BulletList":
		for _, item := range block.Items {
			w.writeListItem(sb, item, "- ", 2)
		}
	case "OrderedList":
		for idx, item := range block.Items {
			num := block.ListAttr.Start + idx
			marker := fmt.Sprintf("%d. ", num)
			// Pad to at least 4 chars
			for len(marker) < 4 {
				marker += " "
			}
			w.writeListItem(sb, item, marker, len(marker))
		}
	case "DefinitionList":
		for _, item := range block.DefItems {
			sb.WriteString(inlinesToMarkdown(item.Term) + "\n")
			for _, def := range item.Defs {
				for _, b := range def {
					var bsb strings.Builder
					w.writeBlock(&bsb, b, 0)
					lines := strings.Split(strings.TrimRight(bsb.String(), "\n"), "\n")
					for j, line := range lines {
						if j == 0 {
							sb.WriteString(":   " + line + "\n")
						} else {
							sb.WriteString("    " + line + "\n")
						}
					}
				}
			}
		}
	case "Table":
		w.writeTable(sb, block)
	case "Figure":
		// Write the image inline
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, 0)
		}
	case "Div":
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, 0)
		}
	case "LineBlock":
		for _, line := range block.Lines {
			sb.WriteString("| " + inlinesToMarkdown(line) + "\n")
		}
	}
}

func (w *MarkdownWriter) writeHeader(sb *strings.Builder, block Block) {
	atx := w.opts.MarkdownHeadings != "setext"

	if !atx && block.Level <= 2 {
		text := inlinesToMarkdown(block.Inlines)
		sb.WriteString(text + "\n")
		if block.Level == 1 {
			sb.WriteString(strings.Repeat("=", len(text)) + "\n")
		} else {
			sb.WriteString(strings.Repeat("-", len(text)) + "\n")
		}
	} else {
		sb.WriteString(strings.Repeat("#", block.Level) + " ")
		sb.WriteString(inlinesToMarkdown(block.Inlines))
		sb.WriteString("\n")
	}
}

func (w *MarkdownWriter) writeListItem(sb *strings.Builder, item []Block, marker string, indent int) {
	indentStr := strings.Repeat(" ", indent)
	for i, b := range item {
		var bsb strings.Builder
		w.writeBlock(&bsb, b, 0)
		content := strings.TrimRight(bsb.String(), "\n")
		if i == 0 {
			lines := strings.Split(content, "\n")
			for j, line := range lines {
				if j == 0 {
					sb.WriteString(marker + line + "\n")
				} else if line != "" {
					sb.WriteString(indentStr + line + "\n")
				}
			}
		} else {
			lines := strings.Split(content, "\n")
			for _, line := range lines {
				if line != "" {
					sb.WriteString(indentStr + line + "\n")
				}
			}
		}
	}
}

func (w *MarkdownWriter) writeTable(sb *strings.Builder, block Block) {
	td := block.Table
	if td == nil {
		return
	}

	if len(td.Head.Rows) == 0 {
		return
	}

	// Get column count
	numCols := len(td.ColSpecs)
	if numCols == 0 && len(td.Head.Rows) > 0 {
		numCols = len(td.Head.Rows[0].Cells)
	}

	// Get header cells
	var headers []string
	if len(td.Head.Rows) > 0 {
		for _, cell := range td.Head.Rows[0].Cells {
			text := ""
			for _, b := range cell.Blocks {
				if b.Type == "Plain" || b.Type == "Para" {
					text = inlinesToMarkdown(b.Inlines)
				}
			}
			headers = append(headers, text)
		}
	}

	// Get body rows
	var bodyRows [][]string
	for _, body := range td.Bodies {
		for _, row := range body.Rows {
			var cells []string
			for _, cell := range row.Cells {
				text := ""
				for _, b := range cell.Blocks {
					if b.Type == "Plain" || b.Type == "Para" {
						text = inlinesToMarkdown(b.Inlines)
					}
				}
				cells = append(cells, text)
			}
			bodyRows = append(bodyRows, cells)
		}
	}

	// Calculate column widths
	colWidths := make([]int, numCols)
	for i := 0; i < numCols; i++ {
		if i < len(headers) {
			if len(headers[i]) > colWidths[i] {
				colWidths[i] = len(headers[i])
			}
		}
		for _, row := range bodyRows {
			if i < len(row) && len(row[i]) > colWidths[i] {
				colWidths[i] = len(row[i])
			}
		}
		if colWidths[i] < 3 {
			colWidths[i] = 3
		}
	}

	// Use simple table format (two-space separated)
	// Write header
	for i := 0; i < numCols; i++ {
		h := ""
		if i < len(headers) {
			h = headers[i]
		}
		sb.WriteString(padRight(h, colWidths[i]))
		if i < numCols-1 {
			sb.WriteString("   ")
		}
	}
	sb.WriteString("\n")

	// Write separator
	for i := 0; i < numCols; i++ {
		sb.WriteString(strings.Repeat("-", colWidths[i]))
		if i < numCols-1 {
			sb.WriteString("   ")
		}
	}
	sb.WriteString("\n")

	// Write body
	for _, row := range bodyRows {
		for i := 0; i < numCols; i++ {
			cell := ""
			if i < len(row) {
				cell = row[i]
			}
			sb.WriteString(padRight(cell, colWidths[i]))
			if i < numCols-1 {
				sb.WriteString("   ")
			}
		}
		sb.WriteString("\n")
	}
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func wrapMarkdown(text string, cols int, indent int) string {
	if cols <= 0 {
		return text
	}
	effective := cols - indent
	if effective < 20 {
		effective = 20
	}
	return wrapText(text, effective)
}

func inlinesToMarkdown(inlines []Inline) string {
	var sb strings.Builder
	for _, il := range inlines {
		writeInlineMarkdown(&sb, il)
	}
	return sb.String()
}

func writeInlineMarkdown(sb *strings.Builder, il Inline) {
	switch il.Type {
	case "Str":
		sb.WriteString(il.Text)
	case "Space":
		sb.WriteString(" ")
	case "SoftBreak":
		sb.WriteString(" ")
	case "LineBreak":
		sb.WriteString("  \n")
	case "Emph":
		sb.WriteString("*")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("*")
	case "Strong":
		sb.WriteString("**")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("**")
	case "Strikeout":
		sb.WriteString("~~")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("~~")
	case "Superscript":
		sb.WriteString("^")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("^")
	case "Subscript":
		sb.WriteString("~")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("~")
	case "SmallCaps":
		sb.WriteString("[")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("]{.smallcaps}")
	case "Quoted":
		if il.QuoteType == "DoubleQuote" {
			sb.WriteString("\u201c")
			for _, child := range il.Inlines {
				writeInlineMarkdown(sb, child)
			}
			sb.WriteString("\u201d")
		} else {
			sb.WriteString("\u2018")
			for _, child := range il.Inlines {
				writeInlineMarkdown(sb, child)
			}
			sb.WriteString("\u2019")
		}
	case "Code":
		sb.WriteString("`" + il.Text + "`")
	case "Math":
		if il.MathType == "DisplayMath" {
			sb.WriteString("$$" + il.Text + "$$")
		} else {
			sb.WriteString("$" + il.Text + "$")
		}
	case "Link":
		sb.WriteString("[")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("](")
		sb.WriteString(il.Target.URL)
		if il.Target.Title != "" {
			sb.WriteString(" \"" + il.Target.Title + "\"")
		}
		sb.WriteString(")")
	case "Image":
		sb.WriteString("![")
		for _, child := range il.Inlines {
			writeInlineMarkdown(sb, child)
		}
		sb.WriteString("](")
		sb.WriteString(il.Target.URL)
		if il.Target.Title != "" {
			sb.WriteString(" \"" + il.Target.Title + "\"")
		}
		sb.WriteString(")")
	case "RawInline":
		sb.WriteString(il.Text)
	case "Span":
		// Check for smallcaps
		if il.Attr.hasClass("smallcaps") {
			sb.WriteString("[")
			for _, child := range il.Inlines {
				writeInlineMarkdown(sb, child)
			}
			sb.WriteString("]{.smallcaps}")
		} else {
			for _, child := range il.Inlines {
				writeInlineMarkdown(sb, child)
			}
		}
	case "Note":
		sb.WriteString("[^")
		for _, b := range il.Blocks {
			if b.Type == "Para" {
				sb.WriteString(inlinesToMarkdown(b.Inlines))
			}
		}
		sb.WriteString("]")
	}
}

// RST writer
type RSTWriter struct {
	opts *Options
}

func newRSTWriter(opts *Options) *RSTWriter {
	return &RSTWriter{opts: opts}
}

func (w *RSTWriter) write(doc *Doc) string {
	var sb strings.Builder
	for i, block := range doc.Blocks {
		if i > 0 {
			sb.WriteString("\n")
		}
		w.writeBlock(&sb, block, 0)
	}
	return sb.String()
}

var rstHeaderChars = []string{"=", "-", "~", "^", "'", "\""}

func (w *RSTWriter) writeBlock(sb *strings.Builder, block Block, level int) {
	switch block.Type {
	case "Para":
		text := w.inlinesToRST(block.Inlines)
		if w.opts.Wrap == "none" {
			sb.WriteString(text)
		} else {
			sb.WriteString(wrapText(text, w.opts.Columns))
		}
		sb.WriteString("\n")
	case "Plain":
		sb.WriteString(w.inlinesToRST(block.Inlines) + "\n")
	case "Header":
		text := w.inlinesToRST(block.Inlines)
		charIdx := block.Level - 1
		if charIdx >= len(rstHeaderChars) {
			charIdx = len(rstHeaderChars) - 1
		}
		underline := strings.Repeat(rstHeaderChars[charIdx], len(text))
		sb.WriteString(text + "\n" + underline + "\n")
	case "BlockQuote":
		for _, b := range block.Blocks {
			var bsb strings.Builder
			w.writeBlock(&bsb, b, 0)
			lines := strings.Split(strings.TrimRight(bsb.String(), "\n"), "\n")
			for _, line := range lines {
				sb.WriteString("   " + line + "\n")
			}
		}
	case "CodeBlock":
		lang := ""
		if len(block.Attr.Classes) > 0 {
			lang = block.Attr.Classes[0]
		}
		if lang != "" {
			sb.WriteString(".. code:: " + lang + "\n\n")
		} else {
			sb.WriteString("::\n\n")
		}
		for _, line := range strings.Split(block.Code, "\n") {
			sb.WriteString("   " + line + "\n")
		}
	case "HorizontalRule":
		sb.WriteString("-" + strings.Repeat("-", 13) + "\n")
	case "BulletList":
		for _, item := range block.Items {
			first := true
			for _, b := range item {
				var bsb strings.Builder
				w.writeBlock(&bsb, b, 0)
				content := strings.TrimRight(bsb.String(), "\n")
				lines := strings.Split(content, "\n")
				for i, line := range lines {
					if first && i == 0 {
						sb.WriteString("- " + line + "\n")
						first = false
					} else {
						sb.WriteString("  " + line + "\n")
					}
				}
			}
		}
	case "OrderedList":
		for idx, item := range block.Items {
			num := block.ListAttr.Start + idx
			marker := fmt.Sprintf("%d. ", num)
			indent := strings.Repeat(" ", len(marker))
			first := true
			for _, b := range item {
				var bsb strings.Builder
				w.writeBlock(&bsb, b, 0)
				content := strings.TrimRight(bsb.String(), "\n")
				lines := strings.Split(content, "\n")
				for i, line := range lines {
					if first && i == 0 {
						sb.WriteString(marker + line + "\n")
						first = false
					} else {
						sb.WriteString(indent + line + "\n")
					}
				}
			}
		}
	case "Table":
		w.writeTable(sb, block)
	case "Figure":
		// Write as figure directive
		for _, b := range block.Blocks {
			if b.Type == "Plain" || b.Type == "Para" {
				for _, il := range b.Inlines {
					if il.Type == "Image" {
						sb.WriteString(".. figure:: " + il.Target.URL + "\n")
						alt := inlinesToText(il.Inlines)
						sb.WriteString("   :alt: " + alt + "\n")
						sb.WriteString("\n")
						sb.WriteString("   " + alt + "\n")
					}
				}
			}
		}
	case "RawBlock":
		if block.Format == "rst" {
			sb.WriteString(block.Code + "\n")
		}
	case "DefinitionList":
		for _, item := range block.DefItems {
			sb.WriteString(w.inlinesToRST(item.Term) + "\n")
			for _, def := range item.Defs {
				for _, b := range def {
					var bsb strings.Builder
					w.writeBlock(&bsb, b, 0)
					lines := strings.Split(strings.TrimRight(bsb.String(), "\n"), "\n")
					for _, line := range lines {
						sb.WriteString("   " + line + "\n")
					}
				}
			}
		}
	case "Div":
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, level)
		}
	case "LineBlock":
		for _, line := range block.Lines {
			sb.WriteString("| " + w.inlinesToRST(line) + "\n")
		}
	}
}

func (w *RSTWriter) writeTable(sb *strings.Builder, block Block) {
	td := block.Table
	if td == nil {
		return
	}

	numCols := len(td.ColSpecs)

	var headers []string
	if len(td.Head.Rows) > 0 {
		for _, cell := range td.Head.Rows[0].Cells {
			text := ""
			for _, b := range cell.Blocks {
				if b.Type == "Plain" || b.Type == "Para" {
					text = w.inlinesToRST(b.Inlines)
				}
			}
			headers = append(headers, text)
		}
		if numCols == 0 {
			numCols = len(headers)
		}
	}

	var bodyRows [][]string
	for _, body := range td.Bodies {
		for _, row := range body.Rows {
			var cells []string
			for _, cell := range row.Cells {
				text := ""
				for _, b := range cell.Blocks {
					if b.Type == "Plain" || b.Type == "Para" {
						text = w.inlinesToRST(b.Inlines)
					}
				}
				cells = append(cells, text)
			}
			bodyRows = append(bodyRows, cells)
		}
	}

	// Calculate column widths
	colWidths := make([]int, numCols)
	for i := 0; i < numCols; i++ {
		if i < len(headers) && len(headers[i]) > colWidths[i] {
			colWidths[i] = len(headers[i])
		}
		for _, row := range bodyRows {
			if i < len(row) && len(row[i]) > colWidths[i] {
				colWidths[i] = len(row[i])
			}
		}
		if colWidths[i] == 0 {
			colWidths[i] = 1
		}
	}

	// Write simple RST table
	// = = = format
	sep := ""
	for i, w := range colWidths {
		sep += strings.Repeat("=", w)
		if i < numCols-1 {
			sep += " "
		}
	}

	sb.WriteString(sep + "\n")
	// Header
	for i := 0; i < numCols; i++ {
		h := ""
		if i < len(headers) {
			h = headers[i]
		}
		sb.WriteString(padRight(h, colWidths[i]))
		if i < numCols-1 {
			sb.WriteString(" ")
		}
	}
	sb.WriteString("\n")
	sb.WriteString(sep + "\n")
	// Body
	for _, row := range bodyRows {
		for i := 0; i < numCols; i++ {
			cell := ""
			if i < len(row) {
				cell = row[i]
			}
			sb.WriteString(padRight(cell, colWidths[i]))
			if i < numCols-1 {
				sb.WriteString(" ")
			}
		}
		sb.WriteString("\n")
	}
	sb.WriteString(sep + "\n")
}

func (w *RSTWriter) inlinesToRST(inlines []Inline) string {
	var sb strings.Builder
	for _, il := range inlines {
		w.writeInline(&sb, il)
	}
	return sb.String()
}

func (w *RSTWriter) writeInline(sb *strings.Builder, il Inline) {
	switch il.Type {
	case "Str":
		sb.WriteString(il.Text)
	case "Space":
		sb.WriteString(" ")
	case "SoftBreak":
		sb.WriteString(" ")
	case "LineBreak":
		sb.WriteString("\n")
	case "Emph":
		sb.WriteString("*")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("*")
	case "Strong":
		sb.WriteString("**")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("**")
	case "Strikeout":
		sb.WriteString("~~")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("~~")
	case "Code":
		sb.WriteString("``" + il.Text + "``")
	case "Link":
		text := ""
		for _, child := range il.Inlines {
			var tmp strings.Builder
			w.writeInline(&tmp, child)
			text += tmp.String()
		}
		url := il.Target.URL
		sb.WriteString("`" + text + " <" + url + ">`__")
	case "Image":
		// Inline image in RST
		alt := inlinesToText(il.Inlines)
		sb.WriteString("|" + alt + "|")
	case "Math":
		sb.WriteString(":math:`" + il.Text + "`")
	case "Quoted":
		if il.QuoteType == "DoubleQuote" {
			sb.WriteString("\u201c")
		} else {
			sb.WriteString("\u2018")
		}
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		if il.QuoteType == "DoubleQuote" {
			sb.WriteString("\u201d")
		} else {
			sb.WriteString("\u2019")
		}
	case "Superscript":
		sb.WriteString("\\ :sup:`")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("`\\ ")
	case "Subscript":
		sb.WriteString("\\ :sub:`")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("`\\ ")
	case "Note":
		sb.WriteString(" [#]_")
	default:
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
	}
}

// LaTeX writer
type LaTeXWriter struct {
	opts *Options
}

func newLaTeXWriter(opts *Options) *LaTeXWriter {
	return &LaTeXWriter{opts: opts}
}

func (w *LaTeXWriter) write(doc *Doc) string {
	var sb strings.Builder
	for i, block := range doc.Blocks {
		if i > 0 {
			sb.WriteString("\n")
		}
		w.writeBlock(&sb, block, 0)
	}
	return sb.String()
}

var latexSectionCmds = []string{
	"", "section", "subsection", "subsubsection", "paragraph", "subparagraph",
}

func (w *LaTeXWriter) writeBlock(sb *strings.Builder, block Block, indent int) {
	switch block.Type {
	case "Para":
		text := w.inlinesToLaTeX(block.Inlines)
		sb.WriteString(text + "\n")
	case "Plain":
		sb.WriteString(w.inlinesToLaTeX(block.Inlines) + "\n")
	case "Header":
		level := block.Level
		if level < 1 {
			level = 1
		}
		cmd := "section"
		if level < len(latexSectionCmds) {
			cmd = latexSectionCmds[level]
		} else {
			cmd = "subparagraph"
		}
		id := block.Attr.ID
		text := w.inlinesToLaTeX(block.Inlines)
		if id != "" {
			sb.WriteString(fmt.Sprintf("\\%s{%s}\\label{%s}\n", cmd, text, id))
		} else {
			autoID := makeIdentifier(inlinesToText(block.Inlines))
			sb.WriteString(fmt.Sprintf("\\%s{%s}\\label{%s}\n", cmd, text, autoID))
		}
	case "BlockQuote":
		sb.WriteString("\\begin{quote}\n")
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, 0)
		}
		sb.WriteString("\\end{quote}\n")
	case "CodeBlock":
		lang := ""
		if len(block.Attr.Classes) > 0 {
			lang = block.Attr.Classes[0]
		}
		if lang != "" {
			sb.WriteString(fmt.Sprintf("\\begin{verbatim}\n%s\n\\end{verbatim}\n", block.Code))
		} else {
			sb.WriteString(fmt.Sprintf("\\begin{verbatim}\n%s\n\\end{verbatim}\n", block.Code))
		}
	case "HorizontalRule":
		sb.WriteString("\\rule{\\linewidth}{0.5pt}\n")
	case "BulletList":
		sb.WriteString("\\begin{itemize}\n")
		sb.WriteString("\\tightlist\n")
		for _, item := range block.Items {
			sb.WriteString("\\item\n")
			for _, b := range item {
				w.writeBlock(sb, b, 1)
			}
		}
		sb.WriteString("\\end{itemize}\n")
	case "OrderedList":
		la := block.ListAttr
		enumStyle := ""
		switch la.Style {
		case "LowerAlpha":
			enumStyle = "\\def\\labelenumi{\\alph{enumi}.}"
		case "UpperAlpha":
			enumStyle = "\\def\\labelenumi{\\Alph{enumi}.}"
		case "LowerRoman":
			enumStyle = "\\def\\labelenumi{\\roman{enumi}.}"
		case "UpperRoman":
			enumStyle = "\\def\\labelenumi{\\Roman{enumi}.}"
		default:
			if la.Delimiter == "Period" {
				enumStyle = "\\def\\labelenumi{\\arabic{enumi}.}"
			} else {
				enumStyle = "\\def\\labelenumi{\\arabic{enumi})"
			}
		}
		sb.WriteString("\\begin{enumerate}\n")
		sb.WriteString(enumStyle + "\n")
		sb.WriteString("\\tightlist\n")
		for _, item := range block.Items {
			sb.WriteString("\\item\n")
			for _, b := range item {
				w.writeBlock(sb, b, 1)
			}
		}
		sb.WriteString("\\end{enumerate}\n")
	case "DefinitionList":
		sb.WriteString("\\begin{description}\n")
		for _, item := range block.DefItems {
			term := w.inlinesToLaTeX(item.Term)
			sb.WriteString("\\item[" + term + "]\n")
			for _, def := range item.Defs {
				for _, b := range def {
					w.writeBlock(sb, b, 0)
				}
			}
		}
		sb.WriteString("\\end{description}\n")
	case "Table":
		w.writeTable(sb, block)
	case "Figure":
		sb.WriteString("\\begin{figure}\n")
		for _, b := range block.Blocks {
			if b.Type == "Plain" || b.Type == "Para" {
				for _, il := range b.Inlines {
					if il.Type == "Image" {
						sb.WriteString("\\centering\n")
						sb.WriteString(fmt.Sprintf("\\includegraphics{%s}\n", il.Target.URL))
					}
				}
			}
		}
		sb.WriteString("\\end{figure}\n")
	case "RawBlock":
		if block.Format == "latex" || block.Format == "tex" {
			sb.WriteString(block.Code + "\n")
		}
	case "Div":
		for _, b := range block.Blocks {
			w.writeBlock(sb, b, 0)
		}
	case "LineBlock":
		for _, line := range block.Lines {
			sb.WriteString(w.inlinesToLaTeX(line) + "\\\\\n")
		}
	}
}

func (w *LaTeXWriter) writeTable(sb *strings.Builder, block Block) {
	td := block.Table
	if td == nil {
		return
	}

	numCols := len(td.ColSpecs)
	colSpec := ""
	for i := 0; i < numCols; i++ {
		colSpec += "l"
	}

	sb.WriteString("\\begin{longtable}[]{@{}\n" + colSpec + "@{}}\n")
	sb.WriteString("\\toprule\n")

	// Header
	if len(td.Head.Rows) > 0 {
		var cells []string
		for _, cell := range td.Head.Rows[0].Cells {
			text := ""
			for _, b := range cell.Blocks {
				if b.Type == "Plain" || b.Type == "Para" {
					text = w.inlinesToLaTeX(b.Inlines)
				}
			}
			cells = append(cells, text)
		}
		sb.WriteString(strings.Join(cells, " & ") + " \\\\\n")
		sb.WriteString("\\midrule\n")
		sb.WriteString("\\endhead\n")
	}

	// Body
	for _, body := range td.Bodies {
		for _, row := range body.Rows {
			var cells []string
			for _, cell := range row.Cells {
				text := ""
				for _, b := range cell.Blocks {
					if b.Type == "Plain" || b.Type == "Para" {
						text = w.inlinesToLaTeX(b.Inlines)
					}
				}
				cells = append(cells, text)
			}
			sb.WriteString(strings.Join(cells, " & ") + " \\\\\n")
		}
	}

	sb.WriteString("\\bottomrule\n")
	sb.WriteString("\\end{longtable}\n")
}

func (w *LaTeXWriter) inlinesToLaTeX(inlines []Inline) string {
	var sb strings.Builder
	for _, il := range inlines {
		w.writeInline(&sb, il)
	}
	return sb.String()
}

func latexEscape(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\textbackslash{}")
	s = strings.ReplaceAll(s, "&", "\\&")
	s = strings.ReplaceAll(s, "%", "\\%")
	s = strings.ReplaceAll(s, "$", "\\$")
	s = strings.ReplaceAll(s, "#", "\\#")
	s = strings.ReplaceAll(s, "_", "\\_")
	s = strings.ReplaceAll(s, "{", "\\{")
	s = strings.ReplaceAll(s, "}", "\\}")
	s = strings.ReplaceAll(s, "~", "\\textasciitilde{}")
	s = strings.ReplaceAll(s, "^", "\\textasciicircum{}")
	return s
}

func (w *LaTeXWriter) writeInline(sb *strings.Builder, il Inline) {
	switch il.Type {
	case "Str":
		sb.WriteString(latexEscape(il.Text))
	case "Space":
		sb.WriteString(" ")
	case "SoftBreak":
		sb.WriteString(" ")
	case "LineBreak":
		sb.WriteString("\\\\\n")
	case "Emph":
		sb.WriteString("\\emph{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "Strong":
		sb.WriteString("\\textbf{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "Strikeout":
		sb.WriteString("\\sout{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "Superscript":
		sb.WriteString("\\textsuperscript{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "Subscript":
		sb.WriteString("\\textsubscript{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "SmallCaps":
		sb.WriteString("\\textsc{")
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
		sb.WriteString("}")
	case "Quoted":
		if il.QuoteType == "DoubleQuote" {
			sb.WriteString("``")
			for _, child := range il.Inlines {
				w.writeInline(sb, child)
			}
			sb.WriteString("''")
		} else {
			sb.WriteString("`")
			for _, child := range il.Inlines {
				w.writeInline(sb, child)
			}
			sb.WriteString("'")
		}
	case "Code":
		sb.WriteString("\\texttt{" + latexEscape(il.Text) + "}")
	case "Math":
		if il.MathType == "DisplayMath" {
			sb.WriteString("\\[" + il.Text + "\\]")
		} else {
			sb.WriteString("$" + il.Text + "$")
		}
	case "Link":
		text := w.inlinesToLaTeX(il.Inlines)
		url := latexEscape(il.Target.URL)
		sb.WriteString(fmt.Sprintf("\\href{%s}{%s}", url, text))
	case "Image":
		sb.WriteString(fmt.Sprintf("\\includegraphics{%s}", latexEscape(il.Target.URL)))
	case "RawInline":
		if il.Format == "latex" || il.Format == "tex" {
			sb.WriteString(il.Text)
		}
	case "Note":
		sb.WriteString("\\footnote{")
		for _, b := range il.Blocks {
			if b.Type == "Para" {
				sb.WriteString(w.inlinesToLaTeX(b.Inlines))
			}
		}
		sb.WriteString("}")
	case "Span":
		for _, child := range il.Inlines {
			w.writeInline(sb, child)
		}
	}
}
