			"c": blocksToJSON(il.Blocks),
		}
	case "Span":
		return map[string]interface{}{
			"t": "Span",
			"c": []interface{}{attrToJSON(il.Attr), inlinesToJSONArray(il.Inlines)},
		}
	case "Cite":
		var cites []interface{}
		for _, c := range il.Citations {
			cites = append(cites, map[string]interface{}{
				"citationId":      c.ID,
				"citationPrefix":  inlinesToJSONArray(c.Prefix),
				"citationSuffix":  inlinesToJSONArray(c.Suffix),
				"citationMode":    map[string]interface{}{"t": c.Mode},
				"citationNoteNum": c.NoteNum,
				"citationHash":    c.Hash,
			})
		}
		if cites == nil {
			cites = []interface{}{}
		}
		return map[string]interface{}{
			"t": "Cite",
			"c": []interface{}{cites, inlinesToJSONArray(il.Inlines)},
		}
	}
	return map[string]interface{}{"t": il.Type}
}

// JSON -> Doc parsing
func jsonToDoc(data string) (*Doc, error) {
	var raw map[string]interface{}
	if err := json.Unmarshal([]byte(data), &raw); err != nil {
		return nil, fmt.Errorf("invalid JSON: %w", err)
	}

	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	if meta, ok := raw["meta"].(map[string]interface{}); ok {
		for k, v := range meta {
			doc.Meta[k] = jsonToMetaVal(v)
		}
	}

	if blocks, ok := raw["blocks"].([]interface{}); ok {
		for _, b := range blocks {
			block := jsonToBlock(b)
			doc.Blocks = append(doc.Blocks, block)
		}
	}

	return doc, nil
}

func jsonToMetaVal(v interface{}) MetaVal {
	m, ok := v.(map[string]interface{})
	if !ok {
		return MetaVal{Type: "MetaString", Str: fmt.Sprint(v)}
	}

	t, _ := m["t"].(string)
	c := m["c"]

	switch t {
	case "MetaInlines":
		if arr, ok := c.([]interface{}); ok {
			return MetaVal{Type: "MetaInlines", Inlines: jsonToInlines(arr)}
		}
	case "MetaString":
		if s, ok := c.(string); ok {
			return MetaVal{Type: "MetaString", Str: s}
		}
	case "MetaBool":
		if b, ok := c.(bool); ok {
			return MetaVal{Type: "MetaBool", Bool: b}
		}
	case "MetaList":
		if arr, ok := c.([]interface{}); ok {
			var list []MetaVal
			for _, item := range arr {
				list = append(list, jsonToMetaVal(item))
			}
			return MetaVal{Type: "MetaList", List: list}
		}
	case "MetaBlocks":
		if arr, ok := c.([]interface{}); ok {
			var blocks []Block
			for _, b := range arr {
				blocks = append(blocks, jsonToBlock(b))
			}
			return MetaVal{Type: "MetaBlocks", Blocks: blocks}
		}
	}

	return MetaVal{Type: "MetaInlines", Inlines: []Inline{}}
}

func jsonToBlock(v interface{}) Block {
	m, ok := v.(map[string]interface{})
	if !ok {
		return Block{Type: "Para"}
	}

	t, _ := m["t"].(string)
	c := m["c"]

	switch t {
	case "Para":
		if arr, ok := c.([]interface{}); ok {
			return Block{Type: "Para", Inlines: jsonToInlines(arr)}
		}
	case "Plain":
		if arr, ok := c.([]interface{}); ok {
			return Block{Type: "Plain", Inlines: jsonToInlines(arr)}
		}
	case "Header":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 3 {
			level := int(toFloat64(arr[0]))
			attr := jsonToAttr(arr[1])
			inlines := jsonToInlines(arr[2].([]interface{}))
			return Block{Type: "Header", Level: level, Attr: attr, Inlines: inlines}
		}
	case "BlockQuote":
		if arr, ok := c.([]interface{}); ok {
			var blocks []Block
			for _, b := range arr {
				blocks = append(blocks, jsonToBlock(b))
			}
			return Block{Type: "BlockQuote", Blocks: blocks}
		}
	case "CodeBlock":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			attr := jsonToAttr(arr[0])
			code, _ := arr[1].(string)
			return Block{Type: "CodeBlock", Attr: attr, Code: code}
		}
	case "RawBlock":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			format, _ := arr[0].(string)
			code, _ := arr[1].(string)
			return Block{Type: "RawBlock", Format: format, Code: code}
		}
	case "HorizontalRule":
		return Block{Type: "HorizontalRule"}
	case "BulletList":
		if arr, ok := c.([]interface{}); ok {
			var items [][]Block
			for _, item := range arr {
				if blocks, ok := item.([]interface{}); ok {
					var blockList []Block
					for _, b := range blocks {
						blockList = append(blockList, jsonToBlock(b))
					}
					items = append(items, blockList)
				}
			}
			return Block{Type: "BulletList", Items: items}
		}
	case "OrderedList":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			la := jsonToListAttr(arr[0])
			var items [][]Block
			if itemsArr, ok := arr[1].([]interface{}); ok {
				for _, item := range itemsArr {
					if blocks, ok := item.([]interface{}); ok {
						var blockList []Block
						for _, b := range blocks {
							blockList = append(blockList, jsonToBlock(b))
						}
						items = append(items, blockList)
					}
				}
			}
			return Block{Type: "OrderedList", ListAttr: la, Items: items}
		}
	case "DefinitionList":
		if arr, ok := c.([]interface{}); ok {
			var defItems []DefItem
			for _, item := range arr {
				if pair, ok := item.([]interface{}); ok && len(pair) >= 2 {
					term := jsonToInlines(pair[0].([]interface{}))
					var defs [][]Block
					if defArr, ok := pair[1].([]interface{}); ok {
						for _, def := range defArr {
							if blocks, ok := def.([]interface{}); ok {
								var blockList []Block
								for _, b := range blocks {
									blockList = append(blockList, jsonToBlock(b))
								}
								defs = append(defs, blockList)
							}
						}
					}
					defItems = append(defItems, DefItem{Term: term, Defs: defs})
				}
			}
			return Block{Type: "DefinitionList", DefItems: defItems}
		}
	case "Div":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			attr := jsonToAttr(arr[0])
			var blocks []Block
			if blocksArr, ok := arr[1].([]interface{}); ok {
				for _, b := range blocksArr {
					blocks = append(blocks, jsonToBlock(b))
				}
			}
			return Block{Type: "Div", Attr: attr, Blocks: blocks}
		}
	case "Table":
		return jsonToTable(c)
	}

	return Block{Type: t}
}

func jsonToTable(c interface{}) Block {
	arr, ok := c.([]interface{})
	if !ok || len(arr) < 6 {
		return Block{Type: "Table"}
	}

	attr := jsonToAttr(arr[0])

	// Caption
	captionBlocks := []Block{}
	if cap, ok := arr[1].([]interface{}); ok && len(cap) >= 2 {
		if blocks, ok := cap[1].([]interface{}); ok {
			for _, b := range blocks {
				captionBlocks = append(captionBlocks, jsonToBlock(b))
			}
		}
	}

	// ColSpecs
	var colSpecs []ColSpec
	if specs, ok := arr[2].([]interface{}); ok {
		for _, spec := range specs {
			if specArr, ok := spec.([]interface{}); ok && len(specArr) >= 2 {
				alignMap, _ := specArr[0].(map[string]interface{})
				alignT, _ := alignMap["t"].(string)
				cs := ColSpec{Align: alignT, Width: 0}
				if widthMap, ok := specArr[1].(map[string]interface{}); ok {
					if widthMap["t"] == "ColWidth" {
						cs.Width = toFloat64(widthMap["c"])
					}
				}
				colSpecs = append(colSpecs, cs)
			}
		}
	}

	// Head
	head := TableHead{Attr: emptyAttr()}
	if headArr, ok := arr[3].([]interface{}); ok && len(headArr) >= 2 {
		head.Attr = jsonToAttr(headArr[0])
		if rows, ok := headArr[1].([]interface{}); ok {
			head.Rows = jsonToTableRows(rows)
		}
	}

	// Bodies
	var bodies []TableBody
	if bodiesArr, ok := arr[4].([]interface{}); ok {
		for _, body := range bodiesArr {
			if bodyArr, ok := body.([]interface{}); ok && len(bodyArr) >= 4 {
				tb := TableBody{
					Attr:    jsonToAttr(bodyArr[0]),
					RowHead: int(toFloat64(bodyArr[1])),
				}
				if headRows, ok := bodyArr[2].([]interface{}); ok {
					tb.HeadRows = jsonToTableRows(headRows)
				}
				if rows, ok := bodyArr[3].([]interface{}); ok {
					tb.Rows = jsonToTableRows(rows)
				}
				bodies = append(bodies, tb)
			}
		}
	}

	// Foot
	foot := TableFoot{Attr: emptyAttr()}
	if footArr, ok := arr[5].([]interface{}); ok && len(footArr) >= 2 {
		foot.Attr = jsonToAttr(footArr[0])
		if rows, ok := footArr[1].([]interface{}); ok {
			foot.Rows = jsonToTableRows(rows)
		}
	}

	td := &TableData{
		Caption:  Caption{Blocks: captionBlocks},
		ColSpecs: colSpecs,
		Head:     head,
		Bodies:   bodies,
		Foot:     foot,
	}

	return Block{Type: "Table", Attr: attr, Table: td}
}

func jsonToTableRows(rows []interface{}) []TableRow {
	var result []TableRow
	for _, row := range rows {
		if rowArr, ok := row.([]interface{}); ok && len(rowArr) >= 2 {
			tr := TableRow{
				Attr: jsonToAttr(rowArr[0]),
			}
			if cells, ok := rowArr[1].([]interface{}); ok {
				for _, cell := range cells {
					if cellArr, ok := cell.([]interface{}); ok && len(cellArr) >= 5 {
						alignMap, _ := cellArr[1].(map[string]interface{})
						alignT, _ := alignMap["t"].(string)

						rowSpanMap, _ := cellArr[2].(map[string]interface{})
						rowSpan := int(toFloat64(rowSpanMap["c"]))
						if rowSpan == 0 {
							rowSpan = 1
						}

						colSpanMap, _ := cellArr[3].(map[string]interface{})
						colSpan := int(toFloat64(colSpanMap["c"]))
						if colSpan == 0 {
							colSpan = 1
						}

						var cellBlocks []Block
						if blocksArr, ok := cellArr[4].([]interface{}); ok {
							for _, b := range blocksArr {
								cellBlocks = append(cellBlocks, jsonToBlock(b))
							}
						}

						tr.Cells = append(tr.Cells, TableCell{
							Attr:    jsonToAttr(cellArr[0]),
							Align:   alignT,
							RowSpan: rowSpan,
							ColSpan: colSpan,
							Blocks:  cellBlocks,
						})
					}
				}
			}
			result = append(result, tr)
		}
	}
	return result
}

func jsonToAttr(v interface{}) Attr {
	arr, ok := v.([]interface{})
	if !ok || len(arr) < 3 {
		return emptyAttr()
	}

	id, _ := arr[0].(string)

	var classes []string
	if classArr, ok := arr[1].([]interface{}); ok {
		for _, c := range classArr {
			if s, ok := c.(string); ok {
				classes = append(classes, s)
			}
		}
	}
	if classes == nil {
		classes = []string{}
	}

	var kvPairs [][2]string
	if kvArr, ok := arr[2].([]interface{}); ok {
		for _, kv := range kvArr {
			if kvPair, ok := kv.([]interface{}); ok && len(kvPair) >= 2 {
				k, _ := kvPair[0].(string)
				v2, _ := kvPair[1].(string)
				kvPairs = append(kvPairs, [2]string{k, v2})
			}
		}
	}
	if kvPairs == nil {
		kvPairs = [][2]string{}
	}

	return Attr{ID: id, Classes: classes, KVPairs: kvPairs}
}

func jsonToListAttr(v interface{}) ListAttr {
	arr, ok := v.([]interface{})
	if !ok || len(arr) < 3 {
		return ListAttr{Start: 1, Style: "Decimal", Delimiter: "Period"}
	}

	start := int(toFloat64(arr[0]))
	if start == 0 {
		start = 1
	}

	styleMap, _ := arr[1].(map[string]interface{})
	style, _ := styleMap["t"].(string)
	if style == "" {
		style = "DefaultStyle"
	}

	delimMap, _ := arr[2].(map[string]interface{})
	delim, _ := delimMap["t"].(string)
	if delim == "" {
		delim = "DefaultDelim"
	}

	return ListAttr{Start: start, Style: style, Delimiter: delim}
}

func jsonToInlines(arr []interface{}) []Inline {
	var result []Inline
	for _, item := range arr {
		il := jsonToInline(item)
		result = append(result, il)
	}
	return result
}

func jsonToInline(v interface{}) Inline {
	m, ok := v.(map[string]interface{})
	if !ok {
		return Inline{Type: "Str", Text: fmt.Sprint(v)}
	}

	t, _ := m["t"].(string)
	c := m["c"]

	switch t {
	case "Str":
		s, _ := c.(string)
		return Inline{Type: "Str", Text: s}
	case "Space":
		return Inline{Type: "Space"}
	case "SoftBreak":
		return Inline{Type: "SoftBreak"}
	case "LineBreak":
		return Inline{Type: "LineBreak"}
	case "Emph":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "Emph", Inlines: jsonToInlines(arr)}
		}
	case "Strong":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "Strong", Inlines: jsonToInlines(arr)}
		}
	case "Strikeout":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "Strikeout", Inlines: jsonToInlines(arr)}
		}
	case "Superscript":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "Superscript", Inlines: jsonToInlines(arr)}
		}
	case "Subscript":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "Subscript", Inlines: jsonToInlines(arr)}
		}
	case "SmallCaps":
		if arr, ok := c.([]interface{}); ok {
			return Inline{Type: "SmallCaps", Inlines: jsonToInlines(arr)}
		}
	case "Quoted":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			qtMap, _ := arr[0].(map[string]interface{})
			qt, _ := qtMap["t"].(string)
			inlines := jsonToInlines(arr[1].([]interface{}))
			return Inline{Type: "Quoted", QuoteType: qt, Inlines: inlines}
		}
	case "Code":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			attr := jsonToAttr(arr[0])
			code, _ := arr[1].(string)
			return Inline{Type: "Code", Attr: attr, Text: code}
		}
	case "Math":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			mtMap, _ := arr[0].(map[string]interface{})
			mt, _ := mtMap["t"].(string)
			text, _ := arr[1].(string)
			return Inline{Type: "Math", MathType: mt, Text: text}
		}
	case "RawInline":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			format, _ := arr[0].(string)
			text, _ := arr[1].(string)
			return Inline{Type: "RawInline", Format: format, Text: text}
		}
	case "Link":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 3 {
			attr := jsonToAttr(arr[0])
			inlines := jsonToInlines(arr[1].([]interface{}))
			target := jsonToTarget(arr[2])
			return Inline{Type: "Link", Attr: attr, Inlines: inlines, Target: target}
		}
	case "Image":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 3 {
			attr := jsonToAttr(arr[0])
			inlines := jsonToInlines(arr[1].([]interface{}))
			target := jsonToTarget(arr[2])
			return Inline{Type: "Image", Attr: attr, Inlines: inlines, Target: target}
		}
	case "Note":
		if arr, ok := c.([]interface{}); ok {
			var blocks []Block
			for _, b := range arr {
				blocks = append(blocks, jsonToBlock(b))
			}
			return Inline{Type: "Note", Blocks: blocks}
		}
	case "Span":
		if arr, ok := c.([]interface{}); ok && len(arr) >= 2 {
			attr := jsonToAttr(arr[0])
			inlines := jsonToInlines(arr[1].([]interface{}))
			return Inline{Type: "Span", Attr: attr, Inlines: inlines}
		}
	}

	return Inline{Type: t}
}

func jsonToTarget(v interface{}) Target {
	arr, ok := v.([]interface{})
	if !ok || len(arr) < 2 {
		return Target{}
	}
	url, _ := arr[0].(string)
	title, _ := arr[1].(string)
	return Target{URL: url, Title: title}
}

func toFloat64(v interface{}) float64 {
	switch n := v.(type) {
	case float64:
		return n
	case int:
		return float64(n)
	case int64:
		return float64(n)
	}
	return 0
}

// Native writer (Haskell-like representation)
func docToNative(doc *Doc) string {
	var sb strings.Builder
	sb.WriteString("[ ")
	for i, block := range doc.Blocks {
		if i > 0 {
			sb.WriteString(", ")
		}
		writeBlockNative(&sb, block, 0)
	}
	sb.WriteString("\n]\n")
	return sb.String()
}

func writeBlockNative(sb *strings.Builder, block Block, indent int) {
	ind := strings.Repeat(" ", indent)

	switch block.Type {
	case "Para":
		sb.WriteString(ind + "Para\n")
		sb.WriteString(ind + "  " + "[ ")
		writeInlinesNative(sb, block.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Plain":
		sb.WriteString(ind + "Plain\n")
		sb.WriteString(ind + "  " + "[ ")
		writeInlinesNative(sb, block.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Header":
		id := block.Attr.ID
		if id == "" {
			id = makeIdentifier(inlinesToText(block.Inlines))
		}
		classes := "[]"
		if len(block.Attr.Classes) > 0 {
			cls := make([]string, len(block.Attr.Classes))
			for i, c := range block.Attr.Classes {
				cls[i] = fmt.Sprintf("%q", c)
			}
			classes = "[ " + strings.Join(cls, " , ") + " ]"
		}
		sb.WriteString(fmt.Sprintf("%sHeader %d ( %q , %s , [] )\n", ind, block.Level, id, classes))
		sb.WriteString(ind + "  " + "[ ")
		writeInlinesNative(sb, block.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "BlockQuote":
		sb.WriteString(ind + "BlockQuote\n")
		sb.WriteString(ind + "  " + "[ ")
		for i, b := range block.Blocks {
			if i > 0 {
				sb.WriteString("\n" + ind + "  , ")
			}
			writeBlockNative(sb, b, indent+4)
		}
		sb.WriteString("\n" + ind + "  ]")
	case "CodeBlock":
		lang := ""
		if len(block.Attr.Classes) > 0 {
			lang = block.Attr.Classes[0]
		}
		classes := "[]"
		if lang != "" {
			classes = fmt.Sprintf("[ %q ]", lang)
		}
		sb.WriteString(fmt.Sprintf("%sCodeBlock ( %q , %s , [] ) %q", ind, block.Attr.ID, classes, block.Code))
	case "RawBlock":
		sb.WriteString(fmt.Sprintf("%sRawBlock %q %q", ind, block.Format, block.Code))
	case "HorizontalRule":
		sb.WriteString(ind + "HorizontalRule")
	case "BulletList":
		sb.WriteString(ind + "BulletList\n")
		sb.WriteString(ind + "  [ ")
		for i, item := range block.Items {
			if i > 0 {
				sb.WriteString("\n" + ind + "  , ")
			}
			sb.WriteString("[ ")
			for j, b := range item {
				if j > 0 {
					sb.WriteString("\n" + ind + "    , ")
				}
				writeBlockNative(sb, b, indent+6)
			}
			sb.WriteString("\n" + ind + "    ]")
		}
		sb.WriteString("\n" + ind + "  ]")
	case "OrderedList":
		la := block.ListAttr
		sb.WriteString(fmt.Sprintf("%sOrderedList ( %d , %s , %s )\n", ind, la.Start, la.Style, la.Delimiter))
		sb.WriteString(ind + "  [ ")
		for i, item := range block.Items {
			if i > 0 {
				sb.WriteString("\n" + ind + "  , ")
			}
			sb.WriteString("[ ")
			for j, b := range item {
				if j > 0 {
					sb.WriteString("\n" + ind + "    , ")
				}
				writeBlockNative(sb, b, indent+6)
			}
			sb.WriteString("\n" + ind + "    ]")
		}
		sb.WriteString("\n" + ind + "  ]")
	case "DefinitionList":
		sb.WriteString(ind + "DefinitionList")
	case "HorizontalRule":
		sb.WriteString(ind + "HorizontalRule")
	default:
		sb.WriteString(ind + block.Type)
	}
}

func writeInlinesNative(sb *strings.Builder, inlines []Inline, indent int) {
	ind := strings.Repeat(" ", indent)
	for i, il := range inlines {
		if i > 0 {
			sb.WriteString("\n" + ind + ", ")
		}
		writeInlineNative(sb, il, indent)
	}
}

func writeInlineNative(sb *strings.Builder, il Inline, indent int) {
	ind := strings.Repeat(" ", indent)
	switch il.Type {
	case "Str":
		sb.WriteString(fmt.Sprintf("Str %q", il.Text))
	case "Space":
		sb.WriteString("Space")
	case "SoftBreak":
		sb.WriteString("SoftBreak")
	case "LineBreak":
		sb.WriteString("LineBreak")
	case "Emph":
		sb.WriteString("Emph\n" + ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Strong":
		sb.WriteString("Strong\n" + ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Strikeout":
		sb.WriteString("Strikeout\n" + ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Superscript":
		sb.WriteString("Superscript\n" + ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Subscript":
		sb.WriteString("Subscript\n" + ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Code":
		lang := ""
		if len(il.Attr.Classes) > 0 {
			lang = il.Attr.Classes[0]
		}
		classes := "[]"
		if lang != "" {
			classes = fmt.Sprintf("[ %q ]", lang)
		}
		sb.WriteString(fmt.Sprintf("Code ( %q , %s , [] ) %q", il.Attr.ID, classes, il.Text))
	case "Math":
		sb.WriteString(fmt.Sprintf("%s %q", il.MathType, il.Text))
	case "RawInline":
		sb.WriteString(fmt.Sprintf("RawInline %q %q", il.Format, il.Text))
	case "Link":
		sb.WriteString("Link\n" + ind + "  ( " + fmt.Sprintf("%q", il.Attr.ID) + " , [] , [] )\n")
		sb.WriteString(ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]\n")
		sb.WriteString(fmt.Sprintf(ind+"  ( %q , %q )", il.Target.URL, il.Target.Title))
	case "Image":
		sb.WriteString("Image\n" + ind + "  ( " + fmt.Sprintf("%q", il.Attr.ID) + " , [] , [] )\n")
		sb.WriteString(ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]\n")
		sb.WriteString(fmt.Sprintf(ind+"  ( %q , %q )", il.Target.URL, il.Target.Title))
	case "Quoted":
		sb.WriteString(fmt.Sprintf("Quoted %s\n", il.QuoteType))
		sb.WriteString(ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	case "Note":
		sb.WriteString("Note\n" + ind + "  [ ")
		for i, b := range il.Blocks {
			if i > 0 {
				sb.WriteString("\n" + ind + "  , ")
			}
			writeBlockNative(sb, b, indent+4)
		}
		sb.WriteString("\n" + ind + "  ]")
	case "Span":
		sb.WriteString(fmt.Sprintf("Span ( %q , [] , [] )\n", il.Attr.ID))
		sb.WriteString(ind + "  [ ")
		writeInlinesNative(sb, il.Inlines, indent+4)
		sb.WriteString("\n" + ind + "  ]")
	default:
		sb.WriteString(il.Type)
	}
}
