package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// JSON AST serialization/deserialization

var pandocAPIVersion = []int{1, 23, 1, 1}

type jsonDoc struct {
	PandocAPIVersion []int            `json:"pandoc-api-version"`
	Meta             map[string]interface{} `json:"meta"`
	Blocks           []interface{}    `json:"blocks"`
}

func docToJSON(doc *Doc) string {
	jd := jsonDoc{
		PandocAPIVersion: pandocAPIVersion,
		Meta:             metaToJSON(doc.Meta),
		Blocks:           blocksToJSON(doc.Blocks),
	}

	data, err := json.Marshal(jd)
	if err != nil {
		return "{}"
	}
	return string(data)
}

func metaToJSON(meta map[string]MetaVal) map[string]interface{} {
	result := make(map[string]interface{})
	for k, v := range meta {
		result[k] = metaValToJSON(v)
	}
	return result
}

func metaValToJSON(mv MetaVal) interface{} {
	switch mv.Type {
	case "MetaInlines":
		return map[string]interface{}{
			"t": "MetaInlines",
			"c": inlinesToJSONArray(mv.Inlines),
		}
	case "MetaString":
		return map[string]interface{}{
			"t": "MetaString",
			"c": mv.Str,
		}
	case "MetaBool":
		return map[string]interface{}{
			"t": "MetaBool",
			"c": mv.Bool,
		}
	case "MetaList":
		var items []interface{}
		for _, item := range mv.List {
			items = append(items, metaValToJSON(item))
		}
		return map[string]interface{}{
			"t": "MetaList",
			"c": items,
		}
	case "MetaMap":
		return map[string]interface{}{
			"t": "MetaMap",
			"c": metaToJSON(mv.Map),
		}
	case "MetaBlocks":
		return map[string]interface{}{
			"t": "MetaBlocks",
			"c": blocksToJSON(mv.Blocks),
		}
	}
	return map[string]interface{}{"t": "MetaInlines", "c": []interface{}{}}
}

func blocksToJSON(blocks []Block) []interface{} {
	var result []interface{}
	for _, b := range blocks {
		result = append(result, blockToJSON(b))
	}
	if result == nil {
		result = []interface{}{}
	}
	return result
}

func blockToJSON(b Block) interface{} {
	switch b.Type {
	case "Para":
		return map[string]interface{}{"t": "Para", "c": inlinesToJSONArray(b.Inlines)}
	case "Plain":
		return map[string]interface{}{"t": "Plain", "c": inlinesToJSONArray(b.Inlines)}
	case "Header":
		id := b.Attr.ID
		if id == "" {
			id = makeIdentifier(inlinesToText(b.Inlines))
		}
		return map[string]interface{}{
			"t": "Header",
			"c": []interface{}{
				b.Level,
				attrToJSON(Attr{ID: id, Classes: b.Attr.Classes, KVPairs: b.Attr.KVPairs}),
				inlinesToJSONArray(b.Inlines),
			},
		}
	case "BlockQuote":
		return map[string]interface{}{"t": "BlockQuote", "c": blocksToJSON(b.Blocks)}
	case "CodeBlock":
		return map[string]interface{}{
			"t": "CodeBlock",
			"c": []interface{}{attrToJSON(b.Attr), b.Code},
		}
	case "RawBlock":
		return map[string]interface{}{
			"t": "RawBlock",
			"c": []interface{}{b.Format, b.Code},
		}
	case "HorizontalRule":
		return map[string]interface{}{"t": "HorizontalRule"}
	case "BulletList":
		var items []interface{}
		for _, item := range b.Items {
			items = append(items, blocksToJSON(item))
		}
		if items == nil {
			items = []interface{}{}
		}
		return map[string]interface{}{"t": "BulletList", "c": items}
	case "OrderedList":
		la := b.ListAttr
		var items []interface{}
		for _, item := range b.Items {
			items = append(items, blocksToJSON(item))
		}
		if items == nil {
			items = []interface{}{}
		}
		return map[string]interface{}{
			"t": "OrderedList",
			"c": []interface{}{
				[]interface{}{
					la.Start,
					map[string]interface{}{"t": la.Style},
					map[string]interface{}{"t": la.Delimiter},
				},
				items,
			},
		}
	case "DefinitionList":
		var items []interface{}
		for _, di := range b.DefItems {
			var defs []interface{}
			for _, def := range di.Defs {
				defs = append(defs, blocksToJSON(def))
			}
			if defs == nil {
				defs = []interface{}{}
			}
			items = append(items, []interface{}{inlinesToJSONArray(di.Term), defs})
		}
		if items == nil {
			items = []interface{}{}
		}
		return map[string]interface{}{"t": "DefinitionList", "c": items}
	case "Table":
		if b.Table == nil {
			return map[string]interface{}{"t": "Table"}
		}
		return tableToJSON(b)
	case "Figure":
		return figureToJSON(b)
	case "Div":
		return map[string]interface{}{
			"t": "Div",
			"c": []interface{}{attrToJSON(b.Attr), blocksToJSON(b.Blocks)},
		}
	case "LineBlock":
		var lines []interface{}
		for _, line := range b.Lines {
			lines = append(lines, inlinesToJSONArray(line))
		}
		if lines == nil {
			lines = []interface{}{}
		}
		return map[string]interface{}{"t": "LineBlock", "c": lines}
	}
	return map[string]interface{}{"t": b.Type}
}

func attrToJSON(attr Attr) []interface{} {
	classes := make([]interface{}, len(attr.Classes))
	for i, c := range attr.Classes {
		classes[i] = c
	}

	kvs := make([]interface{}, len(attr.KVPairs))
	for i, kv := range attr.KVPairs {
		kvs[i] = []interface{}{kv[0], kv[1]}
	}

	return []interface{}{attr.ID, classes, kvs}
}

func tableToJSON(b Block) interface{} {
	td := b.Table

	// ColSpecs
	var colSpecs []interface{}
	for _, cs := range td.ColSpecs {
		var width interface{}
		if cs.Width == 0 {
			width = map[string]interface{}{"t": "ColWidthDefault"}
		} else {
			width = map[string]interface{}{"t": "ColWidth", "c": cs.Width}
		}
		colSpecs = append(colSpecs, []interface{}{
			map[string]interface{}{"t": cs.Align},
			width,
		})
	}
	if colSpecs == nil {
		colSpecs = []interface{}{}
	}

	// Caption
	captionJSON := []interface{}{nil, blocksToJSON(td.Caption.Blocks)}

	// Head
	headJSON := []interface{}{
		attrToJSON(td.Head.Attr),
		rowsToJSON(td.Head.Rows),
	}

	// Bodies
	var bodiesJSON []interface{}
	for _, body := range td.Bodies {
		bodiesJSON = append(bodiesJSON, []interface{}{
			attrToJSON(body.Attr),
			body.RowHead,
			rowsToJSON(body.HeadRows),
			rowsToJSON(body.Rows),
		})
	}
	if bodiesJSON == nil {
		bodiesJSON = []interface{}{}
	}

	// Foot
	footJSON := []interface{}{
		attrToJSON(td.Foot.Attr),
		rowsToJSON(td.Foot.Rows),
	}

	return map[string]interface{}{
		"t": "Table",
		"c": []interface{}{
			attrToJSON(b.Attr),
			captionJSON,
			colSpecs,
			headJSON,
			bodiesJSON,
			footJSON,
		},
	}
}

func rowsToJSON(rows []TableRow) []interface{} {
	var result []interface{}
	for _, row := range rows {
		var cells []interface{}
		for _, cell := range row.Cells {
			cells = append(cells, []interface{}{
				attrToJSON(cell.Attr),
				map[string]interface{}{"t": cell.Align},
				map[string]interface{}{"t": "RowSpan", "c": cell.RowSpan},
				map[string]interface{}{"t": "ColSpan", "c": cell.ColSpan},
				blocksToJSON(cell.Blocks),
			})
		}
		if cells == nil {
			cells = []interface{}{}
		}
		result = append(result, []interface{}{attrToJSON(row.Attr), cells})
	}
	if result == nil {
		result = []interface{}{}
	}
	return result
}

func figureToJSON(b Block) interface{} {
	captionJSON := []interface{}{nil, blocksToJSON(b.Blocks[:0])} // empty blocks for caption

	// The figure blocks become the figure body
	_ = captionJSON

	// Find caption content
	var captionBlocks []Block
	if b.Table != nil {
		captionBlocks = b.Table.Caption.Blocks
	}

	return map[string]interface{}{
		"t": "Figure",
		"c": []interface{}{
			attrToJSON(b.Attr),
			[]interface{}{nil, blocksToJSON(captionBlocks)},
			blocksToJSON(b.Blocks),
		},
	}
}

func inlinesToJSONArray(inlines []Inline) []interface{} {
	var result []interface{}
	for _, il := range inlines {
		result = append(result, inlineToJSON(il))
	}
	if result == nil {
		result = []interface{}{}
	}
	return result
}

func inlineToJSON(il Inline) interface{} {
