package main

import (
	"regexp"
	"strings"
)

// HTML reader - converts HTML to Doc AST
type HTMLReader struct {
	opts *Options
}

func newHTMLReader(opts *Options) *HTMLReader {
	return &HTMLReader{opts: opts}
}

type htmlNode struct {
	tag      string
	attrs    map[string]string
	text     string
	children []*htmlNode
	isText   bool
	selfClose bool
}

func (r *HTMLReader) parse(input string) *Doc {
	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	// Normalize line endings
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")

	// Simple HTML to AST conversion
	nodes := parseHTMLNodes(input)
	doc.Blocks = r.nodesToBlocks(nodes)

	return doc
}

func parseHTMLNodes(html string) []*htmlNode {
	var nodes []*htmlNode
	pos := 0

	for pos < len(html) {
		if html[pos] == '<' {
			// Check for comment
			if pos+3 < len(html) && html[pos:pos+4] == "<!--" {
				end := strings.Index(html[pos:], "-->")
				if end >= 0 {
					pos += end + 3
					continue
				}
			}
			// Check for DOCTYPE
			if pos+8 < len(html) && strings.ToLower(html[pos:pos+9]) == "<!doctype" {
				end := strings.Index(html[pos:], ">")
				if end >= 0 {
					pos += end + 1
					continue
				}
			}

			tag, attrs, selfClose, end := parseHTMLTag(html, pos)
			if end > pos {
				if !strings.HasPrefix(tag, "/") {
					node := &htmlNode{
						tag:       strings.ToLower(tag),
						attrs:     attrs,
						selfClose: selfClose,
					}

					if !selfClose && !isSelfClosingTag(node.tag) {
						// Find closing tag and parse children
						closeTag := "</" + node.tag
						closeIdx := findCloseTag(html, end, node.tag)
						if closeIdx >= 0 {
							inner := html[end:closeIdx]
							node.children = parseHTMLNodes(inner)
							pos = closeIdx + len(closeTag) + 1
							// Skip to > of close tag
							for pos < len(html) && html[pos] != '>' {
								pos++
							}
							pos++
						} else {
							pos = end
						}
					} else {
						pos = end
					}
					nodes = append(nodes, node)
				} else {
					pos = end
				}
				continue
			}
		}

		// Text node
		end := strings.Index(html[pos:], "<")
		var text string
		if end < 0 {
			text = html[pos:]
			pos = len(html)
		} else {
			text = html[pos : pos+end]
			pos += end
		}
		if text != "" {
			nodes = append(nodes, &htmlNode{isText: true, text: text})
		}
	}

	return nodes
}

func findCloseTag(html string, start int, tag string) int {
	closeTag := "</" + tag
	// Need to find matching close tag considering nesting
	depth := 1
	pos := start
	lowerHTML := strings.ToLower(html)
	openTag := "<" + tag

	for pos < len(lowerHTML) {
		nextOpen := strings.Index(lowerHTML[pos:], openTag)
		nextClose := strings.Index(lowerHTML[pos:], closeTag)

		if nextClose < 0 {
			return -1
		}

		if nextOpen >= 0 && nextOpen < nextClose {
			// Check it's a full tag
			afterOpen := pos + nextOpen + len(openTag)
			if afterOpen < len(lowerHTML) {
				c := lowerHTML[afterOpen]
				if c == '>' || c == ' ' || c == '\t' || c == '\n' || c == '/' {
					depth++
				}
			}
			pos += nextOpen + len(openTag)
		} else {
			depth--
			if depth == 0 {
				return pos + nextClose
			}
			pos += nextClose + len(closeTag)
		}
	}
	return -1
}

func parseHTMLTag(html string, start int) (string, map[string]string, bool, int) {
	pos := start + 1 // skip <
	if pos >= len(html) {
		return "", nil, false, start + 1
	}

	// Read tag name
	tagStart := pos
	for pos < len(html) && html[pos] != '>' && html[pos] != ' ' && html[pos] != '\t' && html[pos] != '\n' && html[pos] != '/' {
		pos++
	}
	tag := html[tagStart:pos]

	// Read attributes
	attrs := make(map[string]string)
	for pos < len(html) && html[pos] != '>' {
		if html[pos] == '/' {
			pos++
			continue
		}
		if html[pos] == ' ' || html[pos] == '\t' || html[pos] == '\n' {
			pos++
			continue
		}

		// Read attribute name
		attrStart := pos
		for pos < len(html) && html[pos] != '=' && html[pos] != '>' && html[pos] != ' ' && html[pos] != '\t' && html[pos] != '\n' {
			pos++
		}
		attrName := html[attrStart:pos]

		if pos < len(html) && html[pos] == '=' {
			pos++ // skip =
			// Read attribute value
			if pos < len(html) && (html[pos] == '"' || html[pos] == '\'') {
				quote := html[pos]
				pos++
				valStart := pos
				for pos < len(html) && html[pos] != quote {
					pos++
				}
				attrs[strings.ToLower(attrName)] = html[valStart:pos]
				if pos < len(html) {
					pos++ // skip quote
				}
			} else {
				valStart := pos
				for pos < len(html) && html[pos] != '>' && html[pos] != ' ' {
					pos++
				}
				attrs[strings.ToLower(attrName)] = html[valStart:pos]
			}
		} else if attrName != "" {
			attrs[strings.ToLower(attrName)] = attrName
		}
	}

	selfClose := pos > 0 && pos <= len(html) && html[pos-1] == '/'
	if pos < len(html) && html[pos] == '>' {
		pos++
	}

	return tag, attrs, selfClose, pos
}

func isSelfClosingTag(tag string) bool {
	selfClosing := map[string]bool{
		"area": true, "base": true, "br": true, "col": true, "embed": true,
		"hr": true, "img": true, "input": true, "link": true, "meta": true,
		"param": true, "source": true, "track": true, "wbr": true,
	}
	return selfClosing[tag]
}

func (r *HTMLReader) nodesToBlocks(nodes []*htmlNode) []Block {
	var blocks []Block

	for _, node := range nodes {
		if node.isText {
			text := strings.TrimSpace(node.text)
			if text != "" {
				inlines := htmlTextToInlines(text)
				if len(inlines) > 0 {
					blocks = append(blocks, Block{Type: "Para", Inlines: inlines})
				}
			}
			continue
		}

		block := r.nodeToBlock(node)
		if block != nil {
			blocks = append(blocks, *block)
		}
	}

	return blocks
}

func (r *HTMLReader) nodeToBlock(node *htmlNode) *Block {
	switch node.tag {
	case "h1", "h2", "h3", "h4", "h5", "h6":
		level := int(node.tag[1] - '0')
		inlines := r.nodesToInlines(node.children)
		id := node.attrs["id"]
		if id == "" {
			id = makeIdentifier(inlinesToText(inlines))
		}
		return &Block{
			Type:    "Header",
			Level:   level,
			Attr:    Attr{ID: id, Classes: getClasses(node.attrs), KVPairs: [][2]string{}},
			Inlines: inlines,
		}
	case "p":
		inlines := r.nodesToInlines(node.children)
		if len(inlines) == 0 {
			return nil
		}
		return &Block{Type: "Para", Inlines: inlines}
	case "div", "section", "article", "main", "aside", "nav", "header", "footer":
		id := node.attrs["id"]
		classes := getClasses(node.attrs)
		blocks := r.nodesToBlocks(node.children)
		return &Block{
			Type:   "Div",
			Attr:   Attr{ID: id, Classes: classes, KVPairs: [][2]string{}},
			Blocks: blocks,
		}
	case "blockquote":
		blocks := r.nodesToBlocks(node.children)
		return &Block{Type: "BlockQuote", Blocks: blocks}
	case "pre":
		code := extractPreCode(node)
		lang := ""
		if len(node.children) > 0 && node.children[0].tag == "code" {
			codeNode := node.children[0]
			cls := codeNode.attrs["class"]
			if cls != "" {
				re := regexp.MustCompile(`(?:language-|sourceCode\s+)(\S+)`)
				if m := re.FindStringSubmatch(cls); m != nil {
					lang = m[1]
				} else {
					lang = cls
				}
			}
		}
		attr := emptyAttr()
		if lang != "" {
			attr.Classes = []string{lang}
		}
		return &Block{Type: "CodeBlock", Attr: attr, Code: code}
	case "hr":
		return &Block{Type: "HorizontalRule"}
	case "ul":
		var items [][]Block
		for _, child := range node.children {
			if child.tag == "li" {
				itemBlocks := r.liToBlocks(child)
				items = append(items, itemBlocks)
			}
		}
		return &Block{Type: "BulletList", Items: items}
	case "ol":
		var items [][]Block
		for _, child := range node.children {
			if child.tag == "li" {
				itemBlocks := r.liToBlocks(child)
				items = append(items, itemBlocks)
			}
		}
		la := ListAttr{Start: 1, Style: "Decimal", Delimiter: "Period"}
		if start, ok := node.attrs["start"]; ok {
			n := 0
			for _, c := range start {
				n = n*10 + int(c-'0')
			}
			la.Start = n
		}
		return &Block{Type: "OrderedList", ListAttr: la, Items: items}
	case "dl":
		var defItems []DefItem
		var currentTerm []Inline
		var currentDefs [][]Block
		for _, child := range node.children {
			if child.isText {
				continue
			}
			if child.tag == "dt" {
				if currentTerm != nil {
					defItems = append(defItems, DefItem{Term: currentTerm, Defs: currentDefs})
					currentDefs = nil
				}
				currentTerm = r.nodesToInlines(child.children)
			} else if child.tag == "dd" {
				blocks := r.nodesToBlocks(child.children)
				if len(blocks) == 0 {
					inlines := r.nodesToInlines(child.children)
					if len(inlines) > 0 {
						blocks = []Block{{Type: "Para", Inlines: inlines}}
					}
				}
				currentDefs = append(currentDefs, blocks)
			}
		}
		if currentTerm != nil {
			defItems = append(defItems, DefItem{Term: currentTerm, Defs: currentDefs})
		}
		return &Block{Type: "DefinitionList", DefItems: defItems}
	case "table":
		return r.nodeToTable(node)
	case "figure":
		return r.nodeToFigure(node)
	default:
		// Try to convert to para if it has text
		inlines := r.nodesToInlines(node.children)
		if len(inlines) > 0 {
			return &Block{Type: "Para", Inlines: inlines}
		}
	}
	return nil
}

func (r *HTMLReader) liToBlocks(node *htmlNode) []Block {
	// Check if li contains block-level elements
	hasBlock := false
	for _, child := range node.children {
		if !child.isText && isBlockElement(child.tag) {
			hasBlock = true
			break
		}
	}

	if hasBlock {
		return r.nodesToBlocks(node.children)
	}

	inlines := r.nodesToInlines(node.children)
	if len(inlines) > 0 {
		return []Block{{Type: "Plain", Inlines: inlines}}
	}
	return []Block{{Type: "Plain"}}
}

func isBlockElement(tag string) bool {
	blockElements := map[string]bool{
		"p": true, "div": true, "h1": true, "h2": true, "h3": true, "h4": true,
		"h5": true, "h6": true, "ul": true, "ol": true, "li": true, "dl": true,
		"dt": true, "dd": true, "table": true, "pre": true, "blockquote": true,
		"hr": true, "figure": true,
	}
	return blockElements[tag]
}

func (r *HTMLReader) nodeToTable(node *htmlNode) *Block {
	var headRows []TableRow
	var bodyRows []TableRow

	for _, child := range node.children {
		if child.isText {
			continue
		}
		switch child.tag {
		case "thead":
			for _, row := range child.children {
				if !row.isText && row.tag == "tr" {
					headRows = append(headRows, r.nodeToTableRow(row, true))
				}
			}
		case "tbody":
			for _, row := range child.children {
				if !row.isText && row.tag == "tr" {
					bodyRows = append(bodyRows, r.nodeToTableRow(row, false))
				}
			}
		case "tr":
			bodyRows = append(bodyRows, r.nodeToTableRow(child, false))
		}
	}

	numCols := 0
	if len(headRows) > 0 {
		numCols = len(headRows[0].Cells)
	} else if len(bodyRows) > 0 {
		numCols = len(bodyRows[0].Cells)
	}

	colSpecs := make([]ColSpec, numCols)
	for i := range colSpecs {
		colSpecs[i] = ColSpec{Align: "AlignDefault", Width: 0}
	}

	td := &TableData{
		ColSpecs: colSpecs,
		Head:     TableHead{Attr: emptyAttr(), Rows: headRows},
		Bodies:   []TableBody{{Attr: emptyAttr(), RowHead: 0, HeadRows: []TableRow{}, Rows: bodyRows}},
		Foot:     TableFoot{Attr: emptyAttr(), Rows: []TableRow{}},
	}

	return &Block{Type: "Table", Attr: emptyAttr(), Table: td}
}

func (r *HTMLReader) nodeToTableRow(node *htmlNode, isHead bool) TableRow {
	var cells []TableCell
	for _, child := range node.children {
		if child.isText {
			continue
		}
		if child.tag == "th" || child.tag == "td" {
			var cellBlocks []Block
			// Get content
			inlines := r.nodesToInlines(child.children)
			if len(inlines) > 0 {
				cellBlocks = []Block{{Type: "Plain", Inlines: inlines}}
			} else {
				cellBlocks = r.nodesToBlocks(child.children)
			}
			cells = append(cells, TableCell{
				Attr:    emptyAttr(),
				Align:   "AlignDefault",
				RowSpan: 1,
				ColSpan: 1,
				Blocks:  cellBlocks,
			})
		}
	}
	return TableRow{Attr: emptyAttr(), Cells: cells}
}

func (r *HTMLReader) nodeToFigure(node *htmlNode) *Block {
	var captionInlines []Inline
	var imgInlines []Inline

	for _, child := range node.children {
		if child.isText {
			continue
		}
		if child.tag == "figcaption" {
			captionInlines = r.nodesToInlines(child.children)
		} else if child.tag == "img" {
			src := child.attrs["src"]
			alt := child.attrs["alt"]
			title := child.attrs["title"]
			var altInlines []Inline
			if alt != "" {
				altInlines = []Inline{{Type: "Str", Text: alt}}
			}
			imgInlines = append(imgInlines, Inline{
				Type:    "Image",
				Attr:    emptyAttr(),
				Inlines: altInlines,
				Target:  Target{URL: src, Title: title},
			})
		}
	}

	captionBlocks := []Block{}
	if len(captionInlines) > 0 {
		captionBlocks = []Block{{Type: "Plain", Inlines: captionInlines}}
	}

	bodyBlocks := []Block{{Type: "Plain", Inlines: imgInlines}}

	return &Block{
		Type:   "Figure",
		Attr:   emptyAttr(),
		Blocks: bodyBlocks,
		Table:  &TableData{Caption: Caption{Blocks: captionBlocks}},
	}
}

func (r *HTMLReader) nodesToInlines(nodes []*htmlNode) []Inline {
	var inlines []Inline
	for _, node := range nodes {
		ils := r.nodeToInlines(node)
		inlines = append(inlines, ils...)
	}
	return inlines
}

func (r *HTMLReader) nodeToInlines(node *htmlNode) []Inline {
	if node.isText {
		text := unescapeHTML(node.text)
		if text == "" {
			return nil
		}
		return textToInlines(text)
	}

	switch node.tag {
	case "em", "i":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Emph", Inlines: inlines}}
	case "strong", "b":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Strong", Inlines: inlines}}
	case "del", "s", "strike":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Strikeout", Inlines: inlines}}
	case "sup":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Superscript", Inlines: inlines}}
	case "sub":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Subscript", Inlines: inlines}}
	case "code":
		text := extractTextContent(node)
		return []Inline{{Type: "Code", Attr: emptyAttr(), Text: text}}
	case "a":
		href := node.attrs["href"]
		title := node.attrs["title"]
		inlines := r.nodesToInlines(node.children)
		return []Inline{{
			Type:    "Link",
			Attr:    emptyAttr(),
			Inlines: inlines,
			Target:  Target{URL: href, Title: title},
		}}
	case "img":
		src := node.attrs["src"]
		alt := node.attrs["alt"]
		title := node.attrs["title"]
		var altInlines []Inline
		if alt != "" {
			altInlines = []Inline{{Type: "Str", Text: alt}}
		}
		return []Inline{{
			Type:    "Image",
			Attr:    emptyAttr(),
			Inlines: altInlines,
			Target:  Target{URL: src, Title: title},
		}}
	case "br":
		return []Inline{{Type: "LineBreak"}}
	case "span":
		id := node.attrs["id"]
		classes := getClasses(node.attrs)
		inlines := r.nodesToInlines(node.children)
		return []Inline{{
			Type:    "Span",
			Attr:    Attr{ID: id, Classes: classes, KVPairs: [][2]string{}},
			Inlines: inlines,
		}}
	case "q":
		inlines := r.nodesToInlines(node.children)
		return []Inline{{Type: "Quoted", QuoteType: "DoubleQuote", Inlines: inlines}}
	default:
		// For unknown inline-level elements, just get text
		return r.nodesToInlines(node.children)
	}
}

func textToInlines(text string) []Inline {
	// Split text into words with spaces
	var inlines []Inline
	words := strings.Fields(text)

	for i, word := range words {
		if i > 0 {
			inlines = append(inlines, Inline{Type: "Space"})
		}
		inlines = append(inlines, Inline{Type: "Str", Text: word})
	}

	// Preserve leading/trailing spaces as Space inlines
	if len(text) > 0 && text[0] == ' ' && len(inlines) > 0 {
		inlines = append([]Inline{{Type: "Space"}}, inlines...)
	}
	if len(text) > 0 && text[len(text)-1] == ' ' && len(inlines) > 0 {
		inlines = append(inlines, Inline{Type: "Space"})
	}

	return inlines
}

func htmlTextToInlines(text string) []Inline {
	text = unescapeHTML(text)
	return textToInlines(text)
}

func extractPreCode(node *htmlNode) string {
	if len(node.children) > 0 && node.children[0].tag == "code" {
		return extractTextContent(node.children[0])
	}
	return extractTextContent(node)
}

func extractTextContent(node *htmlNode) string {
	if node.isText {
		return unescapeHTML(node.text)
	}
	var sb strings.Builder
	for _, child := range node.children {
		sb.WriteString(extractTextContent(child))
	}
	return sb.String()
}

func getClasses(attrs map[string]string) []string {
	cls := attrs["class"]
	if cls == "" {
		return []string{}
	}
	return strings.Fields(cls)
}

func unescapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&amp;", "&")
	s = strings.ReplaceAll(s, "&lt;", "<")
	s = strings.ReplaceAll(s, "&gt;", ">")
	s = strings.ReplaceAll(s, "&quot;", `"`)
	s = strings.ReplaceAll(s, "&#39;", "'")
	s = strings.ReplaceAll(s, "&apos;", "'")
	s = strings.ReplaceAll(s, "&nbsp;", "\u00a0")
	s = strings.ReplaceAll(s, "&#8212;", "\u2014")
	s = strings.ReplaceAll(s, "&#8211;", "\u2013")
	s = strings.ReplaceAll(s, "&#8220;", "\u201c")
	s = strings.ReplaceAll(s, "&#8221;", "\u201d")
	// Handle numeric entities
	re := regexp.MustCompile(`&#(\d+);`)
	s = re.ReplaceAllStringFunc(s, func(m string) string {
		m2 := re.FindStringSubmatch(m)
		if len(m2) < 2 {
			return m
		}
		n := 0
		for _, c := range m2[1] {
			n = n*10 + int(c-'0')
		}
		return string(rune(n))
	})
	return s
}
