func makeStandaloneHTML(body string, doc *Doc, opts *Options) string {
	var sb strings.Builder

	// Get metadata
	title := getMetaString(doc.Meta, "title")
	author := getMetaString(doc.Meta, "author")
	date := getMetaString(doc.Meta, "date")
	lang := getMetaString(doc.Meta, "lang")
	abstract := getMetaString(doc.Meta, "abstract")

	// Override with command-line metadata
	for k, v := range opts.Metadata {
		switch k {
		case "title":
			title = v
		case "author":
			author = v
		case "date":
			date = v
		}
	}

	// Override with variables
	if v, ok := opts.Variables["title"]; ok {
		title = v
	}

	pagetitle := title
	if pagetitle == "" {
		pagetitle = "-"
	}
	if opts.TitlePrefix != "" {
		pagetitle = opts.TitlePrefix + " \u2013 " + pagetitle
	}

	// Build HTML
	sb.WriteString("<!DOCTYPE html>\n")
	sb.WriteString("<html xmlns=\"http://www.w3.org/1999/xhtml\"")
	if lang != "" {
		sb.WriteString(fmt.Sprintf(" lang=\"%s\" xml:lang=\"%s\"", htmlEscape(lang), htmlEscape(lang)))
	}
	sb.WriteString(">\n<head>\n")
	sb.WriteString("  <meta charset=\"utf-8\" />\n")
	sb.WriteString("  <meta name=\"generator\" content=\"pandoc\" />\n")
	sb.WriteString("  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=yes\" />\n")

	// Author(s)
	authors := getMetaList(doc.Meta, "author")
	if len(authors) == 0 && author != "" {
		authors = []string{author}
	}
	for _, a := range authors {
		sb.WriteString(fmt.Sprintf("  <meta name=\"author\" content=\"%s\" />\n", htmlEscape(a)))
	}

	// Date
	if date != "" {
		sb.WriteString(fmt.Sprintf("  <meta name=\"dcterms.date\" content=\"%s\" />\n", htmlEscape(date)))
	}

	sb.WriteString(fmt.Sprintf("  <title>%s</title>\n", htmlEscape(pagetitle)))

	// Styles
	sb.WriteString("  <style>\n")
	sb.WriteString("    " + strings.ReplaceAll(pandocCSS, "\n", "\n    ") + "\n")
	sb.WriteString("  </style>\n")

	// CSS links
	for _, css := range opts.CSS {
		sb.WriteString(fmt.Sprintf("  <link rel=\"stylesheet\" href=\"%s\" />\n", htmlEscape(css)))
	}

	// Header includes
	for _, hf := range opts.InclInHeader {
		content, err := ioutil.ReadFile(hf)
		if err == nil {
			sb.WriteString("  " + strings.TrimSpace(string(content)) + "\n")
		}
	}

	sb.WriteString("</head>\n<body>\n")

	// Before body includes
	for _, bf := range opts.InclBeforeBody {
		content, err := ioutil.ReadFile(bf)
		if err == nil {
			sb.WriteString(string(content))
		}
	}

	// Title block
	if title != "" {
		sb.WriteString("<header id=\"title-block-header\">\n")
		sb.WriteString(fmt.Sprintf("<h1 class=\"title\">%s</h1>\n", htmlEscape(title)))

		subtitle := getMetaString(doc.Meta, "subtitle")
		if subtitle != "" {
			sb.WriteString(fmt.Sprintf("<p class=\"subtitle\">%s</p>\n", htmlEscape(subtitle)))
		}

		for _, a := range authors {
			sb.WriteString(fmt.Sprintf("<p class=\"author\">%s</p>\n", htmlEscape(a)))
		}

		if date != "" {
			sb.WriteString(fmt.Sprintf("<p class=\"date\">%s</p>\n", htmlEscape(date)))
		}

		if abstract != "" {
			abstractTitle := getTranslation("abstract-title", "en")
			sb.WriteString("<div class=\"abstract\">\n")
			sb.WriteString(fmt.Sprintf("<div class=\"abstract-title\">%s</div>\n", abstractTitle))
			sb.WriteString(abstract + "\n")
			sb.WriteString("</div>\n")
		}

		sb.WriteString("</header>\n")
	}

	sb.WriteString(body)

	// After body includes
	for _, af := range opts.InclAfterBody {
		content, err := ioutil.ReadFile(af)
		if err == nil {
			sb.WriteString(string(content))
		}
	}

	sb.WriteString("</body>\n</html>\n")

	return sb.String()
}

