	sb.WriteString("\\hypersetup{\n")
	if title != "" {
		sb.WriteString(fmt.Sprintf("  pdftitle={%s},\n", latexEscape(title)))
	}
	if len(authors) > 0 {
		sb.WriteString(fmt.Sprintf("  pdfauthor={%s},\n", latexEscape(strings.Join(authors, ", "))))
	}
	sb.WriteString("  hidelinks,\n")
	sb.WriteString("  pdfcreator={LaTeX via pandoc}}\n")
	if title != "" {
		sb.WriteString(fmt.Sprintf("\\title{%s}\n", latexEscape(title)))
	}
	if len(authors) > 0 {
		authorStr := strings.Join(authors, " \\and ")
		sb.WriteString(fmt.Sprintf("\\author{%s}\n", latexEscape(authorStr)))
	}
	if date != "" {
		sb.WriteString(fmt.Sprintf("\\date{%s}\n", latexEscape(date)))
	} else {
		sb.WriteString("\\date{}\n")
	}
	sb.WriteString("\\begin{document}\n")
	if title != "" {
		sb.WriteString("\\maketitle\n")
	}
	sb.WriteString(body)
	sb.WriteString("\\end{document}\n")

	return sb.String()
}

func getMetaString(meta map[string]MetaVal, key string) string {
	mv, ok := meta[key]
	if !ok {
		return ""
	}
	switch mv.Type {
	case "MetaInlines":
		return inlinesToText(mv.Inlines)
	case "MetaString":
		return mv.Str
	}
	return ""
}

func getMetaList(meta map[string]MetaVal, key string) []string {
	mv, ok := meta[key]
	if !ok {
		return nil
	}
	switch mv.Type {
	case "MetaList":
		var result []string
		for _, item := range mv.List {
			result = append(result, metaValToText(item))
		}
		return result
	case "MetaInlines":
		return []string{inlinesToText(mv.Inlines)}
	case "MetaString":
		return []string{mv.Str}
	}
	return nil
}

func metaValToText(mv MetaVal) string {
	switch mv.Type {
	case "MetaInlines":
		return inlinesToText(mv.Inlines)
	case "MetaString":
		return mv.Str
	}
	return ""
}

func getTranslation(key, lang string) string {
