func getMetaString(meta map[string]MetaVal, key string) string {
	mv, ok := meta[key]
	if !ok {
		return ""
	}
	switch mv.Type {
	case "MetaInlines":
		return inlinesToText(mv.Inlines)
	case "MetaString":
		return mv.Str
	}
	return ""
}

func getMetaList(meta map[string]MetaVal, key string) []string {
	mv, ok := meta[key]
	if !ok {
		return nil
	}
	switch mv.Type {
	case "MetaList":
		var result []string
		for _, item := range mv.List {
			result = append(result, metaValToText(item))
		}
		return result
	case "MetaInlines":
		return []string{inlinesToText(mv.Inlines)}
	case "MetaString":
		return []string{mv.Str}
	}
	return nil
}

func metaValToText(mv MetaVal) string {
	switch mv.Type {
	case "MetaInlines":
		return inlinesToText(mv.Inlines)
	case "MetaString":
		return mv.Str
	}
	return ""
}

func getTranslation(key, lang string) string {
	translations := map[string]map[string]string{
		"en": {
			"abstract-title": "Abstract",
			"toc-title":      "Table of Contents",
			"references-title": "References",
			"figure":         "Figure",
			"table":          "Table",
		},
	}

	if t, ok := translations[lang]; ok {
		if v, ok := t[key]; ok {
			return v
		}
	}
	if t, ok := translations["en"]; ok {
		if v, ok := t[key]; ok {
			return v
		}
	}
