package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"strings"
)

func main() {
	args := os.Args[1:]

	opts, err := parseArgs(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if opts.DumpArgs {
		// Print output file (- for stdout)
		outFile := opts.Output
		if outFile == "" {
			outFile = "-"
		}
		fmt.Println(outFile)
		for _, f := range opts.Files {
			fmt.Println(f)
		}
		return
	}

	if opts.IgnoreArgs {
		return
	}

	// Read input
	var input string
	if len(opts.Files) == 0 {
		// Read from stdin
		data, err := ioutil.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error reading stdin:", err)
			os.Exit(1)
		}
		input = string(data)
	} else {
		var inputs []string
		for _, f := range opts.Files {
			data, err := ioutil.ReadFile(f)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Error reading file:", f, err)
				os.Exit(1)
			}
			inputs = append(inputs, string(data))
		}
		input = strings.Join(inputs, "\n\n")
	}

	// Determine input/output formats from file extensions if not specified
	if len(opts.Files) > 0 {
		f := opts.Files[0]
		if opts.From == "markdown" {
			// Might need to change based on extension
			if strings.HasSuffix(f, ".html") || strings.HasSuffix(f, ".htm") {
				opts.From = "html"
			} else if strings.HasSuffix(f, ".rst") {
				opts.From = "rst"
			} else if strings.HasSuffix(f, ".tex") || strings.HasSuffix(f, ".latex") {
				opts.From = "latex"
			} else if strings.HasSuffix(f, ".json") {
				opts.From = "json"
			} else if strings.HasSuffix(f, ".org") {
				opts.From = "org"
			}
		}
		if opts.Output != "" && opts.To == "html" {
			// Determine output format from output file extension
			if strings.HasSuffix(opts.Output, ".tex") || strings.HasSuffix(opts.Output, ".latex") {
				opts.To = "latex"
			} else if strings.HasSuffix(opts.Output, ".rst") {
				opts.To = "rst"
			} else if strings.HasSuffix(opts.Output, ".md") || strings.HasSuffix(opts.Output, ".markdown") {
				opts.To = "markdown"
			} else if strings.HasSuffix(opts.Output, ".txt") {
				opts.To = "plain"
			} else if strings.HasSuffix(opts.Output, ".json") {
				opts.To = "json"
			} else if strings.HasSuffix(opts.Output, ".pdf") {
				opts.To = "pdf"
			}
		}
	}

	// Parse input
	doc, err := parseInput(input, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error parsing input:", err)
		os.Exit(1)
	}

	// Apply metadata overrides
	for k, v := range opts.Metadata {
		doc.Meta[k] = MetaVal{Type: "MetaInlines", Inlines: []Inline{{Type: "Str", Text: v}}}
	}

	// Generate output
	output, err := generateOutput(doc, opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error generating output:", err)
		os.Exit(1)
	}

	// Write output
	if opts.Output == "" || opts.Output == "-" {
		fmt.Print(output)
	} else {
		err = ioutil.WriteFile(opts.Output, []byte(output), 0644)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Error writing output:", err)
			os.Exit(1)
		}
	}
}

func parseInput(input string, opts *Options) (*Doc, error) {
