// Simple RST parser
func parseRST(input string, opts *Options) (*Doc, error) {
	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	lines := strings.Split(input, "\n")
	ls := &lineState{lines: lines}

	for !ls.done() {
		line := ls.peek()
		if isBlankLine(line) {
			ls.next()
			continue
		}

		// Check for section header (underlined)
		if ls.pos+1 < len(ls.lines) {
			nextLine := ls.lines[ls.pos+1]
			if isRSTUnderline(nextLine) && len(nextLine) >= len(strings.TrimSpace(line)) {
				title := strings.TrimSpace(ls.next())
				ls.next() // skip underline
				level := 1 // simplified
				doc.Blocks = append(doc.Blocks, Block{
					Type:    "Header",
					Level:   level,
					Attr:    Attr{ID: makeIdentifier(title), Classes: []string{}, KVPairs: [][2]string{}},
					Inlines: []Inline{{Type: "Str", Text: title}},
				})
				continue
			}
		}

		// Collect paragraph
		var paraLines []string
		for !ls.done() && !isBlankLine(ls.peek()) {
			paraLines = append(paraLines, ls.next())
		}

		if len(paraLines) > 0 {
			text := strings.Join(paraLines, " ")
			doc.Blocks = append(doc.Blocks, Block{
				Type:    "Para",
				Inlines: []Inline{{Type: "Str", Text: text}},
			})
		}
	}

	return doc, nil
}

func isRSTUnderline(line string) bool {
	if len(line) == 0 {
		return false
	}
	c := line[0]
	for i := 1; i < len(line); i++ {
		if line[i] != c {
			return false
		}
	}
	underlineChars := "=-~^'\"#*+<>_"
	return strings.ContainsRune(underlineChars, rune(c))
}

// Simple LaTeX parser
func parseLaTeX(input string, opts *Options) (*Doc, error) {
	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	// Basic LaTeX parsing - extract text content
	// Remove LaTeX commands
	re := regexp.MustCompile(`\\[a-zA-Z]+(\{[^}]*\})?`)
	text := re.ReplaceAllStringFunc(input, func(m string) string {
		// Keep content of some commands
		if strings.HasPrefix(m, "\\textbf{") || strings.HasPrefix(m, "\\emph{") {
			return strings.TrimSuffix(strings.TrimPrefix(m, "\\textbf{"), "}")
		}
		return " "
	})

	paras := strings.Split(text, "\n\n")
	for _, para := range paras {
		para = strings.TrimSpace(para)
		if para == "" {
			continue
		}
		doc.Blocks = append(doc.Blocks, Block{
			Type:    "Para",
			Inlines: []Inline{{Type: "Str", Text: para}},
		})
	}

	return doc, nil
}

// Simple Org mode parser
func parseOrg(input string, opts *Options) (*Doc, error) {
	doc := &Doc{
		Meta:   make(map[string]MetaVal),
		Blocks: []Block{},
	}

	lines := strings.Split(input, "\n")
	ls := &lineState{lines: lines}

	for !ls.done() {
		line := ls.peek()

		if isBlankLine(line) {
			ls.next()
			continue
		}

		// Org header
		if strings.HasPrefix(line, "* ") || strings.HasPrefix(line, "** ") ||
			strings.HasPrefix(line, "*** ") {
			level := 0
			for i, c := range line {
				if c == '*' {
					level++
				} else if c == ' ' {
					_ = i
					break
				} else {
					break
				}
			}
			title := strings.TrimSpace(line[level+1:])
			ls.next()
			doc.Blocks = append(doc.Blocks, Block{
				Type:    "Header",
				Level:   level,
				Attr:    Attr{ID: makeIdentifier(title), Classes: []string{}, KVPairs: [][2]string{}},
				Inlines: []Inline{{Type: "Str", Text: title}},
			})
			continue
		}

		var paraLines []string
		for !ls.done() && !isBlankLine(ls.peek()) {
			paraLines = append(paraLines, ls.next())
		}

		if len(paraLines) > 0 {
			text := strings.Join(paraLines, " ")
			doc.Blocks = append(doc.Blocks, Block{
				Type:    "Para",
				Inlines: []Inline{{Type: "Str", Text: text}},
			})
		}
	}

	return doc, nil
}

