// Collect footnote definitions
func (p *MdParser) collectFootnotes(input string) string {
	// Match [^label]: content (possibly multi-line)
	lines := strings.Split(input, "\n")
	var resultLines []string
	i := 0
	for i < len(lines) {
		line := lines[i]
		fnRegex := regexp.MustCompile(`^\[\^([^\]]+)\]:\s+(.*)$`)
		if m := fnRegex.FindStringSubmatch(line); m != nil {
			label := m[1]
			content := m[2]
			i++
			// Collect continuation lines (indented)
			for i < len(lines) && (strings.HasPrefix(lines[i], "    ") || strings.HasPrefix(lines[i], "\t") || lines[i] == "") {
				if lines[i] == "" {
					break
				}
				content += "\n" + strings.TrimPrefix(strings.TrimPrefix(lines[i], "    "), "\t")
				i++
			}
			p.footnotes[label] = strings.TrimSpace(content)
			// Remove from output (don't append to resultLines)
			continue
		}
		resultLines = append(resultLines, line)
		i++
	}
	return strings.Join(resultLines, "\n")
}
GOEOF
