# The wrapping in pandoc's HTML output is based on a "pretty printing" algorithm
# that wraps text at the column limit. It wraps at:
# - Spaces between words
# - Between HTML tags when there's a newline opportunity

# Let me implement a simple HTML line wrapping function
# The approach: 
# - Track current column position
# - When we would exceed 72 chars, insert a newline
# - But only at "safe" positions (not inside tags, not inside attributes)

# Let me add an HTML wrapper to the writer
cat >> pandoc-impl/html_writer.go << 'GOEOF'

// wrapHTMLLines wraps HTML output at the given column limit
func wrapHTMLLines(html string, cols int) string {
	if cols <= 0 {
		return html
	}

	var result strings.Builder
	currentLen := 0
	inTag := false

	i := 0
	for i < len(html) {
		c := html[i]

		if c == '<' {
			inTag = true
			result.WriteByte(c)
			currentLen++
			i++
			continue
		}

		if c == '>' {
			inTag = false
			result.WriteByte(c)
			currentLen++
			i++
			continue
		}

		if c == '\n' {
			result.WriteByte(c)
			currentLen = 0
			i++
			continue
		}

		if !inTag && c == ' ' && currentLen > 0 {
			// Check if next word would exceed column limit
			nextSpace := strings.IndexByte(html[i+1:], ' ')
			nextNL := strings.IndexByte(html[i+1:], '\n')
			nextTag := strings.IndexByte(html[i+1:], '<')

			nextBreak := nextSpace
			if nextNL >= 0 && (nextBreak < 0 || nextNL < nextBreak) {
				nextBreak = nextNL
			}
			if nextTag >= 0 && (nextBreak < 0 || nextTag < nextBreak) {
				nextBreak = nextTag
			}

			wordLen := nextBreak
			if wordLen < 0 {
				wordLen = len(html) - i - 1
			}

			if currentLen + 1 + wordLen > cols {
				result.WriteByte('\n')
				currentLen = 0
				i++
				// Skip leading space on new line
				continue
			}
		}

		result.WriteByte(c)
		currentLen++
		i++
	}

	return result.String()
}
GOEOF
echo "Added wrapHTMLLines"

