// wrapHTMLOutput wraps HTML at column limit, similar to pandoc's behavior
func wrapHTMLOutput(html string, cols int) string {
	if cols <= 0 {
		cols = 72
	}

	lines := strings.Split(html, "\n")
	var result []string

	for _, line := range lines {
		if len(line) <= cols {
			result = append(result, line)
			continue
		}

		// Need to wrap this line
		wrapped := wrapHTMLLine(line, cols)
		result = append(result, strings.Split(wrapped, "\n")...)
	}

	return strings.Join(result, "\n")
}

func wrapHTMLLine(line string, cols int) string {
	if len(line) <= cols {
		return line
	}

	var result strings.Builder
	currentLen := 0
	inTag := false
	lastBreak := -1
	lastBreakLen := 0

	i := 0
	for i < len(line) {
		c := line[i]

		if c == '<' {
			inTag = true
		} else if c == '>' {
			inTag = false
			// After closing a tag, we can break
			if i+1 < len(line) && line[i+1] == ' ' || i+1 == len(line) {
				// potential break point
			}
		}

		if !inTag && c == ' ' && currentLen >= cols/2 {
			// Check if we should wrap here
			if currentLen >= cols-10 {
				// Wrap here
				result.WriteByte('\n')
				currentLen = 0
				i++
				continue
			}
			lastBreak = result.Len()
			lastBreakLen = currentLen
		}

		if currentLen > cols && lastBreak > 0 {
			// Insert newline at last break point
			s := result.String()
			return s[:lastBreak] + "\n" + wrapHTMLLine(strings.TrimLeft(s[lastBreak:]+line[i:], " "), cols)
		}

		result.WriteByte(c)
		currentLen++
		i++
	}

	return result.String()
}
