// wrapHTMLPara wraps HTML paragraph content at column limit
// Starting position is already after "<p>" (3 chars)
func wrapHTMLPara(content string, cols int) string {
	if cols <= 0 {
		cols = 72
	}

	// Current line length starts at 3 (for "<p>")
	startLen := 3
	return wrapHTMLContent(content, cols, startLen)
}

// wrapHTMLContent wraps HTML content with awareness of HTML tags
// currentLen is the current position on the line
func wrapHTMLContent(content string, cols int, currentLen int) string {
	if len(content) + currentLen <= cols {
		return content
	}

	var result strings.Builder
	pos := 0

	for pos < len(content) {
		// Find next word boundary or tag
		if content[pos] == '<' {
			// Find end of tag
			end := strings.IndexByte(content[pos:], '>')
			if end < 0 {
				result.WriteString(content[pos:])
				return result.String()
			}
			tagLen := end + 1
			tag := content[pos : pos+tagLen]

			if currentLen+tagLen > cols && currentLen > 0 {
				// Can we break before the tag?
				// Only if tag is not an opening inline tag preceded by space
				result.WriteByte('\n')
				currentLen = 0
			}
			result.WriteString(tag)
			currentLen += tagLen
			pos += tagLen
			continue
		}

		// Find next space or tag
		nextSpace := strings.IndexByte(content[pos:], ' ')
		nextTag := strings.IndexByte(content[pos:], '<')
		nextNL := strings.IndexByte(content[pos:], '\n')

		end := -1
		if nextSpace >= 0 {
			end = nextSpace
		}
		if nextTag >= 0 && (end < 0 || nextTag < end) {
			end = nextTag
		}
		if nextNL >= 0 && (end < 0 || nextNL < end) {
			end = nextNL
		}

		if end < 0 {
			// Rest of content
			rest := content[pos:]
			if currentLen+len(rest) > cols+10 {
				// Force wrap
				result.WriteString(rest)
			} else {
				result.WriteString(rest)
			}
			return result.String()
		}

		// Process up to this point
		word := content[pos : pos+end]
		if currentLen+len(word) > cols && currentLen > 3 {
			result.WriteByte('\n')
			currentLen = 0
		}
		result.WriteString(word)
		currentLen += len(word)
		pos += end

		// Handle the separator
		if pos < len(content) {
			sep := content[pos]
			if sep == '\n' {
				result.WriteByte('\n')
				currentLen = 0
				pos++
			} else if sep == ' ' {
				// Check if next word fits
				// Look ahead
				nextEnd := pos + 1
				for nextEnd < len(content) && content[nextEnd] != ' ' && content[nextEnd] != '<' && content[nextEnd] != '\n' {
					nextEnd++
				}
				nextWordLen := nextEnd - pos - 1

				// Check what follows
				if nextEnd < len(content) && content[nextEnd] == '<' {
					// Next is a tag - include space
					result.WriteByte(' ')
					currentLen++
					pos++
				} else if currentLen+1+nextWordLen > cols {
					result.WriteByte('\n')
					currentLen = 0
					pos++ // skip space
				} else {
					result.WriteByte(' ')
					currentLen++
					pos++
				}
			}
		}
	}

	return result.String()
}
