func wrapHTMLText(content string, cols int, startLen int) string {
	var result strings.Builder
	lineLen := startLen
	pos := 0

	for pos < len(content) {
		// Handle HTML tags
		if content[pos] == '<' {
			end := strings.Index(content[pos:], ">")
			if end < 0 {
				result.WriteString(content[pos:])
				return result.String()
			}
			tag := content[pos : pos+end+1]
			tagLen := len(tag)

			// For opening tags with attributes, consider splitting
			if !strings.HasPrefix(tag, "</") && !strings.HasPrefix(tag, "<!") {
				// Check if tag name + first attr would exceed limit
				spaceIdx := strings.Index(tag[1:], " ")
				if spaceIdx >= 0 && lineLen + spaceIdx + 1 + 1 <= cols && lineLen + tagLen > cols {
					// Write "<tagname\\n...rest..."
					result.WriteString(tag[:spaceIdx+1])
					result.WriteByte(\'\\n\')
					result.WriteString(tag[spaceIdx+2:])
					lineLen = tagLen - spaceIdx - 2
					pos += tagLen
					continue
				}
