				i++ // skip {
				for i < len(math) && math[i] != '}' {
					subContent.WriteByte(math[i])
					i++
				}
				if i < len(math) { i++ } // skip }
			} else {
				subContent.WriteByte(math[i])
				i++
			}
			result.WriteString("<sub>")
			result.WriteString(italicizeLetters(subContent.String()))
			result.WriteString("</sub>")
			continue
		}

		// Regular character
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			result.WriteString("<em>")
			result.WriteByte(c)
			result.WriteString("</em>")
		} else if c == ' ' {
			result.WriteString(" ")
		} else {
			result.WriteByte(c)
		}
		i++
	}
	return result.String()
}

func italicizeLetters(s string) string {
	var result strings.Builder
	for _, c := range s {
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			result.WriteString("<em>" + string(c) + "</em>")
		} else {
			result.WriteRune(c)
		}
	}
	return result.String()
}

