# The parseAutolink function has two problems:
# 1. When pos >= len or p[pos] != '>' -> resets to start and returns nil (HANG!)
# 2. When it finds a tag but it's not a URL -> resets to start and returns nil (HANG!)

# Fix: always consume the '<' character, even when failing

python3 << 'PYEOF'
with open('pandoc-impl/inline_parser.go', 'r') as f:
    content = f.read()

start_idx = content.find('func (p *inlineParser) parseAutolink()')
end_idx = content.find('\nfunc (p *inlineParser) parseHTMLEntity', start_idx)
print(f"parseAutolink: {start_idx} to {end_idx}")
print(content[start_idx:end_idx])

new_func = '''func (p *inlineParser) parseAutolink() *Inline {
	if p.pos+1 >= len(p.text) {
		// Consume the < and return as literal
		p.pos++
		return &Inline{Type: "Str", Text: "<"}
	}

	startPos := p.pos
	p.pos++ // skip <

	// Check for HTML comment
	if p.pos+2 < len(p.text) && p.text[p.pos:p.pos+3] == "!--" {
		// HTML comment - find closing -->
		end := strings.Index(p.text[p.pos:], "-->")
		if end >= 0 {
			raw := p.text[startPos : p.pos+end+3]
			p.pos = p.pos + end + 3
			return &Inline{Type: "RawInline", Format: "html", Text: raw}
		}
	}

	// Check for URL or email
	urlStart := p.pos
	for p.pos < len(p.text) && p.text[p.pos] != '>' && p.text[p.pos] != '<' && p.text[p.pos] != ' ' {
		p.pos++
	}

	if p.pos >= len(p.text) || p.text[p.pos] != '>' {
		// No closing > - restore to just after < and return < as literal
		p.pos = startPos + 1
		return &Inline{Type: "Str", Text: "<"}
	}

	content2 := p.text[urlStart:p.pos]
	p.pos++ // skip >

	// Check if it's a valid URL or email autolink
	if strings.Contains(content2, "://") || (strings.Contains(content2, "@") && !strings.ContainsAny(content2, " \t\n<>")) {
		isEmail := strings.Contains(content2, "@") && !strings.Contains(content2, "://")
		url := content2
		if isEmail {
			url = "mailto:" + content2
		}
		return &Inline{
			Type:    "Link",
			Attr:    emptyAttr(),
			Inlines: []Inline{{Type: "Str", Text: content2}},
			Target:  Target{URL: url},
		}
	}

	// HTML tag or unknown angle bracket content
	fullTag := "<" + content2 + ">"
	return &Inline{Type: "RawInline", Format: "html", Text: fullTag}
}
'''

content = content[:start_idx] + new_func + content[end_idx:]
with open('pandoc-impl/inline_parser.go', 'w') as f:
    f.write(content)
print("Done")
