# The parseHTMLEntity has "p.pos = start; return nil" after the '&' is NOT consumed!
# This will cause a hang when '&' is not followed by '#' or a valid entity.
# Let me fix it:

python3 << 'PYEOF'
with open('pandoc-impl/inline_parser.go', 'r') as f:
    content = f.read()

old_entity = '''func (p *inlineParser) parseHTMLEntity() *Inline {
	start := p.pos
	if p.pos+1 >= len(p.text) || p.text[p.pos+1] != '#' {
		// Named entity like &amp;
		p.pos++
		entityStart := p.pos
		for p.pos < len(p.text) && (isLetter(p.text[p.pos]) || isDigit(p.text[p.pos])) {
			p.pos++
		}
		if p.pos < len(p.text) && p.text[p.pos] == ';' {
			entity := p.text[entityStart:p.pos]
			p.pos++
			decoded := decodeHTMLEntity(entity)
			if decoded != "" {
				return &Inline{Type: "Str", Text: decoded}
			}
		}
		p.pos = start
		return nil
	}
	return nil
}'''

new_entity = '''func (p *inlineParser) parseHTMLEntity() *Inline {
	if p.pos+1 >= len(p.text) {
		p.pos++
		return &Inline{Type: "Str", Text: "&"}
	}

	if p.text[p.pos+1] == '#' {
		// Numeric entity &#123; or &#x1a;
		p.pos += 2
		if p.pos < len(p.text) && (p.text[p.pos] == 'x' || p.text[p.pos] == 'X') {
			// Hex entity
			p.pos++
			start := p.pos
			for p.pos < len(p.text) && (isDigit(p.text[p.pos]) || (p.text[p.pos] >= 'a' && p.text[p.pos] <= 'f') || (p.text[p.pos] >= 'A' && p.text[p.pos] <= 'F')) {
				p.pos++
			}
			if p.pos < len(p.text) && p.text[p.pos] == ';' {
				hex := p.text[start:p.pos]
				p.pos++
				var n int64
				fmt.Sscanf(hex, "%x", &n)
				return &Inline{Type: "Str", Text: string(rune(n))}
			}
		} else {
			// Decimal entity
			start := p.pos
			for p.pos < len(p.text) && isDigit(p.text[p.pos]) {
				p.pos++
			}
			if p.pos < len(p.text) && p.text[p.pos] == ';' {
				numStr := p.text[start:p.pos]
				p.pos++
				var n int64
				fmt.Sscanf(numStr, "%d", &n)
				return &Inline{Type: "Str", Text: string(rune(n))}
			}
		}
		// Invalid - return &# as literal
		return &Inline{Type: "Str", Text: "&#"}
	}

	// Named entity like &amp;
	p.pos++ // skip &
	entityStart := p.pos
	for p.pos < len(p.text) && (isLetter(p.text[p.pos]) || isDigit(p.text[p.pos])) {
		p.pos++
	}
	if p.pos < len(p.text) && p.text[p.pos] == ';' {
		entity := p.text[entityStart:p.pos]
		p.pos++
		decoded := decodeHTMLEntity(entity)
		if decoded != "" {
			return &Inline{Type: "Str", Text: decoded}
		}
		// Unknown entity - return as-is
		return &Inline{Type: "Str", Text: "&" + entity + ";"}
	}
	// No semicolon - return & as literal and backtrack
	p.pos = entityStart
	return &Inline{Type: "Str", Text: "&"}
}'''

