			parsed := inner.parse()
			return &Inline{Type: "Strong", Inlines: parsed}
		}
		p.pos = start + count
	}

	if count >= 1 {
		p.pos = start + 1
		// Try *emph*
		delim := string([]byte{c})
		content, ok := p.parseUntilDelim(delim)
		if ok {
