		savedPos := p.pos
		p.pos = start + 3
		content, ok := p.parseUntilDelim(delim)
		if ok {
			inner := &inlineParser{text: content, pos: 0, refs: p.refs, footnotes: p.footnotes}
			parsed := inner.parse()
			// Advance remaining unused asterisks
			remaining := count - 3
			if remaining > 0 {
				// Put back unused asterisks by not consuming them
				_ = remaining
			}
			return &Inline{Type: "Strong", Inlines: []Inline{
				{Type: "Emph", Inlines: parsed},
			}}
		}
		p.pos = savedPos
	}

